  "stop_score" integer default 50 not null,
  "resource_score" integer default 50 not null,
  "time_score" integer default 50 not null,
  "detail" jsonb default '{}'::jsonb not null,
  "created_at" timestamp with time zone default now() not null
);

create table public."oot_player_profiles" (
  "user_id" uuid not null,
  "tagline" text default ''::text not null,
  "stats_visibility" text default 'friends'::text not null,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null
);

create table public."oot_player_stats" (
  "user_id" uuid not null,
  "one_point" integer default 0 not null,
  "peak_one_point" integer default 0 not null,
  "tier_key" text default 'number_seed'::text not null,
  "point_matches" integer default 0 not null,
  "wins" integer default 0 not null,
  "draws" integer default 0 not null,
  "losses" integer default 0 not null,
  "current_win_streak" integer default 0 not null,
  "max_win_streak" integer default 0 not null,
  "beginner_protection_remaining" integer default 10 not null,
  "exact_hits" integer default 0 not null,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null
);

create table public."oot_point_ledger" (
  "id" bigint generated by default as identity not null,
  "settlement_key" uuid not null,
  "online_match_id" uuid,
  "user_id" uuid not null,
  "opponent_user_id" uuid,
  "source_mode" text not null,
  "result_type" text not null,
  "point_before" integer not null,
  "base_delta" integer not null,
  "streak_bonus" integer default 0 not null,
  "protection_amount" integer default 0 not null,
  "final_delta" integer not null,
  "point_after" integer not null,
  "peak_after" integer not null,
  "tier_before" text not null,
  "tier_after" text not null,
  "beginner_protection_applied" boolean default false not null,
  "tier_floor_applied" boolean default false not null,
  "exact_hit" boolean default false not null,
  "reason" text not null,
  "rules_version" text default 'one_point_v1'::text not null,
  "created_at" timestamp with time zone default now() not null
);

create table public."oot_presence_sessions" (
  "user_id" uuid not null,
  "device_id" text not null,
  "activity_context" text default 'app'::text not null,
  "last_seen_at" timestamp with time zone default now() not null,
  "game_ready_until" timestamp with time zone,
  "current_match_id" uuid,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null
);

create table public."oot_push_subscriptions" (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "device_id" text not null,
  "endpoint" text not null,
  "p256dh" text not null,
  "auth_secret" text not null,
  "user_agent" text,
  "enabled" boolean default true not null,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  "last_used_at" timestamp with time zone
);

create table public."oot_random_match_queue" (
  "user_id" uuid not null,
  "status" text default 'waiting'::text not null,
  "joined_at" timestamp with time zone default now() not null,
  "heartbeat_at" timestamp with time zone default now() not null,
  "match_id" uuid,
  "matched_at" timestamp with time zone,
  "updated_at" timestamp with time zone default now() not null
);

create table public."oot_reward_unlocks" (
  "user_id" uuid not null,
  "reward_key" text not null,
  "unlock_point" integer not null,
  "unlocked_at" timestamp with time zone default now() not null
);

