-- ---- 3) functions ----
CREATE OR REPLACE FUNCTION public._oot_award_acorns_for_user(p_user_id uuid, p_source_type text, p_source_id text, p_amount integer, p_result text, p_reason text DEFAULT ''::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_existing public.oot_acorn_transactions%rowtype;
  v_wallet public.oot_acorn_wallets%rowtype;
begin
  if p_user_id is null then
    raise exception 'ACORN_USER_REQUIRED';
  end if;
  if coalesce(trim(p_source_type), '') = '' or coalesce(trim(p_source_id), '') = '' then
    raise exception 'ACORN_SOURCE_REQUIRED';
  end if;
  if p_amount < 0 then
    raise exception 'INVALID_ACORN_AMOUNT';
  end if;

  insert into public.oot_acorn_wallets (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  -- 사용자 지갑 행 잠금: 같은 결과가 동시에 정산돼도 중복 지급 방지
  select * into v_wallet
  from public.oot_acorn_wallets
  where user_id = p_user_id
  for update;

  select * into v_existing
  from public.oot_acorn_transactions
  where user_id = p_user_id
    and source_type = p_source_type
    and source_id = p_source_id;

  if found then
    return jsonb_build_object(
      'balance', v_wallet.balance,
      'lifetimeEarned', v_wallet.lifetime_earned,
      'rewardAmount', greatest(v_existing.amount, 0),
      'result', coalesce(v_existing.metadata->>'result', p_result, ''),
      'awarded', false,
      'sourceType', p_source_type
    );
  end if;

  update public.oot_acorn_wallets
  set balance = balance + p_amount,
      lifetime_earned = lifetime_earned + greatest(p_amount, 0),
      updated_at = now()
  where user_id = p_user_id
  returning * into v_wallet;

  insert into public.oot_acorn_transactions (
    user_id, amount, balance_after, source_type, source_id, reason, metadata
  ) values (
    p_user_id,
    p_amount,
    v_wallet.balance,
    p_source_type,
    p_source_id,
    coalesce(p_reason, ''),
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('result', p_result)
  );

  return jsonb_build_object(
    'balance', v_wallet.balance,
    'lifetimeEarned', v_wallet.lifetime_earned,
    'rewardAmount', greatest(p_amount, 0),
    'result', p_result,
    'awarded', true,
    'sourceType', p_source_type
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public._oot_award_finished_match_acorns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_p1_result text;
  v_p2_result text;
  v_p1_amount integer;
  v_p2_amount integer;
  v_meta jsonb;
begin
  if new.status <> 'finished' then
    return new;
  end if;

  if new.winner_id is null then
    v_p1_result := 'draw';
    v_p2_result := 'draw';
    v_p1_amount := 2;
    v_p2_amount := 2;
  elsif new.winner_id = new.player_one_id then
    v_p1_result := 'win';
    v_p2_result := 'lose';
    v_p1_amount := 3;
    v_p2_amount := 1;
  else
    v_p1_result := 'lose';
    v_p2_result := 'win';
    v_p1_amount := 1;
    v_p2_amount := 3;
  end if;

  v_meta := jsonb_build_object(
    'mode', coalesce(new.battle_mode, 'casual'),
    'matchSource', coalesce(new.match_source, 'friend'),
    'roundNumber', coalesce(new.round_number, 1)
  );

  begin
    perform public._oot_award_acorns_for_user(
      new.player_one_id,
      'player_match',
      new.id::text,
      v_p1_amount,
      v_p1_result,
      '원오브텐 사용자 대전',
      v_meta
    );
  exception when others then
    -- 재화 보상 오류가 원오브텐 경기 종료 자체를 막지 않게 합니다.
    raise warning 'OOT_ACORN_P1_REWARD_SKIPPED match=% error=%', new.id, sqlerrm;
  end;

  begin
    perform public._oot_award_acorns_for_user(
      new.player_two_id,
      'player_match',
      new.id::text,
      v_p2_amount,
      v_p2_result,
      '원오브텐 사용자 대전',
      v_meta
    );
  exception when others then
    raise warning 'OOT_ACORN_P2_REWARD_SKIPPED match=% error=%', new.id, sqlerrm;
  end;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public._oot_award_my_acorns(p_source_type text, p_source_id text, p_amount integer, p_result text, p_reason text DEFAULT ''::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  return public._oot_award_acorns_for_user(
    v_user_id,
    p_source_type,
    p_source_id,
    p_amount,
    p_result,
    p_reason,
    p_metadata
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public._oot_insert_player_game_record(p_user_id uuid, p_source_type text, p_source_id text, p_mode text, p_battle_mode text, p_difficulty text, p_opponent_personality text, p_result text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_id bigint;
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_manual_stop boolean := lower(coalesce(v_payload->>'manualStop', 'false')) = 'true';
  v_stop_distance integer;
  v_avg_decision integer;
begin
  if p_user_id is null then raise exception 'OOT_PROFILE_USER_REQUIRED'; end if;
  if coalesce(trim(p_source_id), '') = '' then raise exception 'OOT_PROFILE_SOURCE_REQUIRED'; end if;
  if p_result not in ('win', 'draw', 'lose') then raise exception 'OOT_PROFILE_RESULT_INVALID'; end if;

  begin
    v_stop_distance := nullif(v_payload->>'stopDistance', '')::integer;
  exception when others then
    v_stop_distance := null;
  end;
  if v_stop_distance is not null then v_stop_distance := greatest(0, least(9999, v_stop_distance)); end if;

  begin
    v_avg_decision := nullif(v_payload->>'avgDecisionMs', '')::integer;
  exception when others then
    v_avg_decision := null;
  end;
  if v_avg_decision is not null then v_avg_decision := greatest(0, least(120000, v_avg_decision)); end if;

  insert into public.oot_player_game_records (
    user_id, source_type, source_id, mode, battle_mode, difficulty,
    opponent_personality, result, final_value, final_distance, opponent_distance,
    operations_used, draws_used, manual_stop, stop_distance, timeouts,
    avg_decision_ms, division_remainder_uses,
    calculation_score, distance_score, stop_score, resource_score, time_score, detail
  ) values (
    p_user_id,
    p_source_type,
    left(trim(p_source_id), 160),
    p_mode,
    nullif(left(trim(coalesce(p_battle_mode, '')), 24), ''),
    case when p_difficulty in ('easy','normal','hard') then p_difficulty else null end,
    nullif(left(trim(coalesce(p_opponent_personality, '')), 40), ''),
    p_result,
    public._oot_int_from_json(v_payload, 'finalValue', 0, -1000000, 1000000),
    public._oot_int_from_json(v_payload, 'finalDistance', 0, 0, 9999),
    case when v_payload ? 'opponentDistance'
      then public._oot_int_from_json(v_payload, 'opponentDistance', 0, 0, 9999)
      else null end,
    public._oot_int_from_json(v_payload, 'operationsUsed', 0, 0, 20),
    public._oot_int_from_json(v_payload, 'drawsUsed', 0, 0, 20),
    v_manual_stop,
    v_stop_distance,
    public._oot_int_from_json(v_payload, 'timeouts', 0, 0, 20),
    v_avg_decision,
    public._oot_int_from_json(v_payload, 'divisionRemainderUses', 0, 0, 20),
    public._oot_int_from_json(v_payload, 'calculationScore', 50, 0, 100),
    public._oot_int_from_json(v_payload, 'distanceScore', 50, 0, 100),
    public._oot_int_from_json(v_payload, 'stopScore', 50, 0, 100),
    public._oot_int_from_json(v_payload, 'resourceScore', 50, 0, 100),
    public._oot_int_from_json(v_payload, 'timeScore', 50, 0, 100),
    jsonb_strip_nulls(v_payload - array[
      'calculationScore','distanceScore','stopScore','resourceScore','timeScore'
    ])
  )
  on conflict (user_id, source_type, source_id) do nothing
  returning id into v_id;

  return jsonb_build_object('recorded', v_id is not null, 'recordId', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public._oot_int_from_json(p_payload jsonb, p_key text, p_default integer, p_min integer, p_max integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_value numeric;
begin
  begin
    v_value := (p_payload ->> p_key)::numeric;
  exception when others then
    v_value := p_default;
  end;
  if v_value is null then v_value := p_default; end if;
  return greatest(p_min, least(p_max, round(v_value)::integer));
end;
$function$;

CREATE OR REPLACE FUNCTION public.accept_garden_friend_invite(p_token uuid)
 RETURNS TABLE(friend_id uuid, friend_nickname text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_creator_id uuid;
  v_friend_name text;
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  select creator_id
    into v_creator_id
  from public.garden_friend_invites
  where token = p_token
    and accepted_at is null
    and expires_at > now()
  for update;

  if not found then
    raise exception '이 초대 링크는 이미 사용됐거나 만료되었어요.';
  end if;

  if v_creator_id = v_user_id then
    raise exception '내가 만든 초대 링크는 내가 수락할 수 없어요.';
  end if;

  insert into public.garden_friendships (user_id, friend_id)
  values
    (v_user_id, v_creator_id),
    (v_creator_id, v_user_id)
  on conflict do nothing;

  update public.garden_friend_invites
  set accepted_at = now(),
      accepted_by = v_user_id
  where token = p_token;

  select coalesce(nickname, '친구')
    into v_friend_name
  from public.garden_profiles
  where id = v_creator_id;

  return query select v_creator_id, coalesce(v_friend_name, '친구');
end;
$function$;

CREATE OR REPLACE FUNCTION public.accept_my_garden_shared_tree_invite(p_invite_id uuid)
 RETURNS TABLE(tree_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_invite public.garden_shared_tree_invites%rowtype;
  v_low uuid;
  v_high uuid;
  v_tree_id uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 상대를 먼저 확인하고 친구 행을 잠근 뒤 초대 행을 잠가,
  -- 관계 종료 함수와 잠금 순서를 동일하게 유지합니다.
  select *
  into v_invite
  from public.garden_shared_tree_invites
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending';

  if not found then
    raise exception 'SHARED_TREE_INVITE_NOT_FOUND';
  end if;

  perform 1
  from public.garden_friendships
  where user_id = v_me
    and friend_id = v_invite.from_user_id
  for key share;

  if not found then
    raise exception 'SHARED_TREE_FRIEND_REQUIRED';
  end if;

  select *
  into v_invite
  from public.garden_shared_tree_invites
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending'
  for update;

  if not found then
    raise exception 'SHARED_TREE_INVITE_NOT_FOUND';
  end if;

  if (
    select count(*)
    from public.garden_shared_trees t
    where v_me in (t.user_one_id, t.user_two_id)
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) >= 3 then
    raise exception 'SHARED_TREE_LIMIT_REACHED';
  end if;

  v_low := least(v_me, v_invite.from_user_id);
  v_high := greatest(v_me, v_invite.from_user_id);

  if exists (
    select 1
    from public.garden_shared_trees t
    where t.user_one_id = v_low
      and t.user_two_id = v_high
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) then
    raise exception 'SHARED_TREE_ALREADY_EXISTS';
  end if;

  begin
    insert into public.garden_shared_trees (
      user_one_id,
      user_two_id
    )
    values (
      v_low,
      v_high
    )
    returning id into v_tree_id;
  exception
    when unique_violation then
      raise exception 'SHARED_TREE_ALREADY_EXISTS';
  end;

  insert into public.garden_shared_tree_start_moments (
    tree_id,
    proposed_by,
    accepted_by
  )
  values (
    v_tree_id,
    v_invite.from_user_id,
    v_me
  );

  update public.garden_shared_tree_invites
  set status = 'accepted',
      responded_at = now()
  where id = v_invite.id;

  update public.garden_shared_tree_invites
  set status = 'cancelled',
      responded_at = now()
  where status = 'pending'
    and (
      (from_user_id = v_me and to_user_id = v_invite.from_user_id)
      or
      (from_user_id = v_invite.from_user_id and to_user_id = v_me)
    );

  return query select v_tree_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.accept_my_garden_shared_tree_invite_v2(p_invite_id uuid)
 RETURNS TABLE(tree_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_invite public.garden_shared_tree_invites%rowtype;
  v_low uuid;
  v_high uuid;
  v_tree_id uuid;
  v_previous_v2_count integer;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select *
  into v_invite
  from public.garden_shared_tree_invites
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending';

  if not found then
    raise exception 'SHARED_TREE_INVITE_NOT_FOUND';
  end if;

  perform 1
  from public.garden_friendships
  where user_id = v_me
    and friend_id = v_invite.from_user_id
  for key share;

  if not found then
    raise exception 'SHARED_TREE_FRIEND_REQUIRED';
  end if;

  select *
  into v_invite
  from public.garden_shared_tree_invites
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending'
  for update;

  if not found then
    raise exception 'SHARED_TREE_INVITE_NOT_FOUND';
  end if;

  if (
    select count(*)
    from public.garden_shared_trees t
    where v_me in (t.user_one_id, t.user_two_id)
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) >= 3 then
    raise exception 'SHARED_TREE_LIMIT_REACHED';
  end if;

  v_low := least(v_me, v_invite.from_user_id);
  v_high := greatest(v_me, v_invite.from_user_id);

  if exists (
    select 1
    from public.garden_shared_trees t
    where t.user_one_id = v_low
      and t.user_two_id = v_high
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) then
    raise exception 'SHARED_TREE_ALREADY_EXISTS';
  end if;

  select count(*)::integer
  into v_previous_v2_count
  from public.garden_shared_trees t
  where t.user_one_id = v_low
    and t.user_two_id = v_high
    and t.growth_version = 2;

  begin
    insert into public.garden_shared_trees (
      user_one_id,
      user_two_id,
      growth_version
    )
    values (
      v_low,
      v_high,
      2
    )
    returning id into v_tree_id;
  exception
    when unique_violation then
      raise exception 'SHARED_TREE_ALREADY_EXISTS';
  end;

  insert into public.garden_shared_tree_profiles (tree_id)
  values (v_tree_id);

  if mod(v_previous_v2_count, 2) = 0 then
    insert into public.garden_shared_tree_member_states (
      tree_id,
      user_id,
      name_piece_role
    )
    values
      (v_tree_id, v_low, 'emotion'),
      (v_tree_id, v_high, 'nature');
  else
    insert into public.garden_shared_tree_member_states (
      tree_id,
      user_id,
      name_piece_role
    )
    values
      (v_tree_id, v_low, 'nature'),
      (v_tree_id, v_high, 'emotion');
  end if;

  insert into public.garden_shared_tree_start_moments (
    tree_id,
    proposed_by,
    accepted_by
  )
  values (
    v_tree_id,
    v_invite.from_user_id,
    v_me
  );

  update public.garden_shared_tree_invites
  set status = 'accepted',
      responded_at = now()
  where id = v_invite.id;

  update public.garden_shared_tree_invites
  set status = 'cancelled',
      responded_at = now()
  where status = 'pending'
    and (
      (from_user_id = v_me and to_user_id = v_invite.from_user_id)
      or
      (from_user_id = v_invite.from_user_id and to_user_id = v_me)
    );

  return query select v_tree_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_garden_special_friend_day_for_record()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_record_date date := (new.created_at at time zone 'Asia/Seoul')::date;
  v_progress_count integer;
begin
  insert into public.garden_special_friend_profiles (
    user_id,
    friend_key,
    started_at,
    created_at,
    updated_at
  )
  values (
    new.user_id,
    'forest_unicorn',
    new.created_at,
    now(),
    now()
  )
  on conflict (user_id) do nothing;

  insert into public.garden_special_friend_day_records (
    user_id,
    record_date,
    source_type,
    source_record_id,
    created_at
  )
  values (
    new.user_id,
    v_record_date,
    'garden_record',
    new.id,
    new.created_at
  )
  on conflict (user_id, record_date) do nothing;

  select count(*)::integer
  into v_progress_count
  from public.garden_special_friend_day_records d
  where d.user_id = new.user_id;

  if v_progress_count >= 3 then
    update public.garden_special_friend_profiles
    set ready_at = coalesce(ready_at, now()),
        updated_at = now()
    where user_id = new.user_id;
  else
    update public.garden_special_friend_profiles
    set updated_at = now()
    where user_id = new.user_id;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_my_garden_shared_tree_care(p_tree_id uuid, p_care_type text, p_choice_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_tree public.garden_shared_trees%rowtype;
  v_completed_stage_count integer;
  v_stage smallint;
  v_stage_event_count integer;
  v_type_event_count integer;
  v_expected_type_one text;
  v_expected_type_two text;
  v_choice text := nullif(btrim(coalesce(p_choice_key, '')), '');
  v_existing_choice text;
  v_event_id uuid;
  v_event_created_at timestamptz;
  v_participant_count integer;
  v_distinct_type_count integer;
  v_cooperative boolean;
  v_completed_stage smallint;
  v_type_counts jsonb;
  v_choice_summary jsonb;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  select t.*
  into v_tree
  from public.garden_shared_trees t
  where t.id = p_tree_id
    and v_me in (t.user_one_id, t.user_two_id)
    and t.growth_version = 2
    and t.completed_at is null
    and t.relationship_ended_at is null
  for update;

  if not found then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
      and e.user_id = v_me
      and e.record_date = v_today
  ) then
    raise exception 'SHARED_TREE_CARE_ALREADY_RECORDED';
  end if;

  select count(*)::integer
  into v_completed_stage_count
  from public.garden_shared_tree_stage_results r
  where r.tree_id = v_tree.id;

  if v_completed_stage_count >= 4 then
    raise exception 'SHARED_TREE_CARE_COMPLETE';
  end if;

  v_stage := (v_completed_stage_count + 1)::smallint;

  case v_stage
    when 1 then
      v_expected_type_one := 'soil';
      v_expected_type_two := 'water';
    when 2 then
      v_expected_type_one := 'sunlight';
      v_expected_type_two := 'nutrition';
    when 3 then
      v_expected_type_one := 'branch';
      v_expected_type_two := 'habitat';
    when 4 then
      v_expected_type_one := 'bloom';
      v_expected_type_two := 'fruit';
    else
      raise exception 'SHARED_TREE_CARE_INVALID_STAGE';
  end case;

  if p_care_type is null
     or p_care_type not in (v_expected_type_one, v_expected_type_two) then
    raise exception 'SHARED_TREE_CARE_TYPE_INVALID';
  end if;

  -- 선택값 허용 목록
  if p_care_type = 'soil' and v_choice is not null and v_choice not in ('soft', 'firm') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'water' and v_choice is not null and v_choice not in ('gentle', 'deep') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'sunlight' and v_choice is not null and v_choice not in ('morning', 'shade') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'nutrition' and v_choice is not null and v_choice not in ('dense', 'broad') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'branch' and v_choice is not null and v_choice not in ('upright', 'wide') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'habitat' and v_choice is not null and v_choice not in ('nest', 'resting_shade') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'bloom' and v_choice is not null and v_choice not in ('sunlight', 'night_dew') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  elsif p_care_type = 'fruit' and v_choice is not null and v_choice not in ('sweet', 'glow') then
    raise exception 'SHARED_TREE_CARE_CHOICE_INVALID';
  end if;

  insert into public.garden_shared_tree_profiles (tree_id)
  values (v_tree.id)
  on conflict (tree_id) do nothing;

  select case p_care_type
    when 'soil' then p.soil_choice
    when 'water' then p.water_choice
    when 'sunlight' then p.sunlight_choice
    when 'nutrition' then p.nutrition_choice
    when 'branch' then p.branch_choice
    when 'habitat' then p.habitat_choice
    when 'bloom' then p.bloom_choice
    when 'fruit' then p.fruit_choice
  end
  into v_existing_choice
  from public.garden_shared_tree_profiles p
  where p.tree_id = v_tree.id
  for update;

  if v_existing_choice is null and v_choice is null then
    raise exception 'SHARED_TREE_CARE_CHOICE_REQUIRED';
  end if;

  if v_existing_choice is not null
     and v_choice is not null
     and v_existing_choice <> v_choice then
    raise exception 'SHARED_TREE_CARE_CHOICE_LOCKED';
  end if;

  v_choice := coalesce(v_existing_choice, v_choice);

  select count(*)::integer
  into v_stage_event_count
  from public.garden_shared_tree_care_events e
  where e.tree_id = v_tree.id
    and e.stage = v_stage;

  if v_stage_event_count >= 5 then
    raise exception 'SHARED_TREE_STAGE_ALREADY_COMPLETE';
  end if;

  select count(*)::integer
  into v_type_event_count
  from public.garden_shared_tree_care_events e
  where e.tree_id = v_tree.id
    and e.stage = v_stage
    and e.care_type = p_care_type;

  if v_type_event_count >= 3 then
    raise exception 'SHARED_TREE_CARE_TYPE_FULL';
  end if;

  update public.garden_shared_tree_profiles p
  set soil_choice = case when p_care_type = 'soil' then coalesce(p.soil_choice, v_choice) else p.soil_choice end,
      water_choice = case when p_care_type = 'water' then coalesce(p.water_choice, v_choice) else p.water_choice end,
      sunlight_choice = case when p_care_type = 'sunlight' then coalesce(p.sunlight_choice, v_choice) else p.sunlight_choice end,
      nutrition_choice = case when p_care_type = 'nutrition' then coalesce(p.nutrition_choice, v_choice) else p.nutrition_choice end,
      branch_choice = case when p_care_type = 'branch' then coalesce(p.branch_choice, v_choice) else p.branch_choice end,
      habitat_choice = case when p_care_type = 'habitat' then coalesce(p.habitat_choice, v_choice) else p.habitat_choice end,
      bloom_choice = case when p_care_type = 'bloom' then coalesce(p.bloom_choice, v_choice) else p.bloom_choice end,
      fruit_choice = case when p_care_type = 'fruit' then coalesce(p.fruit_choice, v_choice) else p.fruit_choice end,
      updated_at = now()
  where p.tree_id = v_tree.id;

  begin
    insert into public.garden_shared_tree_care_events (
      tree_id,
      user_id,
      stage,
      care_type,
      choice_key,
      record_date
    )
    values (
      v_tree.id,
      v_me,
      v_stage,
      p_care_type,
      v_choice,
      v_today
    )
    returning id, created_at
    into v_event_id, v_event_created_at;
  exception
    when unique_violation then
      raise exception 'SHARED_TREE_CARE_ALREADY_RECORDED';
  end;

  v_stage_event_count := v_stage_event_count + 1;
  v_completed_stage := null;

  if v_stage_event_count = 5 then
    select
      count(distinct e.user_id)::integer,
      count(distinct e.care_type)::integer
    into v_participant_count, v_distinct_type_count
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
      and e.stage = v_stage;

    if v_distinct_type_count <> 2 then
      raise exception 'SHARED_TREE_STAGE_NEEDS_BOTH_CARE_TYPES';
    end if;

    v_cooperative := v_participant_count = 2;

    select coalesce(jsonb_object_agg(x.care_type, x.cnt), '{}'::jsonb)
    into v_type_counts
    from (
      select e.care_type, count(*)::integer as cnt
      from public.garden_shared_tree_care_events e
      where e.tree_id = v_tree.id
        and e.stage = v_stage
      group by e.care_type
    ) x;

    select jsonb_build_object(
      v_expected_type_one,
      case v_expected_type_one
        when 'soil' then p.soil_choice
        when 'water' then p.water_choice
        when 'sunlight' then p.sunlight_choice
        when 'nutrition' then p.nutrition_choice
        when 'branch' then p.branch_choice
        when 'habitat' then p.habitat_choice
        when 'bloom' then p.bloom_choice
        when 'fruit' then p.fruit_choice
      end,
      v_expected_type_two,
      case v_expected_type_two
        when 'soil' then p.soil_choice
        when 'water' then p.water_choice
        when 'sunlight' then p.sunlight_choice
        when 'nutrition' then p.nutrition_choice
        when 'branch' then p.branch_choice
        when 'habitat' then p.habitat_choice
        when 'bloom' then p.bloom_choice
        when 'fruit' then p.fruit_choice
      end
    )
    into v_choice_summary
    from public.garden_shared_tree_profiles p
    where p.tree_id = v_tree.id;

    insert into public.garden_shared_tree_stage_results (
      tree_id,
      stage,
      event_count,
      participant_count,
      cooperative,
      completed_at,
      summary
    )
    values (
      v_tree.id,
      v_stage,
      5,
      v_participant_count,
      v_cooperative,
      v_event_created_at,
      jsonb_build_object(
        'care_counts', v_type_counts,
        'choices', v_choice_summary
      )
    );

    v_completed_stage := v_stage;

    if v_stage = 4 then
      update public.garden_shared_trees
      set completed_at = coalesce(completed_at, v_event_created_at)
      where id = v_tree.id;
    end if;
  end if;

  return jsonb_build_object(
    'event_id', v_event_id,
    'recorded_stage', v_stage,
    'care_type', p_care_type,
    'choice_key', v_choice,
    'stage_completed', v_completed_stage is not null,
    'completed_stage', v_completed_stage,
    'cooperative_stage', case when v_completed_stage is not null then v_cooperative else null end,
    'tree', public.get_my_garden_shared_tree_v2(v_tree.id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_my_garden_shared_tree_light(p_tree_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_tree public.garden_shared_trees%rowtype;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_light_created_at timestamptz;
  v_progress_count integer;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_tree
  from public.garden_shared_trees
  where id = p_tree_id
    and v_me in (user_one_id, user_two_id)
    and completed_at is null
    and relationship_ended_at is null
  for update;

  if not found then
    raise exception 'SHARED_TREE_LIGHT_NOT_FOUND';
  end if;

  select count(*)::integer into v_progress_count
  from public.garden_shared_tree_light_records r
  where r.tree_id = v_tree.id;

  if v_progress_count >= v_tree.target_steps then
    raise exception 'SHARED_TREE_LIGHT_COMPLETE';
  end if;

  if exists (
    select 1
    from public.garden_shared_tree_light_records r
    where r.tree_id = v_tree.id
      and r.user_id = v_me
      and r.record_date = v_today
  ) then
    raise exception 'SHARED_TREE_LIGHT_ALREADY_RECORDED';
  end if;

  insert into public.garden_shared_tree_light_records (
    tree_id,
    user_id,
    record_id,
    record_date
  )
  values (
    v_tree.id,
    v_me,
    null,
    v_today
  )
  returning created_at into v_light_created_at;

  v_progress_count := v_progress_count + 1;

  if v_progress_count >= v_tree.target_steps then
    update public.garden_shared_trees
    set completed_at = coalesce(completed_at, v_light_created_at)
    where id = v_tree.id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.begin_my_garden_special_friend_meeting()
 RETURNS TABLE(friend_key text, progress_count integer, target_count integer, today_counted boolean, is_ready boolean, meeting_started boolean, is_met boolean, started_at timestamp with time zone, ready_at timestamp with time zone, meeting_started_at timestamp with time zone, met_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_ready_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  perform *
  from public.sync_my_garden_special_friend_state();

  select sfp.ready_at
    into v_ready_at
  from public.garden_special_friend_profiles as sfp
  where sfp.user_id = v_user_id
  for update;

  if v_ready_at is null then
    raise exception 'SPECIAL_FRIEND_NOT_READY';
  end if;

  update public.garden_special_friend_profiles as sfp
  set meeting_started_at = coalesce(sfp.meeting_started_at, now()),
      updated_at = now()
  where sfp.user_id = v_user_id;

  return query
  select sync_state.*
  from public.sync_my_garden_special_friend_state() as sync_state;
end;
$function$;

CREATE OR REPLACE FUNCTION public.bootstrap_my_garden_profile(p_nickname text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text)
 RETURNS TABLE(nickname text, growth_count integer, weather_index smallint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_nickname text := coalesce(nullif(trim(p_nickname), ''), '새 친구');
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  insert into public.garden_profiles as gp (
    id,
    nickname,
    avatar_url
  )
  values (
    v_user_id,
    v_nickname,
    p_avatar_url
  )
  on conflict (id) do update
  set
    nickname = case
      when gp.nickname is null
        or gp.nickname = ''
        or gp.nickname = '새 친구'
      then excluded.nickname
      else gp.nickname
    end,
    avatar_url = coalesce(gp.avatar_url, excluded.avatar_url)
  returning
    gp.nickname,
    gp.growth_count,
    gp.weather_index
  into nickname, growth_count, weather_index;

  return next;
end;
$function$;

CREATE OR REPLACE FUNCTION public.call_my_garden_animal_with_tree_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := clock_timestamp();
  v_state public.garden_tree_animal_call_state_v1%rowtype;
  v_visit_id uuid;
  v_kind text;
  v_zone text;
  v_variant text := 'normal';
  v_growth integer := 0;
  v_last_kind text;
  v_arrives_at timestamptz;
  v_leaves_at timestamptz;
  v_cooldown_until timestamptz;
  v_dwell_seconds integer;
  v_busy boolean := false;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;
  if p_request_id is null then
    raise exception 'TREE_CALL_REQUEST_ID_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('todayforest-tree-call:' || v_user_id::text, 0)
  );

  -- 다른 탭에서 끝난 방문 상태까지 먼저 맞춘 뒤 중복 여부를 판단합니다.
  perform public.sync_my_garden_dev_animal_visits_v2();

  insert into public.garden_tree_animal_call_state_v1 (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  select * into v_state
  from public.garden_tree_animal_call_state_v1
  where user_id = v_user_id
  for update;

  -- 같은 브라우저 요청이 재전송되면 기존 결과를 그대로 반환합니다.
  if v_state.last_request_id = p_request_id
     and v_state.pending_visit_id is not null
  then
    select animal_kind into v_kind
    from public.garden_dev_animal_v2_visits
    where id = v_state.pending_visit_id
      and user_id = v_user_id;

    if found then
      return jsonb_build_object(
        'visit_id', v_state.pending_visit_id,
        'animal_kind', v_kind,
        'arrives_at', v_state.pending_arrives_at,
        'cooldown_until', v_state.cooldown_until,
        'reused', true
      );
    end if;
  end if;

  if v_state.cooldown_until is not null
     and v_state.cooldown_until > v_now
  then
    raise exception 'TREE_CALL_COOLDOWN:%', v_state.cooldown_until;
  end if;

  select exists (
    select 1
    from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state in ('approaching', 'visiting', 'departing')
  ) into v_busy;

  if v_busy then
    raise exception 'TREE_CALL_ANIMAL_BUSY';
  end if;

  select coalesce(growth_count, 0)
  into v_growth
  from public.garden_profiles
  where id = v_user_id;
  v_growth := coalesce(v_growth, 0);

  select animal_kind
  into v_last_kind
  from public.garden_dev_animal_v2_visits
  where user_id = v_user_id
    and animal_kind in ('bird', 'owl', 'squirrel', 'raccoon', 'rabbit', 'fox', 'hedgehog', 'mole')
  order by coalesce(arrived_at, departing_at, approach_started_at, arrives_at, created_at) desc nulls last
  limit 1;
  v_last_kind := coalesce(v_last_kind, v_state.last_animal_kind);

  -- 자연 방문과 같은 발견 규칙을 사용하되, 나무로 부를 때는 직전 동물의
  -- 확률만 절반으로 낮춥니다. 정확한 등장 조건은 사용자 화면에 공개하지 않습니다.
  select picked.animal_kind, picked.habitat_zone
  into v_kind, v_zone
  from public.pick_my_garden_animal_v3(
    v_user_id,
    v_growth,
    v_last_kind,
    0.5
  ) as picked
  limit 1;

  if v_kind is null then
    raise exception 'TREE_CALL_NO_ANIMAL_AVAILABLE';
  end if;

  v_variant := case
    when v_growth >= 30 and random() < 0.18 then 'glimmer'
    when v_growth >= 21 and random() < 0.10 then 'glimmer'
    else 'normal'
  end;

  -- 기존 운영 RPC와 같은 종별 체류 범위입니다.
  v_dwell_seconds := case v_kind
    when 'bird' then 150 + floor(random() * 151)::integer
    when 'owl' then 180 + floor(random() * 151)::integer
    when 'rabbit' then 210 + floor(random() * 181)::integer
    when 'fox' then 220 + floor(random() * 181)::integer
    when 'squirrel' then 240 + floor(random() * 181)::integer
    when 'raccoon' then 250 + floor(random() * 191)::integer
    when 'hedgehog' then 270 + floor(random() * 211)::integer
    when 'mole' then 300 + floor(random() * 211)::integer
  end;

  v_arrives_at := v_now + interval '3 seconds';
  v_leaves_at := v_arrives_at + make_interval(secs => v_dwell_seconds);
  v_cooldown_until := v_arrives_at + interval '1 hour';
  v_visit_id := gen_random_uuid();

  -- 자연 방문 25% 단축 트리거가 이 3초 호출까지 줄이지 않도록 표시합니다.
  perform set_config('todayforest.tree_call', '1', true);

  insert into public.garden_dev_animal_v2_visits (
    id,
    user_id,
    animal_kind,
    habitat_zone,
    visit_state,
    visit_variant,
    approach_started_at,
    arrives_at,
    leaves_at,
    created_at,
    updated_at
  ) values (
    v_visit_id,
    v_user_id,
    v_kind,
    v_zone,
    'approaching',
    v_variant,
    v_now,
    v_arrives_at,
    v_leaves_at,
    v_now,
    v_now
  );

  -- 새 방문이 생기면 기존 운영 RPC와 마찬가지로 오래된 흔적은 정리합니다.
  delete from public.garden_dev_animal_v2_visits
  where user_id = v_user_id
    and visit_state = 'trace';

  update public.garden_tree_animal_call_state_v1
  set cooldown_until = v_cooldown_until,
      pending_visit_id = v_visit_id,
      pending_arrives_at = v_arrives_at,
      last_animal_kind = v_kind,
      last_request_id = p_request_id,
      updated_at = v_now
  where user_id = v_user_id;

  return jsonb_build_object(
    'visit_id', v_visit_id,
    'animal_kind', v_kind,
    'arrives_at', v_arrives_at,
    'cooldown_until', v_cooldown_until,
    'reused', false
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_my_garden_friend_request(p_request_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_updated integer;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.garden_friend_requests
  set status = 'cancelled', responded_at = now()
  where id = p_request_id
    and from_user_id = v_me
    and status = 'pending';

  get diagnostics v_updated = row_count;
  return v_updated > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_garden_dev_found_item(p_record_id uuid)
 RETURNS TABLE(id uuid, item_key text, placement_slot text, found_at timestamp with time zone, position_x numeric, position_y numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_item_key text;
  v_slot text;
  v_storage_state text;
  v_found public.garden_dev_found_items%rowtype;
begin
  if v_user_id is null then
    raise exception 'NOT_AUTHENTICATED';
  end if;

  -- 같은 사용자의 동시 요청을 한 건씩 처리합니다.
  perform pg_advisory_xact_lock(
    hashtext('garden-dev-found:' || v_user_id::text)::bigint
  );

  if not exists (
    select 1
    from public.garden_records as record
    where record.id = p_record_id
      and record.user_id = v_user_id
      and (record.created_at at time zone 'Asia/Seoul')::date
          = (now() at time zone 'Asia/Seoul')::date
  ) then
    raise exception 'TODAY_RECORD_NOT_FOUND';
  end if;

  -- 같은 오늘 기록으로 이미 받았다면 기존 결과를 그대로 반환합니다.
  select found.*
  into v_found
  from public.garden_dev_found_items as found
  where found.record_id = p_record_id
    and found.user_id = v_user_id
  limit 1;

  if found then
    return query
    select
      v_found.id,
      v_found.item_key,
      v_found.placement_slot,
      v_found.found_at,
      v_found.position_x,
      v_found.position_y;
    return;
  end if;

  with first_recipe_requirements as (
    select
      requirement.value ->> 'item_key' as item_key,
      sum(
        greatest(
          0,
          coalesce((requirement.value ->> 'quantity')::integer, 0)
        )
      )::bigint as required_quantity
    from public.garden_decoration_recipes as recipe
    cross join lateral jsonb_array_elements(recipe.required_items) as requirement(value)
    where recipe.is_enabled = true
      and not exists (
        select 1
        from public.garden_decoration_recipe_exchanges as exchange
        where exchange.user_id = v_user_id
          and exchange.recipe_key = recipe.recipe_key
          and exchange.status = 'completed'
      )
      and nullif(requirement.value ->> 'item_key', '') is not null
    group by requirement.value ->> 'item_key'
  ),
  inventory_counts as (
    select
      found.item_key,
      count(*)::bigint as inventory_quantity
    from public.garden_dev_found_items as found
    where found.user_id = v_user_id
      and found.storage_state = 'inventory'
    group by found.item_key
  )
  select
    catalog.item_key,
    catalog.default_placement_slot
  into
    v_item_key,
    v_slot
  from public.garden_decoration_items as catalog
  left join public.garden_decoration_claim_counts as counts
    on counts.user_id = v_user_id
   and counts.item_key = catalog.item_key
  left join first_recipe_requirements as recipe_need
    on recipe_need.item_key = catalog.item_key
  left join inventory_counts as inventory
    on inventory.item_key = catalog.item_key
  where catalog.is_active = true
    and catalog.is_daily_findable = true
    and catalog.item_kind = 'basic'
    and catalog.default_placement_slot is not null
  order by
    case
      when coalesce(recipe_need.required_quantity, 0)
           > coalesce(inventory.inventory_quantity, 0)
      then 0 else 1
    end,
    greatest(
      coalesce(recipe_need.required_quantity, 0)
      - coalesce(inventory.inventory_quantity, 0),
      0
    ) desc,
    case when coalesce(counts.claim_count, 0) = 0 then 0 else 1 end,
    coalesce(counts.claim_count, 0) asc,
    md5(
      v_user_id::text || ':' ||
      p_record_id::text || ':' ||
      catalog.item_key
    ) asc,
    catalog.daily_find_sort_order asc,
    catalog.item_key asc
  limit 1;

  if v_item_key is null or v_slot is null then
    raise exception 'DAILY_FINDABLE_ITEM_NOT_CONFIGURED';
  end if;

  -- 같은 종류를 이미 가지고 있으면 중복 발견품은 자동으로 보관함에 넣습니다.
  v_storage_state := case
    when exists (
      select 1
      from public.garden_dev_found_items as owned
      where owned.user_id = v_user_id
        and owned.item_key = v_item_key
    ) then 'inventory'
    else 'placed'
  end;

  insert into public.garden_dev_found_items as inserted (
    user_id,
    record_id,
    item_key,
    placement_slot,
    storage_state,
    found_at
  )
  values (
    v_user_id,
    p_record_id,
    v_item_key,
    v_slot,
    v_storage_state,
    now()
  )
  returning inserted.* into v_found;

  insert into public.garden_decoration_claim_counts (
    user_id,
    item_key,
    claim_count,
    first_claimed_at,
    last_claimed_at,
    updated_at
  )
  values (
    v_user_id,
    v_item_key,
    1,
    v_found.found_at,
    v_found.found_at,
    now()
  )
  on conflict on constraint garden_decoration_claim_counts_pkey do update
  set claim_count = public.garden_decoration_claim_counts.claim_count + 1,
      first_claimed_at = coalesce(
        public.garden_decoration_claim_counts.first_claimed_at,
        excluded.first_claimed_at
      ),
      last_claimed_at = excluded.last_claimed_at,
      updated_at = now();

  return query
  select
    v_found.id,
    v_found.item_key,
    v_found.placement_slot,
    v_found.found_at,
    v_found.position_x,
    v_found.position_y;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_garden_found_item(p_record_id uuid)
 RETURNS TABLE(id uuid, item_key text, placement_slot text, found_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_item_key text;
  v_slot text;
begin
  if v_user_id is null then
    raise exception 'NOT_AUTHENTICATED';
  end if;

  perform pg_advisory_xact_lock(hashtext(v_user_id::text));

  if not exists (
    select 1
    from public.garden_records as record
    where record.id = p_record_id
      and record.user_id = v_user_id
      and (record.created_at at time zone 'Asia/Seoul')::date
          = (now() at time zone 'Asia/Seoul')::date
  ) then
    raise exception 'TODAY_RECORD_NOT_FOUND';
  end if;

  if exists (
    select 1
    from public.garden_found_items as found
    where found.record_id = p_record_id
  ) then
    return query
    select
      found.id,
      found.item_key,
      found.placement_slot,
      found.found_at
    from public.garden_found_items as found
    where found.record_id = p_record_id;

    return;
  end if;

  select
    candidate.item_key,
    candidate.placement_slot
  into
    v_item_key,
    v_slot
  from (
    values
      ('pink_wildflower'::text, 'front_bed_left'::text),
      ('white_daisies'::text, 'front_bed_right'::text),
      ('mushroom_pair'::text, 'tree_base_left'::text),
      ('mossy_round_rock'::text, 'tree_base_right'::text)
  ) as candidate(item_key, placement_slot)
  where not exists (
    select 1
    from public.garden_found_items as found
    where found.user_id = v_user_id
      and found.item_key = candidate.item_key
  )
  order by md5(v_user_id::text || candidate.item_key)
  limit 1;

  if v_item_key is null then
    return;
  end if;

  return query
  insert into public.garden_found_items (
    user_id,
    record_id,
    item_key,
    placement_slot,
    found_at
  )
  values (
    v_user_id,
    p_record_id,
    v_item_key,
    v_slot,
    now()
  )
  returning
    garden_found_items.id,
    garden_found_items.item_key,
    garden_found_items.placement_slot,
    garden_found_items.found_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.cleanup_expired_garden_letters()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  raise exception 'RETENTION_V8_DISABLED_USE_V9_DEV_FUNCTIONS';
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_my_garden_special_friend_meeting()
 RETURNS TABLE(friend_key text, progress_count integer, target_count integer, today_counted boolean, is_ready boolean, meeting_started boolean, is_met boolean, started_at timestamp with time zone, ready_at timestamp with time zone, meeting_started_at timestamp with time zone, met_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_profile public.garden_special_friend_profiles%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select sfp.*
    into v_profile
  from public.garden_special_friend_profiles as sfp
  where sfp.user_id = v_user_id
  for update;

  if not found or v_profile.ready_at is null then
    raise exception 'SPECIAL_FRIEND_NOT_READY';
  end if;

  update public.garden_special_friend_profiles as sfp
  set meeting_started_at = coalesce(sfp.meeting_started_at, now()),
      met_at = coalesce(sfp.met_at, now()),
      updated_at = now()
  where sfp.user_id = v_user_id;

  return query
  select sync_state.*
  from public.sync_my_garden_special_friend_state() as sync_state;
end;
$function$;

CREATE OR REPLACE FUNCTION public.consume_my_garden_retention_dev_notices()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer := 0;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  with acknowledged as (
    update public.garden_letter_retention_dev_notices
       set acknowledged_at = now()
     where owner_id = auth.uid()
       and scenario = '31'
       and acknowledged_at is null
    returning expired_count
  )
  select coalesce(sum(expired_count), 0)::integer
    into v_count
  from acknowledged;

  return jsonb_build_object('expired_count', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_garden_friend_invite()
 RETURNS TABLE(invite_token uuid, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_token uuid;
  v_expires_at timestamptz;
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  -- 만료됐거나 이미 사용한 예전 링크만 정리합니다.
  delete from public.garden_friend_invites as invite
  where invite.creator_id = v_user_id
    and (invite.expires_at <= now() or invite.accepted_at is not null);

  -- 아직 쓸 수 있는 링크가 있으면 같은 링크를 다시 돌려줍니다.
  select invite.token, invite.expires_at
    into v_token, v_expires_at
  from public.garden_friend_invites as invite
  where invite.creator_id = v_user_id
    and invite.accepted_at is null
    and invite.expires_at > now()
  order by invite.created_at desc
  limit 1;

  if found then
    return query select v_token, v_expires_at;
    return;
  end if;

  insert into public.garden_friend_invites as invite (creator_id)
  values (v_user_id)
  returning invite.token, invite.expires_at
    into v_token, v_expires_at;

  return query select v_token, v_expires_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_garden_friend_request_by_code(p_code text, p_nickname text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, request_status text, target_user_id uuid, target_nickname text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  v_target uuid;
  v_target_name text;
  v_from_name text := left(coalesce(nullif(trim(p_nickname), ''), '새 친구'), 40);
  v_existing public.garden_friend_requests%rowtype;
  v_invite_json jsonb;
  v_token uuid;
  v_expires timestamptz;
  v_request_id uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select c.user_id, c.nickname_snapshot
    into v_target, v_target_name
  from public.garden_friend_codes c
  where c.friend_code = v_code;

  if v_target is null then
    raise exception 'FRIEND_CODE_NOT_FOUND';
  end if;
  if v_target = v_me then
    return query select null::uuid, 'self'::text, v_target, v_target_name, null::timestamptz;
    return;
  end if;

  update public.garden_friend_requests r
  set status = 'expired', responded_at = now()
  where r.status = 'pending'
    and r.expires_at <= now()
    and v_me in (r.from_user_id, r.to_user_id);

  if exists (
    select 1 from public.list_my_garden_friends() f
    where f.friend_id = v_target
  ) then
    return query select null::uuid, 'already_friend'::text, v_target, v_target_name, null::timestamptz;
    return;
  end if;

  select * into v_existing
  from public.garden_friend_requests r
  where r.status = 'pending'
    and ((r.from_user_id = v_me and r.to_user_id = v_target)
      or (r.from_user_id = v_target and r.to_user_id = v_me))
  order by r.created_at desc
  limit 1;

  if found then
    return query select
      v_existing.id,
      case when v_existing.from_user_id = v_me then 'outgoing_pending' else 'incoming_pending' end,
      v_target,
      v_target_name,
      v_existing.expires_at;
    return;
  end if;

  if (select count(*) from public.garden_friend_requests r
      where r.from_user_id = v_me and r.status = 'pending') >= 10 then
    raise exception 'FRIEND_REQUEST_LIMIT_REACHED';
  end if;

  -- 기존의 검증된 1회용 친구 초대 토큰을 내부 연결 증표로 재사용합니다.
  select to_jsonb(i) into v_invite_json
  from public.create_garden_friend_invite() i
  limit 1;

  v_token := nullif(v_invite_json ->> 'invite_token', '')::uuid;
  v_expires := coalesce(nullif(v_invite_json ->> 'expires_at', '')::timestamptz, now() + interval '7 days');

  if v_token is null then
    raise exception 'FRIEND_REQUEST_TOKEN_NOT_CREATED';
  end if;

  insert into public.garden_friend_requests (
    from_user_id, to_user_id, invite_token,
    from_nickname, to_nickname, expires_at
  ) values (
    v_me, v_target, v_token,
    v_from_name, v_target_name, v_expires
  )
  returning id into v_request_id;

  return query select v_request_id, 'outgoing_pending'::text, v_target, v_target_name, v_expires;
exception
  when unique_violation then
    select * into v_existing
    from public.garden_friend_requests r
    where r.status = 'pending'
      and ((r.from_user_id = v_me and r.to_user_id = v_target)
        or (r.from_user_id = v_target and r.to_user_id = v_me))
    order by r.created_at desc
    limit 1;

    if found then
      return query select
        v_existing.id,
        case when v_existing.from_user_id = v_me then 'outgoing_pending' else 'incoming_pending' end,
        v_target,
        v_target_name,
        v_existing.expires_at;
      return;
    end if;
    raise;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_garden_friend_request_from_oot_match(p_match_id uuid, p_nickname text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, request_status text, target_user_id uuid, target_nickname text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_wrapper jsonb;
  v_match jsonb;
  v_single_value jsonb;
  v_source text;
  v_status text;
  v_phase text;
  v_target_text text;
  v_target uuid;
  v_target_name text;
  v_from_name text := left(coalesce(nullif(trim(p_nickname), ''), '새 친구'), 40);
  v_existing public.garden_friend_requests%rowtype;
  v_recent_decline public.garden_friend_requests%rowtype;
  v_invite_json jsonb;
  v_token uuid;
  v_expires timestamptz;
  v_request_id uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_match_id is null then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  -- 기존 원오브텐 조회 RPC가 참여자 여부를 검증합니다.
  -- 반환형이 jsonb 스칼라이거나 1행 레코드인 경우를 모두 안전하게 펼칩니다.
  execute 'select to_jsonb(m) from public.oot_get_match_view($1) m limit 1'
    into v_wrapper
    using p_match_id;

  if v_wrapper is null then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  v_match := v_wrapper;
  if not (v_match ? 'matchId' or v_match ? 'match_id')
     and jsonb_typeof(v_match) = 'object'
     and jsonb_object_length(v_match) = 1 then
    select value into v_single_value from jsonb_each(v_match) limit 1;
    if jsonb_typeof(v_single_value) = 'object' then
      v_match := v_single_value;
    end if;
  end if;

  v_source := lower(coalesce(v_match ->> 'matchSource', v_match ->> 'match_source', ''));
  v_status := lower(coalesce(v_match ->> 'status', ''));
  v_phase := lower(coalesce(v_match ->> 'phase', ''));

  if v_source <> 'random' then
    raise exception 'OOT_RANDOM_MATCH_REQUIRED';
  end if;
  if v_status <> 'finished' and v_phase <> 'finished' then
    raise exception 'OOT_MATCH_NOT_FINISHED';
  end if;

  v_target_text := coalesce(
    nullif(v_match ->> 'opponentId', ''),
    nullif(v_match ->> 'opponent_id', ''),
    nullif(v_match ->> 'otherUserId', ''),
    nullif(v_match ->> 'other_user_id', '')
  );

  begin
    v_target := v_target_text::uuid;
  exception when others then
    raise exception 'OOT_OPPONENT_NOT_FOUND';
  end;

  if v_target is null or v_target = v_me then
    raise exception 'OOT_OPPONENT_NOT_FOUND';
  end if;

  v_target_name := left(coalesce(
    nullif(trim(v_match ->> 'opponentNickname'), ''),
    nullif(trim(v_match ->> 'opponent_nickname'), ''),
    '대전에서 만난 친구'
  ), 40);

  update public.garden_friend_requests r
  set status = 'expired', responded_at = now()
  where r.status = 'pending'
    and r.expires_at <= now()
    and v_me in (r.from_user_id, r.to_user_id);

  if exists (
    select 1 from public.list_my_garden_friends() f
    where f.friend_id = v_target
  ) then
    return query select null::uuid, 'already_friend'::text, v_target, v_target_name, null::timestamptz;
    return;
  end if;

  select * into v_existing
  from public.garden_friend_requests r
  where r.status = 'pending'
    and ((r.from_user_id = v_me and r.to_user_id = v_target)
      or (r.from_user_id = v_target and r.to_user_id = v_me))
  order by r.created_at desc
  limit 1;

  if found then
    return query select
      v_existing.id,
      case when v_existing.from_user_id = v_me then 'outgoing_pending' else 'incoming_pending' end,
      v_target,
      v_target_name,
      v_existing.expires_at;
    return;
  end if;

  -- 상대가 최근 거절한 경우 결과를 노출하지 않고 재신청만 잠시 제한합니다.
  select * into v_recent_decline
  from public.garden_friend_requests r
  where r.from_user_id = v_me
    and r.to_user_id = v_target
    and r.status = 'declined'
    and coalesce(r.responded_at, r.created_at) > now() - interval '7 days'
  order by coalesce(r.responded_at, r.created_at) desc
  limit 1;

  if found then
    return query select
      v_recent_decline.id,
      'recently_declined'::text,
      v_target,
      v_target_name,
      (coalesce(v_recent_decline.responded_at, v_recent_decline.created_at) + interval '7 days');
    return;
  end if;

  if (select count(*) from public.garden_friend_requests r
      where r.from_user_id = v_me and r.status = 'pending') >= 10 then
    raise exception 'FRIEND_REQUEST_LIMIT_REACHED';
  end if;

  -- 기존 친구 연결 증표를 재사용하여 기존 친구/정원 데이터 구조를 보존합니다.
  select to_jsonb(i) into v_invite_json
  from public.create_garden_friend_invite() i
  limit 1;

  if jsonb_typeof(v_invite_json) = 'object'
     and not (v_invite_json ? 'invite_token')
     and jsonb_object_length(v_invite_json) = 1 then
    select value into v_single_value from jsonb_each(v_invite_json) limit 1;
    if jsonb_typeof(v_single_value) = 'object' then
      v_invite_json := v_single_value;
    end if;
  end if;

  v_token := nullif(v_invite_json ->> 'invite_token', '')::uuid;
  v_expires := coalesce(
    nullif(v_invite_json ->> 'expires_at', '')::timestamptz,
    now() + interval '7 days'
  );

  if v_token is null then
    raise exception 'FRIEND_REQUEST_TOKEN_NOT_CREATED';
  end if;

  insert into public.garden_friend_requests (
    from_user_id, to_user_id, invite_token,
    from_nickname, to_nickname, expires_at
  ) values (
    v_me, v_target, v_token,
    v_from_name, v_target_name, v_expires
  )
  returning id into v_request_id;

  return query select v_request_id, 'outgoing_pending'::text, v_target, v_target_name, v_expires;
exception
  when unique_violation then
    select * into v_existing
    from public.garden_friend_requests r
    where r.status = 'pending'
      and ((r.from_user_id = v_me and r.to_user_id = v_target)
        or (r.from_user_id = v_target and r.to_user_id = v_me))
    order by r.created_at desc
    limit 1;

    if found then
      return query select
        v_existing.id,
        case when v_existing.from_user_id = v_me then 'outgoing_pending' else 'incoming_pending' end,
        v_target,
        v_target_name,
        v_existing.expires_at;
      return;
    end if;
    raise;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_my_garden_retention_test(p_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  raise exception 'RETENTION_V8_DISABLED_USE_V9_DEV_FUNCTIONS';
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_my_garden_shared_tree_invite(p_friend_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_low uuid;
  v_high uuid;
  v_invite_id uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_friend_id is null or p_friend_id = v_me then
    raise exception 'INVALID_SHARED_TREE_FRIEND';
  end if;

  perform 1
  from public.garden_friendships
  where user_id = v_me
    and friend_id = p_friend_id
  for key share;

  if not found then
    raise exception 'SHARED_TREE_FRIEND_REQUIRED';
  end if;

  v_low := least(v_me, p_friend_id);
  v_high := greatest(v_me, p_friend_id);

  if exists (
    select 1
    from public.garden_shared_trees t
    where t.user_one_id = v_low
      and t.user_two_id = v_high
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) then
    raise exception 'SHARED_TREE_ALREADY_EXISTS';
  end if;

  if (
    select count(*)
    from public.garden_shared_trees t
    where v_me in (t.user_one_id, t.user_two_id)
      and t.completed_at is null
      and t.relationship_ended_at is null
  ) >= 3 then
    raise exception 'SHARED_TREE_LIMIT_REACHED';
  end if;

  if exists (
    select 1
    from public.garden_shared_tree_invites i
    where i.status = 'pending'
      and (
        (i.from_user_id = v_me and i.to_user_id = p_friend_id)
        or
        (i.from_user_id = p_friend_id and i.to_user_id = v_me)
      )
  ) then
    raise exception 'SHARED_TREE_INVITE_ALREADY_PENDING';
  end if;

  insert into public.garden_shared_tree_invites (
    from_user_id,
    to_user_id
  )
  values (
    v_me,
    p_friend_id
  )
  returning id into v_invite_id;

  return v_invite_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.depart_my_garden_animal_visit(p_expected_kind text)
 RETURNS TABLE(departed boolean, next_available_at timestamp with time zone, last_departed_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_visit public.garden_animal_visit_states%rowtype;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_expected_kind not in ('bird', 'rabbit', 'squirrel', 'hedgehog') then
    raise exception 'INVALID_ANIMAL_KIND';
  end if;

  select * into v_visit
  from public.garden_animal_visit_states
  where user_id = v_user_id
  for update;

  if not found or v_visit.state <> 'visiting' or v_visit.animal_kind <> p_expected_kind then
    return query select false, null::timestamptz, null::timestamptz;
    return;
  end if;

  update public.garden_animal_visit_states
  set state = 'idle',
      animal_kind = null,
      approach_started_at = null,
      arrives_at = null,
      arrived_at = null,
      leaves_at = null,
      next_available_at = v_now + interval '1 hour',
      last_departed_at = v_now,
      last_departure_reason = 'letter',
      trace_expires_at = v_now + interval '10 minutes',
      updated_at = v_now
  where user_id = v_user_id;

  return query select true, v_now + interval '1 hour', v_now;
end;
$function$;

CREATE OR REPLACE FUNCTION public.dismiss_my_garden_retention_dev_test(p_test_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted integer := 0;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  delete from public.garden_letter_retention_dev_tests
   where id = p_test_id
     and owner_id = auth.uid();

  get diagnostics v_deleted = row_count;
  return v_deleted = 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.enable_my_dev_test_friend()
 RETURNS TABLE(friend_id uuid, nickname text, growth_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  insert into public.garden_dev_test_friends (owner_id, nickname, growth_count)
  values (v_user_id, '테스트 새싹', 5)
  on conflict (owner_id) do update
    set nickname = excluded.nickname,
        growth_count = excluded.growth_count;

  return query
  select d.id, d.nickname, d.growth_count
  from public.garden_dev_test_friends as d
  where d.owner_id = v_user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.end_garden_friendship_v1(p_friend_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_low uuid;
  v_high uuid;
  v_now timestamptz := clock_timestamp();
  v_relationship_started_at timestamptz;
  v_friendship_rows integer := 0;
  v_archived_tree_count integer := 0;
  v_cancelled_invite_count integer := 0;
  v_returned_letter_count integer := 0;
  v_my_returned_letter_count integer := 0;
begin
  if v_me is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if p_friend_id is null or p_friend_id = v_me then
    raise exception '정리할 친구 관계를 찾지 못했어요.';
  end if;

  v_low := least(v_me, p_friend_id);
  v_high := greatest(v_me, p_friend_id);

  -- 두 방향의 친구 행을 일정한 순서로 잠급니다.
  perform 1
  from public.garden_friendships f
  where
    (f.user_id = v_me and f.friend_id = p_friend_id)
    or
    (f.user_id = p_friend_id and f.friend_id = v_me)
  order by f.user_id, f.friend_id
  for update;

  get diagnostics v_friendship_rows = row_count;

  if v_friendship_rows = 0 then
    return jsonb_build_object(
      'ended', false,
      'already_ended', true,
      'archived_shared_tree_count', 0,
      'cancelled_shared_tree_invite_count', 0,
      'returned_letter_count', 0,
      'my_returned_letter_count', 0
    );
  end if;

  select min(f.created_at)
  into v_relationship_started_at
  from public.garden_friendships f
  where
    (f.user_id = v_me and f.friend_id = p_friend_id)
    or
    (f.user_id = p_friend_id and f.friend_id = v_me);

  update public.garden_shared_trees t
  set relationship_ended_at = v_now,
      relationship_ended_by = v_me
  where t.user_one_id = v_low
    and t.user_two_id = v_high
    and t.relationship_ended_at is null;

  get diagnostics v_archived_tree_count = row_count;

  update public.garden_shared_tree_invites i
  set status = 'cancelled',
      responded_at = coalesce(i.responded_at, v_now)
  where i.status = 'pending'
    and (
      (i.from_user_id = v_me and i.to_user_id = p_friend_id)
      or
      (i.from_user_id = p_friend_id and i.to_user_id = v_me)
    );

  get diagnostics v_cancelled_invite_count = row_count;

  -- 아직 친구의 나뭇가지에 도착하지 않은 편지만 반환합니다.
  with returned_letters as (
    update public.garden_letters l
    set returned_at = v_now,
        return_reason = 'friendship_ended',
        return_seen_at = null
    where l.returned_at is null
      and l.read_at is null
      and l.available_at > v_now
      and (
        (l.sender_id = v_me and l.recipient_id = p_friend_id)
        or
        (l.sender_id = p_friend_id and l.recipient_id = v_me)
      )
    returning l.sender_id
  )
  select
    count(*)::integer,
    count(*) filter (where sender_id = v_me)::integer
  into
    v_returned_letter_count,
    v_my_returned_letter_count
  from returned_letters;

  delete from public.garden_friendships
  where
    (user_id = v_me and friend_id = p_friend_id)
    or
    (user_id = p_friend_id and friend_id = v_me);

  insert into public.garden_friendship_endings (
    user_one_id,
    user_two_id,
    ended_by,
    relationship_started_at,
    ended_at,
    end_reason,
    archived_shared_tree_count,
    cancelled_shared_tree_invite_count,
    returned_letter_count
  )
  values (
    v_low,
    v_high,
    v_me,
    v_relationship_started_at,
    v_now,
    'user_ended',
    v_archived_tree_count,
    v_cancelled_invite_count,
    v_returned_letter_count
  );

  return jsonb_build_object(
    'ended', true,
    'already_ended', false,
    'archived_shared_tree_count', v_archived_tree_count,
    'cancelled_shared_tree_invite_count', v_cancelled_invite_count,
    'returned_letter_count', v_returned_letter_count,
    'my_returned_letter_count', v_my_returned_letter_count
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_my_garden_friend_code(p_nickname text DEFAULT NULL::text)
 RETURNS TABLE(friend_code text, nickname text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_code text;
  v_nickname text := left(coalesce(nullif(trim(p_nickname), ''), '새 친구'), 40);
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select c.friend_code into v_code
  from public.garden_friend_codes c
  where c.user_id = v_me;

  if v_code is null then
    loop
      v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
      begin
        insert into public.garden_friend_codes (user_id, friend_code, nickname_snapshot)
        values (v_me, v_code, v_nickname);
        exit;
      exception when unique_violation then
        v_code := null;
      end;
    end loop;
  else
    update public.garden_friend_codes
    set nickname_snapshot = v_nickname,
        updated_at = now()
    where user_id = v_me;
  end if;

  return query select v_code, v_nickname;
end;
$function$;

CREATE OR REPLACE FUNCTION public.exchange_my_garden_decoration_recipe_v1(p_recipe_key text, p_client_request_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_recipe public.garden_decoration_recipes%rowtype;
  v_exchange_id bigint;
  v_existing public.garden_decoration_recipe_exchanges%rowtype;
  v_requirement record;
  v_item public.garden_dev_found_items%rowtype;
  v_loop integer;
  v_consumed jsonb := '[]'::jsonb;
  v_anchor_record_id public.garden_dev_found_items.record_id%type;
  v_anchor_time timestamptz;
  v_item_time timestamptz;
  v_result_item_id text;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해요.' using errcode = '42501';
  end if;

  if nullif(trim(p_recipe_key), '') is null
     or nullif(trim(p_client_request_id), '') is null then
    raise exception '레시피 요청 정보가 올바르지 않아요.' using errcode = '22023';
  end if;

  select *
  into v_recipe
  from public.garden_decoration_recipes
  where recipe_key = p_recipe_key
    and is_enabled = true;

  if not found then
    raise exception '사용할 수 없는 레시피예요.' using errcode = '22023';
  end if;

  insert into public.garden_decoration_recipe_exchanges (
    user_id,
    client_request_id,
    recipe_key,
    status
  )
  values (
    v_user_id,
    p_client_request_id,
    v_recipe.recipe_key,
    'processing'
  )
  on conflict (user_id, client_request_id) do nothing
  returning id into v_exchange_id;

  if v_exchange_id is null then
    select *
    into v_existing
    from public.garden_decoration_recipe_exchanges
    where user_id = v_user_id
      and client_request_id = p_client_request_id;

    if v_existing.status = 'completed' then
      return jsonb_build_object(
        'ok', true,
        'duplicate', true,
        'recipe_key', v_existing.recipe_key,
        'result_item_key', v_existing.result_item_key,
        'result_found_item_id', v_existing.result_found_item_id,
        'consumed_items', v_existing.consumed_items
      );
    end if;

    raise exception '같은 교환 요청을 처리하고 있어요.' using errcode = '55000';
  end if;

  -- 지정 재료를 오래된 보관 장식부터 한 개씩 잠그고 차감합니다.
  for v_requirement in
    select
      value ->> 'item_key' as item_key,
      greatest(0, coalesce((value ->> 'quantity')::integer, 0)) as quantity
    from jsonb_array_elements(v_recipe.required_items)
  loop
    if v_requirement.item_key is null or v_requirement.quantity < 1 then
      continue;
    end if;

    for v_loop in 1..v_requirement.quantity loop
      select *
      into v_item
      from public.garden_dev_found_items
      where user_id = v_user_id
        and storage_state = 'inventory'
        and item_key = v_requirement.item_key
      order by coalesce(found_at, created_at) asc, item_key asc, id::text asc
      limit 1
      for update skip locked;

      if not found then
        raise exception '지정 재료가 부족해요: %', v_requirement.item_key using errcode = 'P0001';
      end if;

      v_item_time := coalesce(v_item.found_at, v_item.created_at, now());
      if v_anchor_time is null or v_item_time > v_anchor_time then
        v_anchor_time := v_item_time;
        v_anchor_record_id := v_item.record_id;
      end if;

      v_consumed := v_consumed || jsonb_build_array(jsonb_build_object(
        'id', v_item.id::text,
        'item_key', v_item.item_key,
        'role', 'required'
      ));

      delete from public.garden_dev_found_items
      where id = v_item.id
        and user_id = v_user_id;
    end loop;
  end loop;

  -- 자유 재료는 지정 재료를 뺀 뒤 남은 일반 장식 중 오래된 것부터 사용합니다.
  if v_recipe.flexible_quantity > 0 then
    for v_loop in 1..v_recipe.flexible_quantity loop
      select *
      into v_item
      from public.garden_dev_found_items
      where user_id = v_user_id
        and storage_state = 'inventory'
        and item_key = any(v_recipe.flexible_item_keys)
      order by coalesce(found_at, created_at) asc, item_key asc, id::text asc
      limit 1
      for update skip locked;

      if not found then
        raise exception '자유 재료가 부족해요.' using errcode = 'P0001';
      end if;

      v_item_time := coalesce(v_item.found_at, v_item.created_at, now());
      if v_anchor_time is null or v_item_time > v_anchor_time then
        v_anchor_time := v_item_time;
        v_anchor_record_id := v_item.record_id;
      end if;

      v_consumed := v_consumed || jsonb_build_array(jsonb_build_object(
        'id', v_item.id::text,
        'item_key', v_item.item_key,
        'role', 'flexible'
      ));

      delete from public.garden_dev_found_items
      where id = v_item.id
        and user_id = v_user_id;
    end loop;
  end if;

  if v_anchor_record_id is null then
    raise exception '결과 장식을 연결할 기록을 찾지 못했어요.' using errcode = 'P0001';
  end if;

  -- 가장 최근에 사용된 재료의 기록 자리를 결과 장식이 이어받습니다.
  -- record_id 고유 제약과 오늘 장식 재발견 문제를 동시에 피합니다.
  insert into public.garden_dev_found_items (
    user_id,
    record_id,
    item_key,
    placement_slot,
    position_x,
    position_y,
    storage_state,
    found_at
  )
  values (
    v_user_id,
    v_anchor_record_id,
    v_recipe.result_item_key,
    'front_bed_left',
    null,
    null,
    'inventory',
    now()
  )
  returning id::text into v_result_item_id;

  update public.garden_decoration_recipe_exchanges
  set result_item_key = v_recipe.result_item_key,
      result_found_item_id = v_result_item_id,
      consumed_items = v_consumed,
      status = 'completed',
      completed_at = now()
  where id = v_exchange_id;

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'recipe_key', v_recipe.recipe_key,
    'result_item_key', v_recipe.result_item_key,
    'result_found_item_id', v_result_item_id,
    'consumed_items', v_consumed
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.exchange_my_garden_dev_trade_items(p_quantity integer DEFAULT 1)
 RETURNS TABLE(id uuid, item_key text, storage_state text, placement_slot text, position_x numeric, position_y numeric, obtained_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_offer text;
  v_needed integer;
  v_deleted integer;
begin
  if v_user is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 99 then raise exception 'INVALID_QUANTITY'; end if;
  select o.item_key into v_offer from public.get_my_garden_dev_trade_offer() o limit 1;
  v_needed := p_quantity * 3;
  with picked as (
    select f.id
    from public.garden_dev_found_items f
    left join public.garden_records r on r.id = f.record_id
    where f.storage_state = 'inventory'
      and coalesce(to_jsonb(f)->>'user_id', to_jsonb(f)->>'owner_id', to_jsonb(r)->>'user_id', to_jsonb(r)->>'owner_id') = v_user::text
    order by f.created_at asc, f.id asc
    limit v_needed
  ), deleted as (
    delete from public.garden_dev_found_items f
    using picked p
    where f.id = p.id
    returning f.id
  ) select count(*) into v_deleted from deleted;
  if v_deleted <> v_needed then raise exception 'NOT_ENOUGH_BASIC_ITEMS'; end if;
  return query
  insert into public.garden_dev_trade_items (user_id, item_key, storage_state, placement_slot)
  select v_user, v_offer, 'inventory', 'front_bed_right'
  from generate_series(1, p_quantity)
  returning garden_dev_trade_items.id, garden_dev_trade_items.item_key, garden_dev_trade_items.storage_state,
            garden_dev_trade_items.placement_slot, garden_dev_trade_items.position_x, garden_dev_trade_items.position_y,
            garden_dev_trade_items.obtained_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.garden_animal_v2_approach_speed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_is_tree_call boolean := coalesce(current_setting('todayforest.tree_call', true), '') = '1';
  v_entering_approach boolean := false;
  v_dwell interval;
begin
  if tg_op = 'INSERT' then
    v_entering_approach := new.visit_state = 'approaching';
  else
    v_entering_approach := new.visit_state = 'approaching'
      and old.visit_state is distinct from 'approaching';
  end if;

  if not v_is_tree_call
     and v_entering_approach
     and new.arrives_at is not null
     and new.arrives_at > v_now
  then
    if new.leaves_at is not null and new.leaves_at > new.arrives_at then
      v_dwell := new.leaves_at - new.arrives_at;
    end if;

    new.arrives_at := v_now + ((new.arrives_at - v_now) * 0.75);
    if v_dwell is not null then
      new.leaves_at := new.arrives_at + v_dwell;
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.garden_animal_v2_presence_speed_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_changed boolean := false;
begin
  if new.next_event_at is null or new.next_event_at <= v_now then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_changed := true;
  else
    v_changed := new.next_event_at is distinct from old.next_event_at;
  end if;

  if v_changed then
    new.next_event_at := v_now + ((new.next_event_at - v_now) * 0.75);
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.garden_animal_visit_limit(p_growth_count integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when coalesce(p_growth_count, 0) <= 6 then 2
    when coalesce(p_growth_count, 0) <= 13 then 3
    when coalesce(p_growth_count, 0) <= 20 then 4
    when coalesce(p_growth_count, 0) <= 29 then 5
    else 6
  end;
$function$;

