AS $function$
  SELECT CASE p_kind
    WHEN 'bird' THEN 'feather'
    WHEN 'owl' THEN 'moon_feather'
    WHEN 'rabbit' THEN 'footprints'
    WHEN 'fox' THEN 'tiny_pawprints'
    WHEN 'squirrel' THEN 'acorn_shell'
    WHEN 'raccoon' THEN 'berry_peel'
    WHEN 'hedgehog' THEN 'ruffled_leaves'
    WHEN 'mole' THEN 'soft_soil'
    ELSE NULL
  END;
$function$;

