CREATE OR REPLACE FUNCTION public.get_my_forest_codex_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select jsonb_build_object(
    'decorations', coalesce(
      (
        with current_items as (
          select
            found.item_key,
            count(*)::bigint as current_count,
            count(*) filter (where found.storage_state = 'inventory')::bigint as inventory_count,
            count(*) filter (where found.storage_state is distinct from 'inventory')::bigint as placed_count,
            min(coalesce(found.found_at, found.created_at)) as first_current_at,
            max(coalesce(found.found_at, found.created_at)) as last_current_at
          from public.garden_dev_found_items as found
          where found.user_id = v_user_id
          group by found.item_key
        ),
        known_items as (
          select item_key from current_items
          union
          select counts.item_key
          from public.garden_decoration_claim_counts as counts
          where counts.user_id = v_user_id
        )
        select jsonb_agg(
          jsonb_build_object(
            'item_key', known.item_key,
            'claim_count', greatest(
              coalesce(counts.claim_count, 0)::bigint,
              coalesce(current.current_count, 0)::bigint
            ),
            'placed_count', coalesce(current.placed_count, 0)::bigint,
            'inventory_count', coalesce(current.inventory_count, 0)::bigint,
            'current_count', coalesce(current.current_count, 0)::bigint,
            'first_discovered_at', coalesce(counts.first_claimed_at, current.first_current_at),
            'last_discovered_at', greatest(
              coalesce(counts.last_claimed_at, '-infinity'::timestamptz),
              coalesce(current.last_current_at, '-infinity'::timestamptz)
            )
          )
          order by known.item_key
        )
        from known_items as known
        left join current_items as current
          on current.item_key = known.item_key
        left join public.garden_decoration_claim_counts as counts
          on counts.user_id = v_user_id
         and counts.item_key = known.item_key
      ),
      '[]'::jsonb
    ),
    'animals', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'animal_kind', summary.animal_kind,
            'visit_count', summary.visit_count,
            'first_seen_at', summary.first_seen_at,
            'last_seen_at', summary.last_seen_at
          )
          order by summary.first_seen_at, summary.animal_kind
        )
        from (
          select
            visit.animal_kind,
            count(*)::bigint as visit_count,
            min(visit.arrived_at) as first_seen_at,
            max(visit.arrived_at) as last_seen_at
          from public.garden_animal_codex_visits as visit
          where visit.user_id = v_user_id
          group by visit.animal_kind
        ) as summary
      ),
      '[]'::jsonb
    ),
    'generated_at', now()
  )
  into v_result;

  return v_result;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_dev_trade_offer()
 RETURNS TABLE(offer_date date, item_key text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_today date := timezone('Asia/Seoul', now())::date;
  v_item text;
  v_candidates text[];
  v_all text[] := array[
    'flower_meadow','mushroom_grove','mossy_path','leaf_rest','firefly_path','moonlit_mushroom_lamp',
    'letter_branch','forest_mailbox','wind_signpost','ribbon_arch','secret_garden_gate','forest_rest_spot'
  ];
begin
  if v_user is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select o.item_key
    into v_item
  from public.garden_dev_trade_offers as o
  where o.user_id = v_user
    and o.offer_date = v_today;

  if v_item is null then
    select coalesce(
      array_agg(candidate.item_key order by md5(v_user::text || v_today::text || candidate.item_key)),
      array[]::text[]
    )
      into v_candidates
    from unnest(v_all) as candidate(item_key)
    where not exists (
      select 1
      from public.garden_dev_trade_items as owned
      where owned.user_id = v_user
        and owned.item_key = candidate.item_key
    );

    if coalesce(array_length(v_candidates, 1), 0) = 0 then
      v_candidates := v_all;
    end if;

    select candidate.item_key
      into v_item
    from unnest(v_candidates) as candidate(item_key)
    order by md5(v_user::text || v_today::text || candidate.item_key)
    limit 1;

    insert into public.garden_dev_trade_offers (user_id, offer_date, item_key)
    values (v_user, v_today, v_item)
    on conflict on constraint garden_dev_trade_offers_pkey do nothing;

    select o.item_key
      into v_item
    from public.garden_dev_trade_offers as o
    where o.user_id = v_user
      and o.offer_date = v_today;
  end if;

  return query
  select v_today as offer_date, v_item as item_key;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_feedback_admin_access()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin_id constant uuid := '2029663f-4af7-48df-a32e-47f855c9f1e1'::uuid;
begin
  return auth.uid() = v_admin_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_friend_view(p_friend_id uuid)
 RETURNS TABLE(friend_id uuid, nickname text, avatar_url text, growth_count integer, weather_index smallint, became_friends_at timestamp with time zone, is_dev_test boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  -- 개발용 테스트 새싹을 먼저 처리합니다.
  -- avatar_url 컬럼이 없는 이전 테스트 DB에서도 안전하게 열립니다.
  if exists (
    select 1
    from public.garden_dev_test_friends d
    where d.owner_id = v_user_id
      and d.id = p_friend_id
  ) then
    return query
    select
      d.id as friend_id,
      d.nickname,
      null::text as avatar_url,
      d.growth_count,
      0::smallint as weather_index,
      d.created_at as became_friends_at,
      true as is_dev_test
    from public.garden_dev_test_friends d
    where d.owner_id = v_user_id
      and d.id = p_friend_id;
    return;
  end if;

  -- 실제 친구: 서로 친구인 경우에만 나무의 공개 정보만 반환합니다.
  if exists (
    select 1
    from public.garden_friendships f
    where f.user_id = v_user_id
      and f.friend_id = p_friend_id
  ) then
    return query
    select
      f.friend_id,
      coalesce(p.nickname, '친구') as nickname,
      null::text as avatar_url,
      coalesce(p.growth_count, 0) as growth_count,
      coalesce(p.weather_index, 0)::smallint as weather_index,
      f.created_at as became_friends_at,
      false as is_dev_test
    from public.garden_friendships f
    left join public.garden_profiles p
      on p.id = f.friend_id
    where f.user_id = v_user_id
      and f.friend_id = p_friend_id;
    return;
  end if;

  raise exception '친구 정원을 볼 수 없어요.';
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_letter_body(p_letter_id uuid)
 RETURNS TABLE(id uuid, title text, body text, sender_name text, delivery_kind text, sent_at timestamp with time zone, available_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    gl.id,
    gl.title,
    gl.body,
    gl.sender_name,
    gl.delivery_kind,
    gl.sent_at,
    gl.available_at,
    gl.created_at
  from public.garden_letters gl
  where gl.id = p_letter_id
    and gl.recipient_id = auth.uid()
    and gl.read_at is null
    and gl.returned_at is null
    and gl.available_at <= now()
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_shared_tree_v2(p_tree_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_tree public.garden_shared_trees%rowtype;
  v_partner_id uuid;
  v_completed_stage_count integer;
  v_current_stage smallint;
  v_stage_event_count integer;
  v_my_cared_today boolean;
  v_partner_cared_today boolean;
  v_care_counts jsonb;
  v_profile jsonb;
  v_recent_events jsonb;
  v_stage_results jsonb;
  v_my_state jsonb;
  v_both_named boolean;
  v_both_world_consent boolean;
  v_placement jsonb;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  select t.*
  into v_tree
  from public.garden_shared_trees t
  where t.id = p_tree_id
    and v_me in (t.user_one_id, t.user_two_id)
    and t.growth_version = 2
    and t.relationship_ended_at is null;

  if not found then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  v_partner_id := case
    when v_tree.user_one_id = v_me then v_tree.user_two_id
    else v_tree.user_one_id
  end;

  select count(*)::integer
  into v_completed_stage_count
  from public.garden_shared_tree_stage_results r
  where r.tree_id = v_tree.id;

  v_current_stage := case
    when v_tree.completed_at is not null then 4::smallint
    else least(4, v_completed_stage_count + 1)::smallint
  end;

  select count(*)::integer
  into v_stage_event_count
  from public.garden_shared_tree_care_events e
  where e.tree_id = v_tree.id
    and e.stage = v_current_stage;

  select exists (
    select 1
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
      and e.user_id = v_me
      and e.record_date = v_today
  ) into v_my_cared_today;

  select exists (
    select 1
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
      and e.user_id = v_partner_id
      and e.record_date = v_today
  ) into v_partner_cared_today;

  select coalesce(jsonb_object_agg(x.care_type, x.cnt), '{}'::jsonb)
  into v_care_counts
  from (
    select e.care_type, count(*)::integer as cnt
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
      and e.stage = v_current_stage
    group by e.care_type
  ) x;

  select coalesce(
    to_jsonb(p) - 'created_at' - 'updated_at',
    '{}'::jsonb
  )
  into v_profile
  from public.garden_shared_tree_profiles p
  where p.tree_id = v_tree.id;

  v_profile := coalesce(v_profile, '{}'::jsonb);

  select coalesce(jsonb_agg(item order by item_created_at desc), '[]'::jsonb)
  into v_recent_events
  from (
    select
      jsonb_build_object(
        'id', e.id,
        'user_id', e.user_id,
        'is_mine', e.user_id = v_me,
        'stage', e.stage,
        'care_type', e.care_type,
        'choice_key', e.choice_key,
        'record_date', e.record_date,
        'created_at', e.created_at
      ) as item,
      e.created_at as item_created_at
    from public.garden_shared_tree_care_events e
    where e.tree_id = v_tree.id
    order by e.created_at desc
    limit 20
  ) q;

  select coalesce(jsonb_agg(item order by stage), '[]'::jsonb)
  into v_stage_results
  from (
    select
      r.stage,
      jsonb_build_object(
        'stage', r.stage,
        'event_count', r.event_count,
        'participant_count', r.participant_count,
        'cooperative', r.cooperative,
        'completed_at', r.completed_at,
        'summary', r.summary
      ) as item
    from public.garden_shared_tree_stage_results r
    where r.tree_id = v_tree.id
    order by r.stage
  ) q;

  select coalesce(
    jsonb_build_object(
      'birth_scene_seen_at', s.birth_scene_seen_at,
      'name_piece_role', s.name_piece_role,
      'name_piece_key', s.name_piece_key,
      'name_piece_at', s.name_piece_at,
      'world_consent', s.world_consent,
      'world_consent_at', s.world_consent_at,
      'last_viewed_at', s.last_viewed_at
    ),
    '{}'::jsonb
  )
  into v_my_state
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id
    and s.user_id = v_me;

  v_my_state := coalesce(v_my_state, '{}'::jsonb);

  select count(*) = 2
  into v_both_named
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id
    and s.name_piece_key is not null;

  select count(*) = 2
  into v_both_world_consent
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id
    and s.world_consent is true;

  select coalesce(
    jsonb_build_object(
      'placement_state', w.placement_state,
      'trail_key', w.trail_key,
      'slot_key', w.slot_key,
      'position_x', w.position_x,
      'position_y', w.position_y,
      'position_z', w.position_z,
      'rotation_y', w.rotation_y,
      'placed_at', w.placed_at,
      'hidden_at', w.hidden_at
    ),
    '{}'::jsonb
  )
  into v_placement
  from public.garden_shared_tree_world_placements w
  where w.tree_id = v_tree.id;

  v_placement := coalesce(v_placement, '{}'::jsonb);

  update public.garden_shared_tree_member_states
  set last_viewed_at = now(),
      updated_at = now()
  where tree_id = v_tree.id
    and user_id = v_me;

  return jsonb_build_object(
    'tree_id', v_tree.id,
    'partner_id', v_partner_id,
    'growth_version', v_tree.growth_version,
    'status', case
      when v_tree.completed_at is not null then 'completed'
      else 'growing'
    end,
    'current_stage', v_current_stage,
    'stage_event_count', v_stage_event_count,
    'stage_event_target', 5,
    'completed_stage_count', v_completed_stage_count,
    'created_at', v_tree.created_at,
    'completed_at', v_tree.completed_at,
    'my_cared_today', v_my_cared_today,
    'partner_cared_today', v_partner_cared_today,
    'care_counts', v_care_counts,
    'profile', v_profile,
    'recent_events', v_recent_events,
    'stage_results', v_stage_results,
    'my_member_state', v_my_state,
    'both_name_pieces_ready', v_both_named,
    'both_world_consent', v_both_world_consent,
    'placement', v_placement
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_special_friend_letter_body_v1(p_letter_id uuid)
 RETURNS TABLE(body text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  select l.body
  from public.garden_special_friend_letters l
  where l.id = p_letter_id
    and l.recipient_id = v_me
    and l.available_at <= now()
    and l.read_at is null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_my_garden_tree_call_status_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_state public.garden_tree_animal_call_state_v1%rowtype;
  v_busy boolean := false;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  insert into public.garden_tree_animal_call_state_v1 (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  update public.garden_tree_animal_call_state_v1
  set pending_visit_id = null,
      pending_arrives_at = null,
      updated_at = now()
  where user_id = v_user_id
    and pending_arrives_at is not null
    and pending_arrives_at <= now();

  select * into v_state
  from public.garden_tree_animal_call_state_v1
  where user_id = v_user_id;

  select exists (
    select 1
    from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state in ('approaching', 'visiting', 'departing')
  ) into v_busy;

  return jsonb_build_object(
    'server_now', now(),
    'cooldown_until', v_state.cooldown_until,
    'pending_visit_id', v_state.pending_visit_id,
    'pending_arrives_at', v_state.pending_arrives_at,
    'has_active_visit', v_busy
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_garden_feedback_for_admin(p_status text DEFAULT 'all'::text, p_category text DEFAULT 'all'::text)
 RETURNS TABLE(feedback_id uuid, nickname_snapshot text, category text, message text, created_at timestamp with time zone, operator_status text, operator_read_at timestamp with time zone, operator_reply text, operator_replied_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin_id constant uuid := '2029663f-4af7-48df-a32e-47f855c9f1e1'::uuid;
  v_status text := lower(btrim(coalesce(p_status, 'all')));
  v_category text := lower(btrim(coalesce(p_category, 'all')));
begin
  if auth.uid() is distinct from v_admin_id then
    raise exception 'FEEDBACK_ADMIN_ONLY';
  end if;

  if v_status not in ('all', 'new', 'read', 'replied') then
    raise exception 'INVALID_FEEDBACK_STATUS';
  end if;

  if v_category not in ('all', 'issue', 'idea', 'cheer') then
    raise exception 'INVALID_FEEDBACK_CATEGORY';
  end if;

  return query
  select
    feedback.id,
    feedback.nickname_snapshot,
    feedback.category,
    feedback.message,
    feedback.created_at,
    feedback.operator_status,
    feedback.operator_read_at,
    feedback.operator_reply,
    feedback.operator_replied_at
  from public.garden_feedback as feedback
  where (v_status = 'all' or feedback.operator_status = v_status)
    and (v_category = 'all' or feedback.category = v_category)
  order by feedback.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_dev_test_sent_letters()
 RETURNS TABLE(id uuid, recipient_name text, title text, delivery_kind text, sent_at timestamp with time zone, available_at timestamp with time zone, read_at timestamp with time zone, is_dev_test boolean)
