 RETURNS TABLE(feedback_id uuid, category text, message text, created_at timestamp with time zone, operator_reply text, operator_replied_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
