CREATE OR REPLACE FUNCTION public.list_my_garden_friend_dev_found_items(p_friend_id uuid)
 RETURNS TABLE(id uuid, item_key text, placement_slot text, position_x numeric, position_y numeric, found_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_friend_id is null or p_friend_id = v_user_id then
    raise exception 'GARDEN_FRIEND_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.get_my_garden_friend_view(p_friend_id)
  ) then
    raise exception 'GARDEN_FRIEND_REQUIRED';
  end if;

  return query
  select
    item.id,
    item.item_key,
    item.placement_slot,
    item.position_x,
    item.position_y,
    item.found_at,
    item.created_at
  from public.garden_dev_found_items as item
  where item.user_id = p_friend_id
    and item.storage_state = 'placed'
  order by item.created_at asc, item.id asc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_friend_dev_placed_items(p_friend_id uuid)
 RETURNS TABLE(id uuid, item_key text, placement_slot text, position_x double precision, position_y double precision)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    source.id,
    source.item_key,
    source.placement_slot,
    source.position_x::double precision,
    source.position_y::double precision
  from public.list_my_garden_friend_dev_found_items(p_friend_id) as source
  join public.garden_dev_found_items as item
    on item.id = source.id
  where item.storage_state = 'placed'
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_friend_fruits(p_friend_id uuid)
 RETURNS TABLE(id uuid, mood text, one_line text, detail text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_friend_id is null or p_friend_id = auth.uid() then
    raise exception 'INVALID_GARDEN_FRIEND';
  end if;

  -- 현재 친구 관계가 유지되는 상대만 읽을 수 있습니다.
  if not exists (
    select 1
    from public.list_my_garden_friends() f
    where f.friend_id = p_friend_id
  ) then
    raise exception 'GARDEN_FRIEND_REQUIRED';
  end if;

  -- 나무가 완성되기 전에는 공개 표시를 켜더라도 열매 목록을 내보내지 않습니다.
  if not exists (
    select 1
    from public.garden_profiles p
    where p.id = p_friend_id
      and coalesce(p.growth_count, 0) >= 30
  ) then
    return;
  end if;

  return query
  select
    r.id,
    r.mood,
    r.one_line,
    r.detail,
    r.created_at
  from public.garden_records r
  where r.user_id = p_friend_id
    and r.is_public = true
  order by r.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_friend_requests()
 RETURNS TABLE(request_id uuid, direction text, other_user_id uuid, other_nickname text, created_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.garden_friend_requests r
  set status = 'expired', responded_at = now()
  where r.status = 'pending'
    and r.expires_at <= now()
    and v_me in (r.from_user_id, r.to_user_id);

  -- 이미 친구가 된 뒤 상태 갱신만 놓친 신청도 조용히 닫습니다.
  update public.garden_friend_requests r
  set status = 'accepted', responded_at = coalesce(r.responded_at, now())
  where r.status = 'pending'
    and v_me in (r.from_user_id, r.to_user_id)
    and exists (
      select 1 from public.list_my_garden_friends() f
      where f.friend_id = case when r.from_user_id = v_me then r.to_user_id else r.from_user_id end
    );

  return query
  select
    r.id,
    case when r.to_user_id = v_me then 'incoming' else 'outgoing' end,
    case when r.to_user_id = v_me then r.from_user_id else r.to_user_id end,
    case when r.to_user_id = v_me then r.from_nickname else r.to_nickname end,
    r.created_at,
    r.expires_at
  from public.garden_friend_requests r
  where r.status = 'pending'
    and v_me in (r.from_user_id, r.to_user_id)
  order by (r.to_user_id = v_me) desc, r.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_friends()
 RETURNS TABLE(friend_id uuid, nickname text, avatar_url text, growth_count integer, became_friends_at timestamp with time zone, is_dev_test boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  return query
  select
    friendship.friend_id,
    coalesce(profile.nickname, '친구') as nickname,
    profile.avatar_url,
    coalesce(profile.growth_count, 0) as growth_count,
    friendship.created_at as became_friends_at,
    false as is_dev_test
  from public.garden_friendships as friendship
  left join public.garden_profiles as profile
    on profile.id = friendship.friend_id
  where friendship.user_id = auth.uid()

  union all

  select
    dev_friend.id,
    dev_friend.nickname,
    dev_friend.avatar_url,
    dev_friend.growth_count,
    dev_friend.created_at as became_friends_at,
    true as is_dev_test
  from public.garden_dev_test_friends as dev_friend
  where dev_friend.owner_id = auth.uid()

  order by became_friends_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_retention_dev_tests()
 RETURNS TABLE(id bigint, scenario text, sender_name text, title text, body text, delivery_kind text, available_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    t.id,
    t.scenario,
    t.sender_name,
    t.title,
    t.body,
    t.delivery_kind,
    t.available_at,
    t.created_at
  from public.garden_letter_retention_dev_tests t
  where t.owner_id = auth.uid()
  order by t.created_at asc;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_shared_tree_invites()
 RETURNS TABLE(invite_id uuid, direction text, other_user_id uuid, created_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    i.id,
    case when i.to_user_id = auth.uid() then 'incoming' else 'outgoing' end,
    case when i.to_user_id = auth.uid() then i.from_user_id else i.to_user_id end,
    i.created_at
  from public.garden_shared_tree_invites i
  where i.status = 'pending'
    and auth.uid() in (i.from_user_id, i.to_user_id)
    and exists (
      select 1
      from public.garden_friendships f
      where f.user_id = auth.uid()
        and f.friend_id = case
          when i.to_user_id = auth.uid() then i.from_user_id
          else i.to_user_id
        end
    )
  order by i.created_at desc;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_shared_tree_notes()
 RETURNS TABLE(tree_id uuid, author_id uuid, note_body text, is_mine boolean, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  select
    n.tree_id,
    n.user_id,
    n.body,
    (n.user_id = v_me),
    n.created_at,
    n.updated_at
  from public.garden_shared_tree_notes n
  join public.garden_shared_trees t
    on t.id = n.tree_id
  where v_me in (t.user_one_id, t.user_two_id)
    and t.relationship_ended_at is null
  order by n.created_at asc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_shared_trees()
 RETURNS TABLE(tree_id uuid, partner_id uuid, progress_count integer, target_steps integer, created_at timestamp with time zone, completed_at timestamp with time zone, my_recorded_today boolean, partner_recorded_today boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    t.id,
    case when t.user_one_id = auth.uid() then t.user_two_id else t.user_one_id end,
    least(t.target_steps::integer, coalesce(lights.progress_count, 0)),
    t.target_steps::integer,
    t.created_at,
    t.completed_at,
    coalesce(lights.my_recorded_today, false),
    coalesce(lights.partner_recorded_today, false)
  from public.garden_shared_trees t
  left join lateral (
    select
      count(*)::integer as progress_count,
      bool_or(
        r.user_id = auth.uid()
        and r.record_date = (now() at time zone 'Asia/Seoul')::date
      ) as my_recorded_today,
      bool_or(
        r.user_id = case
          when t.user_one_id = auth.uid() then t.user_two_id
          else t.user_one_id
        end
        and r.record_date = (now() at time zone 'Asia/Seoul')::date
      ) as partner_recorded_today
    from public.garden_shared_tree_light_records r
    where r.tree_id = t.id
  ) lights on true
  where auth.uid() in (t.user_one_id, t.user_two_id)
    and t.relationship_ended_at is null
  order by t.created_at desc;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_shared_trees_v2()
 RETURNS TABLE(tree_id uuid, partner_id uuid, current_stage smallint, stage_event_count integer, completed_stage_count integer, created_at timestamp with time zone, completed_at timestamp with time zone, my_cared_today boolean, partner_cared_today boolean, final_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  select
    t.id,
    case when t.user_one_id = v_me then t.user_two_id else t.user_one_id end,
    case
      when t.completed_at is not null then 4::smallint
      else least(4, coalesce(sr.completed_stage_count, 0) + 1)::smallint
    end,
    case
      when t.completed_at is not null then 5
      else coalesce(ce.stage_event_count, 0)
    end,
    coalesce(sr.completed_stage_count, 0),
    t.created_at,
    t.completed_at,
    exists (
      select 1
      from public.garden_shared_tree_care_events mine
      where mine.tree_id = t.id
        and mine.user_id = v_me
        and mine.record_date = v_today
    ),
    exists (
      select 1
      from public.garden_shared_tree_care_events partner
      where partner.tree_id = t.id
        and partner.user_id = case
          when t.user_one_id = v_me then t.user_two_id
          else t.user_one_id
        end
        and partner.record_date = v_today
    ),
    p.final_name
  from public.garden_shared_trees t
  left join public.garden_shared_tree_profiles p
    on p.tree_id = t.id
  left join lateral (
    select count(*)::integer as completed_stage_count
    from public.garden_shared_tree_stage_results x
    where x.tree_id = t.id
  ) sr on true
  left join lateral (
    select count(*)::integer as stage_event_count
    from public.garden_shared_tree_care_events x
    where x.tree_id = t.id
      and x.stage = case
        when t.completed_at is not null then 4
        else least(4, coalesce(sr.completed_stage_count, 0) + 1)
      end
  ) ce on true
  where v_me in (t.user_one_id, t.user_two_id)
    and t.growth_version = 2
    and t.relationship_ended_at is null
  order by t.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_garden_special_friend_letters_v1()
 RETURNS TABLE(id uuid, direction text, sender_name text, recipient_name text, friend_key text, title text, sent_at timestamp with time zone, available_at timestamp with time zone, return_at timestamp with time zone, read_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 읽은 편지는 읽은 시점부터 30일, 미열람은 도착 후 30일이 지나면 정리합니다.
  -- 사용자가 다시 정원에 들어왔을 때만 실행되는 조용한 정리입니다.
  delete from public.garden_special_friend_letters l
  where l.recipient_id = v_me
    and (
      (l.read_at is not null and l.read_at <= now() - interval '30 days')
      or (l.read_at is null and l.available_at <= now() - interval '30 days')
    );

  return query
  select * from (
    select
      l.id,
      'received'::text as direction,
      l.sender_name,
      l.recipient_name,
      l.friend_key,
      l.title,
      l.sent_at,
      l.available_at,
      l.return_at,
      l.read_at,
      l.created_at
    from public.garden_special_friend_letters l
    where l.recipient_id = v_me
      and l.available_at <= now()
      and l.read_at is null

    union all

    select
      l.id,
      'sent'::text as direction,
      l.sender_name,
      l.recipient_name,
      l.friend_key,
      l.title,
      l.sent_at,
      l.available_at,
      l.return_at,
      l.read_at,
      l.created_at
    from public.garden_special_friend_letters l
    where l.sender_id = v_me
      and l.return_at > now()
  ) visible_letters
  order by sent_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_sent_garden_letters()
 RETURNS TABLE(id uuid, recipient_name text, title text, delivery_kind text, sent_at timestamp with time zone, available_at timestamp with time zone, read_at timestamp with time zone, is_dev_test boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  return query
  select
    letter.id,
    coalesce(profile.nickname::text, '친구'::text) as recipient_name,
    letter.title::text as title,
    letter.delivery_kind::text as delivery_kind,
    letter.sent_at,
    letter.available_at,
    letter.read_at,
    false as is_dev_test
  from public.garden_letters as letter
  left join public.garden_profiles as profile
    on profile.id = letter.recipient_id
  where letter.sender_id = auth.uid()

  union all

  select
    dev_letter.id,
    dev_friend.nickname::text as recipient_name,
    dev_letter.title::text as title,
    dev_letter.delivery_kind::text as delivery_kind,
    dev_letter.sent_at,
    dev_letter.available_at,
    dev_letter.read_at,
    true as is_dev_test
  from public.garden_dev_test_letters as dev_letter
  join public.garden_dev_test_friends as dev_friend
    on dev_friend.id = dev_letter.test_friend_id
  where dev_letter.owner_id = auth.uid()

  order by sent_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_sent_garden_letters_v2()
 RETURNS TABLE(id uuid, recipient_name text, title text, delivery_kind text, sent_at timestamp with time zone, available_at timestamp with time zone, read_at timestamp with time zone, returned_at timestamp with time zone, return_reason text, return_seen_at timestamp with time zone, is_dev_test boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  return query
  select
    letter.id,
    coalesce(profile.nickname::text, '친구'::text) as recipient_name,
    letter.title::text,
    letter.delivery_kind::text,
    letter.sent_at,
    letter.available_at,
    letter.read_at,
    letter.returned_at,
    letter.return_reason,
    letter.return_seen_at,
    false as is_dev_test
  from public.garden_letters as letter
  left join public.garden_profiles as profile
    on profile.id = letter.recipient_id
  where letter.sender_id = auth.uid()
    and (
      (letter.returned_at is null and letter.available_at > now())
      or
      (letter.returned_at is not null and letter.return_seen_at is null)
    )

  union all

  select
    dev_letter.id,
    dev_friend.nickname::text,
    dev_letter.title::text,
    dev_letter.delivery_kind::text,
    dev_letter.sent_at,
    dev_letter.available_at,
    dev_letter.read_at,
    null::timestamptz,
    null::text,
    null::timestamptz,
    true as is_dev_test
  from public.garden_dev_test_letters as dev_letter
  join public.garden_dev_test_friends as dev_friend
    on dev_friend.id = dev_letter.test_friend_id
  where dev_letter.owner_id = auth.uid()
    and dev_letter.available_at > now()

  order by sent_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_my_unseen_garden_shared_tree_start_moments()
 RETURNS TABLE(tree_id uuid, partner_id uuid, scene_role text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  select
    m.tree_id,
    case when m.proposed_by = v_me then m.accepted_by else m.proposed_by end,
    case when m.accepted_by = v_me then 'accepted' else 'proposed' end,
    m.created_at
  from public.garden_shared_tree_start_moments m
  join public.garden_shared_trees t
    on t.id = m.tree_id
  where v_me in (m.proposed_by, m.accepted_by)
    and t.relationship_ended_at is null
    and not exists (
      select 1
      from public.garden_shared_tree_start_moment_views v
      where v.tree_id = m.tree_id
        and v.user_id = v_me
    )
  order by m.created_at asc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.lock_garden_tree_name_after_first_save()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(btrim(old.tree_name), '') <> ''
     and new.tree_name is distinct from old.tree_name then
    raise exception 'TREE_NAME_LOCKED';
  end if;

  if new.tree_name is not null then
    new.tree_name := btrim(new.tree_name);
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_dev_test_garden_letter_read(p_letter_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  update public.garden_dev_test_letters
  set read_at = coalesce(read_at, now())
  where id = p_letter_id
    and owner_id = auth.uid();

  if not found then
    raise exception '테스트 편지를 찾지 못했어요.';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_garden_feedback_read(p_feedback_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin_id constant uuid := '2029663f-4af7-48df-a32e-47f855c9f1e1'::uuid;
  v_found boolean := false;
begin
  if auth.uid() is distinct from v_admin_id then
    raise exception 'FEEDBACK_ADMIN_ONLY';
  end if;

  update public.garden_feedback
  set
    operator_status = case
      when operator_status = 'new' then 'read'
      else operator_status
    end,
    operator_read_at = coalesce(operator_read_at, now())
  where id = p_feedback_id
  returning true into v_found;

  return coalesce(v_found, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_my_garden_shared_tree_start_moment_seen(p_tree_id uuid)
 RETURNS TABLE(tree_id uuid, seen_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_START_MOMENT_NOT_FOUND';
  end if;

  if not exists (
    select 1
    from public.garden_shared_tree_start_moments m
    join public.garden_shared_trees t
      on t.id = m.tree_id
    where m.tree_id = p_tree_id
      and v_me in (m.proposed_by, m.accepted_by)
      and t.relationship_ended_at is null
  ) then
    raise exception 'SHARED_TREE_START_MOMENT_NOT_FOUND';
  end if;

  insert into public.garden_shared_tree_start_moment_views as v (
    tree_id,
    user_id
  )
  values (
    p_tree_id,
    v_me
  )
  on conflict on constraint garden_shared_tree_start_moment_views_one_per_person
  do nothing;

  return query
  select v.tree_id, v.seen_at
  from public.garden_shared_tree_start_moment_views v
  where v.tree_id = p_tree_id
    and v.user_id = v_me;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_my_returned_garden_letters_seen(p_letter_ids uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_updated integer := 0;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if p_letter_ids is null or cardinality(p_letter_ids) = 0 then
    return 0;
  end if;

  update public.garden_letters
  set return_seen_at = coalesce(return_seen_at, now())
  where sender_id = auth.uid()
    and returned_at is not null
    and id = any(p_letter_ids);

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_accept_invite(p_invite_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_invite public.oot_invites%rowtype;
  v_match_id uuid;
  v_starter uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('oot_random_matchmaking_v1'));

  select * into v_invite
  from public.oot_invites
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending'
  for update;

  if not found then
    raise exception 'OOT_INVITE_NOT_FOUND';
  end if;

  if v_invite.expires_at <= now() then
    update public.oot_invites
    set status = 'expired', responded_at = now()
    where id = v_invite.id;

    raise exception 'OOT_INVITE_EXPIRED';
  end if;

  if not exists (
    select 1
    from public.list_my_garden_friends() f
    where f.friend_id = v_invite.from_user_id
      and coalesce(f.is_dev_test, false) = false
  ) then
    raise exception 'OOT_FRIEND_REQUIRED';
  end if;

  if coalesce(v_invite.battle_mode, 'casual') = 'rated'
     and public.oot_count_pair_rated_matches_today(
       v_invite.from_user_id,
       v_me
     ) >= 3 then
    raise exception 'OOT_DAILY_RATED_LIMIT_REACHED';
  end if;

  -- 어느 한쪽이라도 이미 다른 경기 중이면 두 번째 방을 만들지 않습니다.
  if exists (
    select 1
    from public.oot_matches m
    where m.status = 'active'
      and (
        v_invite.from_user_id in (m.player_one_id, m.player_two_id)
        or v_me in (m.player_one_id, m.player_two_id)
      )
  ) then
    raise exception 'OOT_PLAYER_ALREADY_IN_MATCH';
  end if;

  delete from public.oot_random_match_queue
  where user_id in (v_invite.from_user_id, v_me)
    and status = 'waiting';

  v_starter := case
    when random() < 0.5 then v_invite.from_user_id
    else v_me
  end;

  insert into public.oot_matches (
    player_one_id,
    player_two_id,
    starter_id,
    current_turn_id,
    status,
    phase,
    turn_deadline,
    battle_mode,
    point_rules_version,
    player_one_ready_at,
    player_two_ready_at,
    countdown_started_at,
    play_starts_at,
    play_started_at,
    match_source
  )
  values (
    v_invite.from_user_id,
    v_me,
    v_starter,
    null,
    'active',
    'opening',
    null,
    coalesce(v_invite.battle_mode, 'casual'),
    case
      when coalesce(v_invite.battle_mode, 'casual') = 'rated'
        then 'one_point_v1'
      else null
    end,
    null,
    null,
    null,
    null,
    null,
    'friend'
  )
  returning id into v_match_id;

  insert into public.oot_match_private_states (
    match_id,
    deck,
    player_one_hand,
    player_two_hand
  )
  values (
    v_match_id,
    '{}'::smallint[],
    '{}'::smallint[],
    '{}'::smallint[]
  );

  update public.oot_invites
  set
    status = 'accepted',
    responded_at = now(),
    match_id = v_match_id
  where id = v_invite.id;

  update public.oot_invites
  set
    status = 'cancelled',
    responded_at = now()
  where id <> v_invite.id
    and status = 'pending'
    and (
      from_user_id in (v_invite.from_user_id, v_me)
      or to_user_id in (v_invite.from_user_id, v_me)
    );

  return v_match_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_ack_invite(p_invite_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_invites
  set
    receiver_seen_at = coalesce(receiver_seen_at, now()),
    in_app_delivered_at = coalesce(in_app_delivered_at, now()),
    push_status = case
      when push_status = 'pending'
       and push_sent_at is null
        then 'not_needed'
      else push_status
    end,
    push_due_at = case
      when push_status = 'pending'
       and push_sent_at is null
        then null
      else push_due_at
    end
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending'
    and expires_at > now();

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_ack_random_matchmaking(p_match_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.oot_matches m
    where m.id = p_match_id
      and v_me in (m.player_one_id, m.player_two_id)
  ) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  delete from public.oot_random_match_queue q
  where q.user_id = v_me
    and q.match_id = p_match_id;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_apply_friend_point_result_locked(p_match_id uuid, p_user_id uuid, p_opponent_id uuid, p_result_type text, p_exact_hit boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stats public.oot_player_stats%rowtype;
  v_base_delta integer;
  v_candidate_point integer;
  v_floor integer;
  v_point_after integer;
  v_peak_after integer;
  v_final_delta integer;
  v_protection_amount integer := 0;
  v_beginner_applied boolean := false;
  v_tier_floor_applied boolean := false;
  v_tier_after text;
  v_new_streak integer;
begin
  if p_result_type is null
     or p_result_type not in ('win', 'draw', 'loss') then
    raise exception 'OOT_INVALID_POINT_RESULT';
  end if;

  select *
    into v_stats
  from public.oot_player_stats
  where user_id = p_user_id;

  if not found then
    raise exception 'OOT_PLAYER_STATS_MISSING';
  end if;

  v_base_delta :=
    case p_result_type
      when 'win' then 5
      when 'draw' then 1
      else -3
    end;

  v_floor := public.oot_point_floor_for_peak(v_stats.peak_one_point);

  if p_result_type = 'loss'
     and v_stats.beginner_protection_remaining > 0 then
    v_beginner_applied := true;
    v_point_after := v_stats.one_point;
    v_protection_amount := abs(v_base_delta);
  else
    v_candidate_point := v_stats.one_point + v_base_delta;
    v_point_after := greatest(v_candidate_point, v_floor, 0);

    if v_point_after > v_candidate_point then
      v_tier_floor_applied := true;
      v_protection_amount := v_point_after - v_candidate_point;
    end if;
  end if;

  v_final_delta := v_point_after - v_stats.one_point;

  -- 0점 하한 또는 보호 규칙으로 줄지 않은 점수까지 정확히 기록합니다.
  if v_base_delta < 0 then
    v_protection_amount := greatest(v_final_delta - v_base_delta, 0);
  end if;

  v_peak_after := greatest(v_stats.peak_one_point, v_point_after);
  v_tier_after := public.oot_point_tier_for(v_point_after);

  v_new_streak :=
    case p_result_type
      when 'win' then v_stats.current_win_streak + 1
      when 'draw' then v_stats.current_win_streak
      else 0
    end;

  update public.oot_player_stats
  set
    one_point = v_point_after,
    peak_one_point = v_peak_after,
    tier_key = v_tier_after,
    point_matches = point_matches + 1,
    wins = wins + case when p_result_type = 'win' then 1 else 0 end,
    draws = draws + case when p_result_type = 'draw' then 1 else 0 end,
    losses = losses + case when p_result_type = 'loss' then 1 else 0 end,
    current_win_streak = v_new_streak,
    max_win_streak = greatest(max_win_streak, v_new_streak),
    beginner_protection_remaining =
      greatest(beginner_protection_remaining - 1, 0),
    exact_hits = exact_hits + case when coalesce(p_exact_hit, false) then 1 else 0 end
  where user_id = p_user_id;

  insert into public.oot_point_ledger (
    settlement_key,
    online_match_id,
    user_id,
    opponent_user_id,
    source_mode,
    result_type,
    point_before,
    base_delta,
    streak_bonus,
    protection_amount,
    final_delta,
    point_after,
    peak_after,
    tier_before,
    tier_after,
    beginner_protection_applied,
    tier_floor_applied,
    exact_hit,
    reason,
    rules_version
  )
  values (
    p_match_id,
    p_match_id,
    p_user_id,
    p_opponent_id,
    'friend_rated',
    p_result_type,
    v_stats.one_point,
    v_base_delta,
    0,
    v_protection_amount,
    v_final_delta,
    v_point_after,
    v_peak_after,
    v_stats.tier_key,
    v_tier_after,
    v_beginner_applied,
    v_tier_floor_applied,
    coalesce(p_exact_hit, false),
    'friend_rated_' || p_result_type,
    'one_point_v1'
  );

  if v_peak_after >= 30 then
    insert into public.oot_reward_unlocks (
      user_id, reward_key, unlock_point
    )
    values (
      p_user_id, 'badge_calculation_sprout', 30
    )
    on conflict (user_id, reward_key) do nothing;
  end if;

  if v_peak_after >= 80 then
    insert into public.oot_reward_unlocks (
      user_id, reward_key, unlock_point
    )
    values (
      p_user_id, 'card_back_formula_branch', 80
    )
    on conflict (user_id, reward_key) do nothing;
  end if;

  if v_peak_after >= 150 then
    insert into public.oot_reward_unlocks (
      user_id, reward_key, unlock_point
    )
    values (
      p_user_id, 'result_frame_number_tree', 150
    )
    on conflict (user_id, reward_key) do nothing;
  end if;

  if v_peak_after >= 250 then
    insert into public.oot_reward_unlocks (
      user_id, reward_key, unlock_point
    )
    values (
      p_user_id, 'stop_effect_one_of_ten_master', 250
    )
    on conflict (user_id, reward_key) do nothing;
  end if;

  if v_peak_after >= 400 then
    insert into public.oot_reward_unlocks (
      user_id, reward_key, unlock_point
    )
    values (
      p_user_id, 'title_forest_keeper', 400
    )
    on conflict (user_id, reward_key) do nothing;
  end if;

  return jsonb_build_object(
    'resultType', p_result_type,
    'pointBefore', v_stats.one_point,
    'baseDelta', v_base_delta,
    'streakBonus', 0,
    'protectionAmount', v_protection_amount,
    'finalDelta', v_final_delta,
    'pointAfter', v_point_after,
    'peakAfter', v_peak_after,
    'tierBefore', v_stats.tier_key,
    'tierAfter', v_tier_after,
    'beginnerProtectionApplied', v_beginner_applied,
    'tierFloorApplied', v_tier_floor_applied,
    'exactHit', coalesce(p_exact_hit, false)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_apply_operation(p_before integer, p_operation text, p_number smallint)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if p_before is null or p_number is null then
    raise exception 'OOT_INVALID_CALCULATION';
  end if;

  case p_operation
    when '+' then return p_before + p_number;
    when '-' then return p_before - p_number;
    when '×' then return p_before * p_number;
    when '÷' then return p_before / p_number; -- PostgreSQL 정수 나눗셈: 0 방향으로 버림
    else raise exception 'OOT_INVALID_OPERATION';
  end case;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_cancel_invite(p_invite_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_invites
  set status = 'cancelled', responded_at = now()
  where id = p_invite_id
    and from_user_id = v_me
    and status = 'pending';

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_cancel_random_matchmaking()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_queue public.oot_random_match_queue%rowtype;
  v_match public.oot_matches%rowtype;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('oot_random_matchmaking_v1'));

  select * into v_queue
  from public.oot_random_match_queue q
  where q.user_id = v_me
  for update;

  if not found then
    return jsonb_build_object(
      'status', 'idle',
      'cancelled', false,
      'serverNow', now()
    );
  end if;

  if v_queue.status = 'matched' and v_queue.match_id is not null then
    select * into v_match
    from public.oot_matches m
    where m.id = v_queue.match_id
      and m.status = 'active'
      and v_me in (m.player_one_id, m.player_two_id);

    if found then
      return jsonb_build_object(
        'status', 'matched',
        'cancelled', false,
        'matchId', v_match.id,
        'matchSource', coalesce(v_match.match_source, 'random'),
        'battleMode', coalesce(v_match.battle_mode, 'rated'),
        'serverNow', now()
      );
    end if;
  end if;

  delete from public.oot_random_match_queue
  where user_id = v_me;

  return jsonb_build_object(
    'status', 'idle',
    'cancelled', true,
    'serverNow', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_cancel_waiting_match(p_match_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'active'
     or v_match.phase <> 'opening'
     or v_match.current_turn_id is not null
     or v_match.turn_deadline is not null
     or v_match.current_value is not null
     or v_match.version <> 0 then
    raise exception 'OOT_MATCH_NOT_WAITING';
  end if;

  if v_match.play_starts_at is not null then
    raise exception 'OOT_WAITING_MATCH_CANCEL_LOCKED';
  end if;

  update public.oot_matches
  set
    status = 'cancelled',
    current_turn_id = null,
    turn_deadline = null,
    player_one_ready_at = null,
    player_two_ready_at = null,
    countdown_started_at = null,
    play_starts_at = null,
    finish_reason = 'waiting_cancelled',
    finished_at = now()
  where id = p_match_id;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_claim_due_push_invites(p_limit integer DEFAULT 20)
 RETURNS TABLE(invite_id uuid, from_user_id uuid, to_user_id uuid, expires_at timestamp with time zone, delivery_mode text, subscriptions jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  with due as (
    select i.id
    from public.oot_invites i
    where i.status = 'pending'
      and i.expires_at > now()
      and i.receiver_seen_at is null
      and i.push_status = 'pending'
      and i.push_due_at <= now()
      and exists (
        select 1
        from public.oot_push_subscriptions s
        where s.user_id = i.to_user_id
          and s.enabled = true
      )
    order by i.push_due_at, i.created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 20), 100))
  ),
  claimed as (
    update public.oot_invites i
    set
      push_status = 'processing',
      push_requested_at = now(),
      push_attempts = i.push_attempts + 1
    from due
    where i.id = due.id
    returning i.*
  )
  select
    c.id,
    c.from_user_id,
    c.to_user_id,
    c.expires_at,
    c.delivery_mode,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'subscriptionId', s.id,
            'endpoint', s.endpoint,
            'p256dh', s.p256dh,
            'auth', s.auth_secret
          )
          order by s.created_at
        )
        from public.oot_push_subscriptions s
        where s.user_id = c.to_user_id
          and s.enabled = true
      ),
      '[]'::jsonb
    )
  from claimed c;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_claim_match_acorns(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_result text;
  v_amount integer;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;
  if p_match_id is null then
    raise exception 'MATCH_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
    and v_user_id in (player_one_id, player_two_id);

  if not found then
    raise exception 'MATCH_NOT_FOUND';
  end if;
  if v_match.status <> 'finished' and v_match.phase <> 'finished' then
    raise exception 'MATCH_NOT_FINISHED';
  end if;

  if v_match.winner_id is null then
    v_result := 'draw';
    v_amount := 2;
  elsif v_match.winner_id = v_user_id then
    v_result := 'win';
    v_amount := 3;
  else
    v_result := 'lose';
    v_amount := 1;
  end if;

  return public._oot_award_my_acorns(
    'player_match',
    p_match_id::text,
    v_amount,
    v_result,
    '원오브텐 사용자 대전',
    jsonb_build_object(
      'mode', coalesce(v_match.battle_mode, 'casual'),
      'matchSource', coalesce(v_match.match_source, 'friend'),
      'roundNumber', coalesce(v_match.round_number, 1)
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_claim_squirrel_acorns(p_run_id text, p_result text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_run_id text := trim(coalesce(p_run_id, ''));
  v_result text := lower(trim(coalesce(p_result, '')));
  v_amount integer;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;
  if length(v_run_id) < 8 or length(v_run_id) > 120 then
    raise exception 'INVALID_RUN_ID';
  end if;
  if v_result not in ('win', 'draw', 'lose') then
    raise exception 'INVALID_RESULT';
  end if;

  v_amount := case v_result when 'win' then 3 when 'draw' then 2 else 1 end;

  return public._oot_award_my_acorns(
    'squirrel_match',
    v_run_id,
    v_amount,
    v_result,
    '원오브텐 다람쥐 대전',
    jsonb_build_object('mode', 'squirrel')
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_closest_card(p_hand smallint[], p_value integer)
 RETURNS smallint
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select card
  from unnest(coalesce(p_hand, '{}'::smallint[])) as card
  order by abs(card::integer - p_value), card
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.oot_count_pair_rated_matches_today(p_user_a uuid, p_user_b uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::integer
  from public.oot_matches m
  where m.battle_mode = 'rated'
    and m.status = 'finished'
    and m.point_settled_at is not null
    and m.point_ineligible_reason is null
    and least(m.player_one_id, m.player_two_id) = least(p_user_a, p_user_b)
    and greatest(m.player_one_id, m.player_two_id) = greatest(p_user_a, p_user_b)
    and (m.point_settled_at at time zone 'Asia/Seoul')::date
        = (now() at time zone 'Asia/Seoul')::date;
$function$;

CREATE OR REPLACE FUNCTION public.oot_create_invite(p_friend_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return public.oot_create_invite_with_mode(p_friend_id, 'casual');
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_create_invite_with_mode(p_friend_id uuid, p_battle_mode text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_mode text := lower(coalesce(p_battle_mode, 'casual'));
  v_invite_id uuid;
  v_is_active boolean := false;
  v_has_push boolean := false;
  v_delivery_mode text := 'in_app';
  v_push_status text := 'unavailable';
  v_push_due_at timestamptz := null;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('oot_random_matchmaking_v1'));

  if v_mode not in ('casual', 'rated') then
    raise exception 'OOT_INVALID_BATTLE_MODE';
  end if;

  if p_friend_id is null or p_friend_id = v_me then
    raise exception 'OOT_INVALID_FRIEND';
  end if;

  if not exists (
    select 1
    from public.list_my_garden_friends() f
    where f.friend_id = p_friend_id
      and coalesce(f.is_dev_test, false) = false
  ) then
    raise exception 'OOT_FRIEND_REQUIRED';
  end if;

  if exists (
    select 1
    from public.oot_matches m
    where m.status = 'active'
      and v_me in (m.player_one_id, m.player_two_id)
  ) then
    raise exception 'OOT_PLAYER_ALREADY_IN_MATCH';
  end if;

  if exists (
    select 1
    from public.oot_matches m
    where m.status = 'active'
      and p_friend_id in (m.player_one_id, m.player_two_id)
  ) then
    raise exception 'OOT_FRIEND_IN_MATCH';
  end if;

  -- 친구 대전을 선택한 순간 내 랜덤 대기를 종료합니다.
  delete from public.oot_random_match_queue
  where user_id = v_me
    and status = 'waiting';

  update public.oot_invites
  set
    status = 'expired',
    responded_at = coalesce(responded_at, now())
  where status = 'pending'
    and expires_at <= now()
    and v_me in (from_user_id, to_user_id);

  if exists (
    select 1
    from public.oot_invites i
    where i.status = 'pending'
      and i.expires_at > now()
      and (
        (i.from_user_id = v_me and i.to_user_id = p_friend_id)
        or
        (i.from_user_id = p_friend_id and i.to_user_id = v_me)
      )
  ) then
    raise exception 'OOT_INVITE_ALREADY_PENDING';
  end if;

  if v_mode = 'rated'
     and public.oot_count_pair_rated_matches_today(v_me, p_friend_id) >= 3 then
    raise exception 'OOT_DAILY_RATED_LIMIT_REACHED';
  end if;

  select exists (
    select 1
    from public.oot_presence_sessions ps
    where ps.user_id = p_friend_id
      and ps.last_seen_at > now() - interval '45 seconds'
  )
  into v_is_active;

  select exists (
    select 1
    from public.oot_push_subscriptions s
    where s.user_id = p_friend_id
      and s.enabled = true
  )
  into v_has_push;

  if v_has_push then
    v_push_status := 'pending';

    if v_is_active then
      v_delivery_mode := 'in_app_then_push';
      v_push_due_at := now() + interval '5 seconds';
    else
      v_delivery_mode := 'push';
      v_push_due_at := now();
    end if;
  else
    v_delivery_mode := 'in_app';
    v_push_status := 'unavailable';
    v_push_due_at := null;
  end if;

  insert into public.oot_invites (
    from_user_id,
    to_user_id,
    expires_at,
    delivery_mode,
    push_due_at,
    push_status,
    battle_mode
  )
  values (
    v_me,
    p_friend_id,
    now() + interval '10 minutes',
    v_delivery_mode,
    v_push_due_at,
    v_push_status,
    v_mode
  )
  returning id into v_invite_id;

  return v_invite_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_decline_invite(p_invite_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_invites
  set status = 'declined', responded_at = now()
  where id = p_invite_id
    and to_user_id = v_me
    and status = 'pending';

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_decline_rematch(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'finished' then
    raise exception 'OOT_REMATCH_NOT_FINISHED';
  end if;

  if v_match.next_match_id is null then
    if v_me = v_match.player_one_id then
      update public.oot_matches
      set
        player_one_rematch_status = 'declined',
        rematch_updated_at = now()
      where id = p_match_id;
    else
      update public.oot_matches
      set
        player_two_rematch_status = 'declined',
        rematch_updated_at = now()
      where id = p_match_id;
    end if;
  end if;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_disable_push_subscription(p_endpoint text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_push_subscriptions
  set
    enabled = false,
    updated_at = now()
  where user_id = v_me
    and endpoint = trim(p_endpoint);

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_draw_card(p_match_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_drawn smallint;
  v_next_version integer;
begin
  if v_me is null then raise exception 'LOGIN_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;
  if v_match.status <> 'active' or v_match.phase <> 'decision' then
    raise exception 'OOT_INVALID_PHASE';
  end if;
  if v_match.current_turn_id <> v_me then
    raise exception 'OOT_NOT_MY_TURN';
  end if;
  if v_match.version <> p_expected_version then
    raise exception 'OOT_VERSION_MISMATCH';
  end if;
  if v_match.turn_deadline <= now() then
    raise exception 'OOT_TURN_EXPIRED';
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  if cardinality(v_private.deck) = 0 then
    raise exception 'OOT_DECK_EMPTY';
  end if;

  v_drawn := v_private.deck[1];

  if v_match.player_one_id = v_me then
    update public.oot_match_private_states
    set
      deck = coalesce(deck[2:cardinality(deck)], '{}'::smallint[]),
      player_one_hand = array_append(player_one_hand, v_drawn),
      updated_at = now()
    where match_id = p_match_id;
  else
    update public.oot_match_private_states
    set
      deck = coalesce(deck[2:cardinality(deck)], '{}'::smallint[]),
      player_two_hand = array_append(player_two_hand, v_drawn),
      updated_at = now()
    where match_id = p_match_id;
  end if;

  v_next_version := v_match.version + 1;

  -- 카드 받기를 눌러도 30초가 초기화되지 않습니다.
  update public.oot_matches
  set
    phase = 'must_play',
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id, action_no, actor_id, action_type
  )
  values (
    p_match_id, v_next_version, v_me, 'draw'
  );

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_finish_match_locked(p_match_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_p1_target smallint;
  v_p2_target smallint;
  v_p1_distance integer;
  v_p2_distance integer;
  v_winner uuid;
  v_next_version integer;
begin
  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_match.status <> 'active' then
    return;
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  if v_match.current_value is null then
    raise exception 'OOT_RESULT_VALUE_MISSING';
  end if;

  v_p1_target := public.oot_closest_card(
    v_private.player_one_hand,
    v_match.current_value
  );
  v_p2_target := public.oot_closest_card(
    v_private.player_two_hand,
    v_match.current_value
  );

  if v_p1_target is null or v_p2_target is null then
    raise exception 'OOT_RESULT_CARD_MISSING';
  end if;

  v_p1_distance := abs(v_p1_target::integer - v_match.current_value);
  v_p2_distance := abs(v_p2_target::integer - v_match.current_value);

  if v_p1_distance < v_p2_distance then
    v_winner := v_match.player_one_id;
  elsif v_p2_distance < v_p1_distance then
    v_winner := v_match.player_two_id;
  else
    v_winner := null;
  end if;

  v_next_version := v_match.version + 1;

  update public.oot_matches
  set
    status = 'finished',
    phase = 'finished',
    current_turn_id = null,
    turn_deadline = null,
    winner_id = v_winner,
    player_one_target = v_p1_target,
    player_two_target = v_p2_target,
    player_one_distance = v_p1_distance,
    player_two_distance = v_p2_distance,
    finish_reason = p_reason,
    finished_at = now(),
    player_one_rematch_status = null,
    player_two_rematch_status = null,
    rematch_expires_at = now() + interval '10 minutes',
    rematch_updated_at = now(),
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id,
    action_no,
    actor_id,
    action_type,
    before_value,
    after_value
  )
  values (
    p_match_id,
    v_next_version,
    null,
    'finish',
    v_match.current_value,
    v_match.current_value
  );

  if v_match.battle_mode = 'rated' then
    perform public.oot_settle_friend_rated_match_locked(p_match_id);
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_friend_rated_status(p_friend_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_used integer;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_friend_id is null or p_friend_id = v_me then
    raise exception 'OOT_INVALID_FRIEND';
  end if;

  if not exists (
    select 1
    from public.list_my_garden_friends() f
    where f.friend_id = p_friend_id
      and coalesce(f.is_dev_test, false) = false
  ) then
    raise exception 'OOT_FRIEND_REQUIRED';
  end if;

  v_used := public.oot_count_pair_rated_matches_today(v_me, p_friend_id);

  return jsonb_build_object(
    'usedToday', v_used,
    'remainingToday', greatest(3 - v_used, 0),
    'canStartRated', v_used < 3,
    'dayTimeZone', 'Asia/Seoul'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_invite_badge()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_invites
  set
    status = 'expired',
    responded_at = coalesce(responded_at, now())
  where to_user_id = v_me
    and status = 'pending'
    and expires_at <= now();

  return jsonb_build_object(
    'incomingCount',
      (
        select count(*)
        from public.oot_invites i
        where i.to_user_id = v_me
          and i.status = 'pending'
          and i.expires_at > now()
      ),
    'unseenCount',
      (
        select count(*)
        from public.oot_invites i
        where i.to_user_id = v_me
          and i.status = 'pending'
          and i.expires_at > now()
          and i.receiver_seen_at is null
      ),
    'soonestExpiresAt',
      (
        select min(i.expires_at)
        from public.oot_invites i
        where i.to_user_id = v_me
          and i.status = 'pending'
          and i.expires_at > now()
      )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_match_view(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_is_p1 boolean;
  v_my_hand smallint[];
  v_opponent_hand smallint[];
  v_opponent_id uuid;
  v_opponent_nickname text;
  v_opponent_avatar text := '';
  v_actions jsonb := '[]'::jsonb;
  v_ledger public.oot_point_ledger%rowtype;
  v_point_result jsonb := null;
  v_is_waiting boolean := false;
  v_rated_played integer := 0;
  v_rated_remaining integer := 3;
  v_rematch_target_mode text := 'casual';
  v_my_rematch_status text;
  v_opponent_rematch_status text;
  v_rematch_expiry timestamptz;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id;

  if not found then
    raise exception 'OOT_PRIVATE_STATE_NOT_FOUND';
  end if;

  v_is_p1 := v_match.player_one_id = v_me;
  v_opponent_id := case
    when v_is_p1 then v_match.player_two_id
    else v_match.player_one_id
  end;
  v_my_hand := case
    when v_is_p1 then v_private.player_one_hand
    else v_private.player_two_hand
  end;
  v_opponent_hand := case
    when v_is_p1 then v_private.player_two_hand
    else v_private.player_one_hand
  end;

  v_opponent_nickname := case
    when coalesce(v_match.match_source, 'friend') = 'random'
      then '숲의 여행자'
    else '친구'
  end;

  if coalesce(v_match.match_source, 'friend') = 'friend' then
    select
      coalesce(f.nickname, '친구'),
      coalesce(f.avatar_url, '')
    into
      v_opponent_nickname,
      v_opponent_avatar
    from public.list_my_garden_friends() f
    where f.friend_id = v_opponent_id
      and coalesce(f.is_dev_test, false) = false
    limit 1;
  else
    select
      coalesce(to_jsonb(g)->>'nickname', '숲의 여행자'),
      coalesce(to_jsonb(g)->>'avatar_url', '')
    into
      v_opponent_nickname,
      v_opponent_avatar
    from public.garden_profiles g
    where g.id = v_opponent_id
    limit 1;
  end if;

  v_opponent_nickname := coalesce(
    v_opponent_nickname,
    case
      when coalesce(v_match.match_source, 'friend') = 'random'
        then '숲의 여행자'
      else '친구'
    end
  );
  v_opponent_avatar := coalesce(v_opponent_avatar, '');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'actionNo', a.action_no,
        'actorId', a.actor_id,
        'type', a.action_type,
        'beforeValue', a.before_value,
        'operation', a.operation,
        'numberCard', a.number_card,
        'afterValue', a.after_value,
        'isTimeout', a.is_timeout,
        'createdAt', a.created_at
      )
      order by a.action_no
    ),
    '[]'::jsonb
  )
  into v_actions
  from public.oot_match_actions a
  where a.match_id = p_match_id;

  select *
  into v_ledger
  from public.oot_point_ledger l
  where l.online_match_id = p_match_id
    and l.user_id = v_me
  limit 1;

  if found then
    v_point_result := jsonb_build_object(
      'resultType', v_ledger.result_type,
      'pointBefore', v_ledger.point_before,
      'baseDelta', v_ledger.base_delta,
      'streakBonus', v_ledger.streak_bonus,
      'protectionAmount', v_ledger.protection_amount,
      'finalDelta', v_ledger.final_delta,
      'pointAfter', v_ledger.point_after,
      'peakAfter', v_ledger.peak_after,
      'tierBefore', v_ledger.tier_before,
      'tierAfter', v_ledger.tier_after,
      'beginnerProtectionApplied', v_ledger.beginner_protection_applied,
      'tierFloorApplied', v_ledger.tier_floor_applied,
      'exactHit', v_ledger.exact_hit,
      'reason', v_ledger.reason,
      'rulesVersion', v_ledger.rules_version
    );
  end if;

  v_is_waiting :=
    v_match.status = 'active'
    and v_match.phase = 'opening'
    and v_match.current_value is null
    and v_match.current_turn_id is null
    and v_match.turn_deadline is null;

  if v_match.status = 'finished' then
    v_rated_played := public.oot_count_pair_rated_matches_today(
      v_match.player_one_id,
      v_match.player_two_id
    );
    v_rated_remaining := greatest(0, 3 - v_rated_played);
    v_rematch_target_mode := case
      when coalesce(v_match.battle_mode, 'casual') = 'rated'
       and v_rated_played < 3
        then 'rated'
      else 'casual'
    end;
  end if;

  v_my_rematch_status := case
    when v_is_p1 then v_match.player_one_rematch_status
    else v_match.player_two_rematch_status
  end;
  v_opponent_rematch_status := case
    when v_is_p1 then v_match.player_two_rematch_status
    else v_match.player_one_rematch_status
  end;
  v_rematch_expiry := coalesce(
    v_match.rematch_expires_at,
    v_match.finished_at + interval '10 minutes'
  );

  return jsonb_build_object(
    'matchId', v_match.id,
    'matchSource', coalesce(v_match.match_source, 'friend'),
    'seriesId', coalesce(v_match.series_id, v_match.id),
    'roundNumber', greatest(1, coalesce(v_match.round_number, 1)),
    'previousMatchId', v_match.previous_match_id,
    'nextMatchId', v_match.next_match_id,
    'battleMode', v_match.battle_mode,
    'pointRulesVersion', v_match.point_rules_version,
    'pointSettledAt', v_match.point_settled_at,
    'pointIneligibleReason', v_match.point_ineligible_reason,
    'pointResult', v_point_result,

    'status', v_match.status,
    'phase', v_match.phase,
    'version', v_match.version,
    'serverNow', now(),
    'turnDeadline', v_match.turn_deadline,
    'currentTurnId', v_match.current_turn_id,
    'starterId', v_match.starter_id,
    'isMyTurn', v_match.current_turn_id = v_me,
    'currentValue', v_match.current_value,
    'availableOperations', to_jsonb(v_match.available_operations),

    'isWaiting', v_is_waiting,
    'myReady', case
      when v_is_p1 then v_match.player_one_ready_at is not null
      else v_match.player_two_ready_at is not null
    end,
    'opponentReady', case
      when v_is_p1 then v_match.player_two_ready_at is not null
      else v_match.player_one_ready_at is not null
    end,
    'countdownStartedAt', v_match.countdown_started_at,
    'playStartsAt', v_match.play_starts_at,
    'playStartedAt', v_match.play_started_at,

    'myUserId', v_me,
    'myHand', to_jsonb(v_my_hand),
    'opponentId', v_opponent_id,
    'opponentNickname', v_opponent_nickname,
    'opponentAvatarUrl', v_opponent_avatar,
    'opponentCardCount', cardinality(v_opponent_hand),

    'winnerId', v_match.winner_id,
    'myTargetCard', case
      when v_match.status <> 'finished' then null
      when v_is_p1 then v_match.player_one_target
      else v_match.player_two_target
    end,
    'opponentTargetCard', case
      when v_match.status <> 'finished' then null
      when v_is_p1 then v_match.player_two_target
      else v_match.player_one_target
    end,
    'myDistance', case
      when v_match.status <> 'finished' then null
      when v_is_p1 then v_match.player_one_distance
      else v_match.player_two_distance
    end,
    'opponentDistance', case
      when v_match.status <> 'finished' then null
      when v_is_p1 then v_match.player_two_distance
      else v_match.player_one_distance
    end,
    'opponentHand', case
      when v_match.status = 'finished' then to_jsonb(v_opponent_hand)
      else null
    end,
    'finishReason', v_match.finish_reason,
    'actions', v_actions,

    'myRematchStatus', v_my_rematch_status,
    'opponentRematchStatus', v_opponent_rematch_status,
    'rematchExpiresAt', v_rematch_expiry,
    'rematchExpired',
      v_match.status = 'finished'
      and v_match.next_match_id is null
      and v_rematch_expiry is not null
      and v_rematch_expiry <= now(),
    'rematchTargetMode', v_rematch_target_mode,
    'ratedPlayedToday', v_rated_played,
    'ratedRemainingToday', v_rated_remaining
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_my_acorn_wallet()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_wallet public.oot_acorn_wallets%rowtype;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  insert into public.oot_acorn_wallets (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  select * into v_wallet
  from public.oot_acorn_wallets
  where user_id = v_user_id;

  return jsonb_build_object(
    'balance', v_wallet.balance,
    'lifetimeEarned', v_wallet.lifetime_earned
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_my_notification_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return jsonb_build_object(
    'enabledDeviceCount',
      (
        select count(*)
        from public.oot_push_subscriptions s
        where s.user_id = v_me
          and s.enabled = true
      ),
    'hasEnabledPush',
      exists (
        select 1
        from public.oot_push_subscriptions s
        where s.user_id = v_me
          and s.enabled = true
      )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_my_player_card()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_profile public.oot_player_profiles%rowtype;
  v_practice jsonb;
  v_people jsonb;
  v_friend jsonb;
  v_random jsonb;
  v_difficulty jsonb;
  v_radar jsonb;
  v_behavior jsonb;
  v_recent jsonb;
  v_acorns bigint := 0;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;

  insert into public.oot_player_profiles (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  select * into v_profile from public.oot_player_profiles where user_id = v_user_id;

  select coalesce(balance, 0) into v_acorns
  from public.oot_acorn_wallets
  where user_id = v_user_id;
  if v_acorns is null then v_acorns := 0; end if;

  select jsonb_build_object(
    'games', count(*),
    'wins', count(*) filter (where result = 'win'),
    'draws', count(*) filter (where result = 'draw'),
    'losses', count(*) filter (where result = 'lose'),
    'winRate', case when count(*) = 0 then 0 else round((count(*) filter (where result = 'win'))::numeric * 1000 / count(*)) / 10 end
  ) into v_practice
  from public.oot_player_game_records
  where user_id = v_user_id and mode = 'squirrel';

  select jsonb_build_object(
    'games', count(*),
    'wins', count(*) filter (where winner_id = v_user_id),
    'draws', count(*) filter (where winner_id is null),
    'losses', count(*) filter (where winner_id is not null and winner_id <> v_user_id),
    'winRate', case when count(*) = 0 then 0 else round((count(*) filter (where winner_id = v_user_id))::numeric * 1000 / count(*)) / 10 end
  ) into v_people
  from public.oot_matches
  where status = 'finished'
    and v_user_id in (player_one_id, player_two_id);

  select jsonb_build_object(
    'games', count(*),
    'wins', count(*) filter (where winner_id = v_user_id),
    'draws', count(*) filter (where winner_id is null),
    'losses', count(*) filter (where winner_id is not null and winner_id <> v_user_id)
  ) into v_friend
  from public.oot_matches
  where status = 'finished'
    and coalesce(match_source, 'friend') <> 'random'
    and v_user_id in (player_one_id, player_two_id);

  select jsonb_build_object(
    'games', count(*),
    'wins', count(*) filter (where winner_id = v_user_id),
    'draws', count(*) filter (where winner_id is null),
    'losses', count(*) filter (where winner_id is not null and winner_id <> v_user_id)
  ) into v_random
  from public.oot_matches
  where status = 'finished'
    and coalesce(match_source, 'friend') = 'random'
    and v_user_id in (player_one_id, player_two_id);

  select coalesce(jsonb_object_agg(difficulty, payload), '{}'::jsonb)
  into v_difficulty
  from (
    select difficulty,
      jsonb_build_object(
        'games', count(*),
        'wins', count(*) filter (where result = 'win'),
        'draws', count(*) filter (where result = 'draw'),
        'losses', count(*) filter (where result = 'lose')
      ) as payload
    from public.oot_player_game_records
    where user_id = v_user_id and mode = 'squirrel' and difficulty is not null
    group by difficulty
  ) d;

  select jsonb_build_object(
    'sampleCount', count(*),
    'calculation', case when count(*) = 0 then null else round(avg(calculation_score)) end,
    'distance', case when count(*) = 0 then null else round(avg(distance_score)) end,
    'stop', case when count(*) = 0 then null else round(avg(stop_score)) end,
    'resource', case when count(*) = 0 then null else round(avg(resource_score)) end,
    'time', case when count(*) = 0 then null else round(avg(time_score)) end,
    'consistency', case
      when count(*) < 3 then null
      else greatest(0, least(100, round(
        100
        - coalesce(stddev_pop(final_distance::numeric), 0) * 11
        - (sum(timeouts)::numeric / greatest(count(*), 1)) * 18
      )))
    end
  ) into v_radar
  from public.oot_player_game_records
  where user_id = v_user_id;

  select jsonb_build_object(
    'sampleCount', count(*),
    'avgOperations', case when count(*) = 0 then 0 else round(avg(operations_used)::numeric, 1) end,
    'avgDraws', case when count(*) = 0 then 0 else round(avg(draws_used)::numeric, 1) end,
    'avgFinalDistance', case when count(*) = 0 then 0 else round(avg(final_distance)::numeric, 1) end,
    'manualStopRate', case when count(*) = 0 then 0 else round((count(*) filter (where manual_stop))::numeric * 1000 / count(*)) / 10 end,
    'timeoutRate', case when count(*) = 0 then 0 else round((count(*) filter (where timeouts > 0))::numeric * 1000 / count(*)) / 10 end,
    'divisionRemainderUses', coalesce(sum(division_remainder_uses), 0)
  ) into v_behavior
  from public.oot_player_game_records
  where user_id = v_user_id;

  select coalesce(jsonb_agg(row_payload order by created_at desc), '[]'::jsonb)
  into v_recent
  from (
    select created_at,
      jsonb_build_object(
        'mode', mode,
        'battleMode', battle_mode,
        'difficulty', difficulty,
        'result', result,
        'finalDistance', final_distance,
        'operationsUsed', operations_used,
        'drawsUsed', draws_used,
        'createdAt', created_at
      ) as row_payload
    from public.oot_player_game_records
    where user_id = v_user_id
    order by created_at desc
    limit 10
  ) r;

  return jsonb_build_object(
    'profile', jsonb_build_object(
      'tagline', v_profile.tagline,
      'statsVisibility', v_profile.stats_visibility
    ),
    'acorns', v_acorns,
    'practice', v_practice,
    'people', v_people,
    'friend', v_friend,
    'random', v_random,
    'practiceByDifficulty', v_difficulty,
    'radar', v_radar,
    'behavior', v_behavior,
    'recentGames', v_recent
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_my_point_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_stats public.oot_player_stats%rowtype;
  v_next_tier_point integer;
  v_next_tier_key text;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  insert into public.oot_player_stats (user_id)
  values (v_user_id)
  on conflict (user_id) do nothing;

  select *
    into v_stats
  from public.oot_player_stats
  where user_id = v_user_id;

  select
    case v_stats.tier_key
      when 'number_seed' then 30
      when 'calculation_sprout' then 80
      when 'formula_branch' then 150
      when 'number_tree' then 250
      when 'one_of_ten_master' then 400
      else null
    end,
    case v_stats.tier_key
      when 'number_seed' then 'calculation_sprout'
      when 'calculation_sprout' then 'formula_branch'
      when 'formula_branch' then 'number_tree'
      when 'number_tree' then 'one_of_ten_master'
      when 'one_of_ten_master' then 'forest_keeper'
      else null
    end
  into v_next_tier_point, v_next_tier_key;

  return jsonb_build_object(
    'one_point', v_stats.one_point,
    'peak_one_point', v_stats.peak_one_point,
    'tier_key', v_stats.tier_key,
    'tier_floor', public.oot_point_floor_for_peak(v_stats.peak_one_point),
    'next_tier_key', v_next_tier_key,
    'next_tier_point', v_next_tier_point,
    'points_to_next_tier',
      case
        when v_next_tier_point is null then 0
        else greatest(v_next_tier_point - v_stats.one_point, 0)
      end,
    'point_matches', v_stats.point_matches,
    'wins', v_stats.wins,
    'draws', v_stats.draws,
    'losses', v_stats.losses,
    'current_win_streak', v_stats.current_win_streak,
    'max_win_streak', v_stats.max_win_streak,
    'beginner_protection_remaining', v_stats.beginner_protection_remaining,
    'exact_hits', v_stats.exact_hits,
    'rewards', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'reward_key', r.reward_key,
            'unlock_point', r.unlock_point,
            'unlocked_at', r.unlocked_at
          )
          order by r.unlock_point
        )
        from public.oot_reward_unlocks r
        where r.user_id = v_user_id
      ),
      '[]'::jsonb
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_random_candidate_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_candidate_count integer := 0;
  v_is_waiting boolean := false;
  v_joined_at timestamptz;
  v_active_match_id uuid;
  v_bucket text := 'none';
  v_label text := '현재 가능한 상대가 없어요';
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 접속 신호가 끊긴 오래된 대기자는 숫자에서 제거합니다.
  delete from public.oot_random_match_queue q
  where q.status = 'waiting'
    and q.heartbeat_at <= now() - interval '45 seconds';

  -- 내가 이미 경기 중이면 랜덤 매칭을 새로 시작할 수 없습니다.
  select m.id
  into v_active_match_id
  from public.oot_matches m
  where m.status = 'active'
    and v_me in (m.player_one_id, m.player_two_id)
  order by m.created_at desc
  limit 1;

  select
    true,
    q.joined_at
  into
    v_is_waiting,
    v_joined_at
  from public.oot_random_match_queue q
  where q.user_id = v_me
    and q.status = 'waiting'
    and q.heartbeat_at > now() - interval '45 seconds'
  limit 1;

  v_is_waiting := coalesce(v_is_waiting, false);

  -- 본인을 제외하고 아래 조건을 모두 만족하는 사용자만 후보로 셉니다.
  -- · 살아 있는 대기 상태
  -- · 현재 다른 경기 없음
  -- · 내 친구가 아님
  -- · 오늘 나와 원포인트 3판을 채우지 않음
  select count(*)::integer
  into v_candidate_count
  from public.oot_random_match_queue q
  where q.status = 'waiting'
    and q.user_id <> v_me
    and q.heartbeat_at > now() - interval '45 seconds'
    and not exists (
      select 1
      from public.oot_matches m
      where m.status = 'active'
        and q.user_id in (m.player_one_id, m.player_two_id)
    )
    and not exists (
      select 1
      from public.list_my_garden_friends() f
      where f.friend_id = q.user_id
        and coalesce(f.is_dev_test, false) = false
    )
    and public.oot_count_pair_rated_matches_today(v_me, q.user_id) < 3;

  if v_candidate_count = 1 then
    v_bucket := 'one';
    v_label := '현재 가능한 상대가 1명 있어요';
  elsif v_candidate_count between 2 and 4 then
    v_bucket := 'few';
    v_label := '현재 가능한 상대가 2~4명 있어요';
  elsif v_candidate_count >= 5 then
    v_bucket := 'many';
    v_label := '현재 가능한 상대가 5명 이상 있어요';
  end if;

  return jsonb_build_object(
    'status', case when v_active_match_id is null then 'available' else 'busy' end,
    'activeMatchId', v_active_match_id,
    'candidateCount', v_candidate_count,
    'candidateBucket', v_bucket,
    'candidateLabel', v_label,
    'canFastMatch', v_candidate_count >= 1,
    'canRandomMatch', v_candidate_count >= 2,
    'isWaiting', v_is_waiting,
    'joinedAt', v_joined_at,
    'serverNow', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_get_random_matchmaking_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_queue public.oot_random_match_queue%rowtype;
  v_match public.oot_matches%rowtype;
  v_queue_size integer := 0;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 이미 진행 중인 경기가 있으면 대기열보다 경기를 우선합니다.
  select * into v_match
  from public.oot_matches m
  where m.status = 'active'
    and v_me in (m.player_one_id, m.player_two_id)
  order by m.created_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'status', 'matched',
      'matchId', v_match.id,
      'matchSource', coalesce(v_match.match_source, 'friend'),
      'battleMode', coalesce(v_match.battle_mode, 'casual'),
      'existingMatch', true,
      'serverNow', now()
    );
  end if;

  select * into v_queue
  from public.oot_random_match_queue q
  where q.user_id = v_me;

  if not found then
    return jsonb_build_object(
      'status', 'idle',
      'serverNow', now()
    );
  end if;

  if v_queue.status = 'matched' and v_queue.match_id is not null then
    select * into v_match
    from public.oot_matches m
    where m.id = v_queue.match_id
      and v_me in (m.player_one_id, m.player_two_id);

    if found and v_match.status = 'active' then
      return jsonb_build_object(
        'status', 'matched',
        'matchId', v_match.id,
        'matchSource', coalesce(v_match.match_source, 'random'),
        'battleMode', coalesce(v_match.battle_mode, 'rated'),
        'existingMatch', false,
        'serverNow', now()
      );
    end if;

    delete from public.oot_random_match_queue
    where user_id = v_me;

    return jsonb_build_object(
      'status', 'idle',
      'serverNow', now()
    );
  end if;

  if v_queue.status = 'waiting'
     and v_queue.heartbeat_at > now() - interval '45 seconds' then
    select count(*)::integer
    into v_queue_size
    from public.oot_random_match_queue q
    where q.status = 'waiting'
      and q.heartbeat_at > now() - interval '45 seconds';

    return jsonb_build_object(
      'status', 'waiting',
      'joinedAt', v_queue.joined_at,
      'heartbeatAt', v_queue.heartbeat_at,
      'waitedSeconds', greatest(
        0,
        floor(extract(epoch from (now() - v_queue.joined_at)))::integer
      ),
      'queueSize', v_queue_size,
      'serverNow', now()
    );
  end if;

  delete from public.oot_random_match_queue
  where user_id = v_me;

  return jsonb_build_object(
    'status', 'idle',
    'serverNow', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_join_random_matchmaking()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_existing_match public.oot_matches%rowtype;
  v_own_queue public.oot_random_match_queue%rowtype;
  v_candidate_id uuid;
  v_match_id uuid;
  v_starter uuid;
  v_series_id uuid := gen_random_uuid();
  v_queue_size integer := 0;
  v_opponent_nickname text := '숲의 여행자';
  v_opponent_avatar text := '';
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 랜덤 매칭 생성과 친구 초대 수락이 동시에 발생하지 않도록 직렬화합니다.
  perform pg_advisory_xact_lock(hashtext('oot_random_matchmaking_v1'));

  -- 오래 끊긴 대기 행 정리. matched 행은 경기 상태 확인 뒤 각 사용자에게 정리됩니다.
  delete from public.oot_random_match_queue q
  where q.status = 'waiting'
    and q.heartbeat_at <= now() - interval '45 seconds';

  -- 어떤 종류든 이미 진행 중인 경기가 있다면 새 경기를 만들지 않습니다.
  select * into v_existing_match
  from public.oot_matches m
  where m.status = 'active'
    and v_me in (m.player_one_id, m.player_two_id)
  order by m.created_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'status', 'matched',
      'matchId', v_existing_match.id,
      'matchSource', coalesce(v_existing_match.match_source, 'friend'),
      'battleMode', coalesce(v_existing_match.battle_mode, 'casual'),
      'existingMatch', true,
      'serverNow', now()
    );
  end if;

  -- 이전 호출에서 이미 매칭됐으나 아직 화면 이동 전인 경우입니다.
  select * into v_own_queue
  from public.oot_random_match_queue q
  where q.user_id = v_me
  for update;

  if found and v_own_queue.status = 'matched' and v_own_queue.match_id is not null then
    select * into v_existing_match
    from public.oot_matches m
    where m.id = v_own_queue.match_id
      and m.status = 'active'
      and v_me in (m.player_one_id, m.player_two_id);

    if found then
      return jsonb_build_object(
        'status', 'matched',
        'matchId', v_existing_match.id,
        'matchSource', coalesce(v_existing_match.match_source, 'random'),
        'battleMode', coalesce(v_existing_match.battle_mode, 'rated'),
        'existingMatch', false,
        'serverNow', now()
      );
    end if;

    delete from public.oot_random_match_queue
    where user_id = v_me;
  end if;

  insert into public.oot_random_match_queue as q (
    user_id,
    status,
    joined_at,
    heartbeat_at,
    match_id,
    matched_at,
    updated_at
  )
  values (
    v_me,
    'waiting',
    now(),
    now(),
    null,
    null,
    now()
  )
  on conflict (user_id)
  do update set
    status = 'waiting',
    joined_at = case
      when q.status = 'waiting' then q.joined_at
      else excluded.joined_at
    end,
    heartbeat_at = now(),
    match_id = null,
    matched_at = null,
    updated_at = now();

  -- 친구가 아닌, 현재 살아 있는 가장 오래된 대기자를 찾습니다.
  -- 같은 상대와 오늘 이미 원포인트 3판을 완료했다면 새 랜덤 매칭에서 제외합니다.
  select q.user_id
  into v_candidate_id
  from public.oot_random_match_queue q
  where q.status = 'waiting'
    and q.user_id <> v_me
    and q.heartbeat_at > now() - interval '45 seconds'
    and not exists (
      select 1
      from public.oot_matches m
      where m.status = 'active'
        and q.user_id in (m.player_one_id, m.player_two_id)
    )
    and not exists (
      select 1
      from public.list_my_garden_friends() f
      where f.friend_id = q.user_id
        and coalesce(f.is_dev_test, false) = false
    )
    and public.oot_count_pair_rated_matches_today(v_me, q.user_id) < 3
  order by q.joined_at, q.user_id
  limit 1
  for update of q skip locked;

  if v_candidate_id is null then
    select count(*)::integer
    into v_queue_size
    from public.oot_random_match_queue q
    where q.status = 'waiting'
      and q.heartbeat_at > now() - interval '45 seconds';

    select * into v_own_queue
    from public.oot_random_match_queue q
    where q.user_id = v_me;

    return jsonb_build_object(
      'status', 'waiting',
      'joinedAt', v_own_queue.joined_at,
      'heartbeatAt', v_own_queue.heartbeat_at,
      'waitedSeconds', greatest(
        0,
        floor(extract(epoch from (now() - v_own_queue.joined_at)))::integer
      ),
      'queueSize', v_queue_size,
      'serverNow', now()
    );
  end if;

  -- 후보가 잠긴 뒤 다시 한 번 양쪽의 활성 경기 여부를 확인합니다.
  if exists (
    select 1
    from public.oot_matches m
    where m.status = 'active'
      and (
        v_me in (m.player_one_id, m.player_two_id)
        or v_candidate_id in (m.player_one_id, m.player_two_id)
      )
  ) then
    raise exception 'OOT_RANDOM_MATCH_CONFLICT';
  end if;

  if public.oot_count_pair_rated_matches_today(v_me, v_candidate_id) >= 3 then
    raise exception 'OOT_DAILY_RATED_LIMIT_REACHED';
  end if;

  v_starter := case
    when random() < 0.5 then v_candidate_id
    else v_me
  end;

  insert into public.oot_matches (
    player_one_id,
    player_two_id,
    starter_id,
    current_turn_id,
    status,
    phase,
    turn_deadline,
    battle_mode,
    point_rules_version,
    player_one_ready_at,
    player_two_ready_at,
    countdown_started_at,
    play_starts_at,
    play_started_at,
    series_id,
    round_number,
    match_source
  )
  values (
    v_candidate_id,
    v_me,
    v_starter,
    null,
    'active',
    'opening',
    null,
    'rated',
    'one_point_v1',
    null,
    null,
    null,
    null,
    null,
    v_series_id,
    1,
    'random'
  )
  returning id into v_match_id;

  insert into public.oot_match_private_states (
    match_id,
    deck,
    player_one_hand,
    player_two_hand
  )
  values (
    v_match_id,
    '{}'::smallint[],
    '{}'::smallint[],
    '{}'::smallint[]
  );

  update public.oot_random_match_queue
  set
    status = 'matched',
    match_id = v_match_id,
    matched_at = now(),
    heartbeat_at = now(),
    updated_at = now()
  where user_id in (v_me, v_candidate_id);

  -- 매칭된 사용자가 나중에 오래된 친구 초대를 눌러 두 번째 경기를 만드는 일을 막습니다.
  update public.oot_invites
  set
    status = 'cancelled',
    responded_at = coalesce(responded_at, now())
  where status = 'pending'
    and (
      from_user_id in (v_me, v_candidate_id)
      or to_user_id in (v_me, v_candidate_id)
    );

  select
    coalesce(to_jsonb(g)->>'nickname', '숲의 여행자'),
    coalesce(to_jsonb(g)->>'avatar_url', '')
  into
    v_opponent_nickname,
    v_opponent_avatar
  from public.garden_profiles g
  where g.id = v_candidate_id
  limit 1;

  return jsonb_build_object(
    'status', 'matched',
    'matchId', v_match_id,
    'matchSource', 'random',
    'battleMode', 'rated',
    'existingMatch', false,
    'opponentNickname', coalesce(v_opponent_nickname, '숲의 여행자'),
    'opponentAvatarUrl', coalesce(v_opponent_avatar, ''),
    'serverNow', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_leave_presence(p_device_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  delete from public.oot_presence_sessions
  where user_id = v_me
    and device_id = trim(p_device_id);

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_friend_availability()
 RETURNS TABLE(friend_id uuid, availability text, last_seen_at timestamp with time zone, game_ready_until timestamp with time zone, has_push boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  with my_friends as (
    select f.friend_id
    from public.list_my_garden_friends() f
    where coalesce(f.is_dev_test, false) = false
  ),
  presence_summary as (
    select
      ps.user_id,
      max(ps.last_seen_at) as latest_seen,
      max(ps.game_ready_until) as latest_ready
    from public.oot_presence_sessions ps
    group by ps.user_id
  )
  select
    mf.friend_id,
    (
      case
        when exists (
          select 1
          from public.oot_matches m
          where m.status = 'active'
            and mf.friend_id in (m.player_one_id, m.player_two_id)
        ) then 'in_game'

        when p.latest_seen > now() - interval '45 seconds'
         and p.latest_ready > now() then 'game_ready'

        when p.latest_seen > now() - interval '45 seconds' then 'online'

        when p.latest_seen > now() - interval '5 minutes' then 'away'

        else 'offline'
      end
    )::text,
    p.latest_seen,
    p.latest_ready,
    exists (
      select 1
      from public.oot_push_subscriptions s
      where s.user_id = mf.friend_id
        and s.enabled = true
    )
  from my_friends mf
  left join presence_summary p
    on p.user_id = mf.friend_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_match_chat(p_match_id uuid, p_limit integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_series_id uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 80), 100));
  v_messages jsonb := '[]'::jsonb;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  v_series_id := coalesce(v_match.series_id, v_match.id);

  if not public.oot_match_chat_series_is_open(v_series_id, v_me) then
    raise exception 'OOT_CHAT_ROOM_CLOSED';
  end if;

  with recent as (
    select
      c.id,
      c.match_id,
      c.sender_id,
      c.body,
      c.created_at,
      greatest(1, coalesce(m.round_number, 1)) as round_number
    from public.oot_match_chat_messages c
    join public.oot_matches m on m.id = c.match_id
    where c.series_id = v_series_id
    order by c.id desc
    limit v_limit
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', r.id,
        'matchId', r.match_id,
        'senderId', r.sender_id,
        'body', r.body,
        'createdAt', r.created_at,
        'roundNumber', r.round_number
      )
      order by r.id
    ),
    '[]'::jsonb
  )
  into v_messages
  from recent r;

  return jsonb_build_object(
    'seriesId', v_series_id,
    'messages', v_messages,
    'maxLength', 120
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_my_invites()
 RETURNS TABLE(invite_id uuid, direction text, other_user_id uuid, other_nickname text, other_avatar_url text, created_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 조회 시점에 이미 만료된 초대만 정리합니다.
  update public.oot_invites i
  set
    status = 'expired',
    responded_at = coalesce(i.responded_at, now())
  where i.status = 'pending'
    and i.expires_at <= now()
    and v_me in (i.from_user_id, i.to_user_id);

  -- 프로필이나 친구 RPC에 의존하지 않고 초대 행만 반환합니다.
  return query
  select
    i.id::uuid as invite_id,
    (
      case
        when i.to_user_id = v_me then 'incoming'
        else 'outgoing'
      end
    )::text as direction,
    (
      case
        when i.to_user_id = v_me then i.from_user_id
        else i.to_user_id
      end
    )::uuid as other_user_id,
    '친구'::text as other_nickname,
    ''::text as other_avatar_url,
    i.created_at::timestamptz as created_at,
    i.expires_at::timestamptz as expires_at
  from public.oot_invites i
  where i.status = 'pending'
    and i.expires_at > now()
    and v_me in (i.from_user_id, i.to_user_id)
  order by i.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_my_invites_v2()
 RETURNS TABLE(invite_id uuid, direction text, other_user_id uuid, other_nickname text, other_avatar_url text, battle_mode text, created_at timestamp with time zone, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.oot_invites i
  set
    status = 'expired',
    responded_at = coalesce(i.responded_at, now())
  where i.status = 'pending'
    and i.expires_at <= now()
    and v_me in (i.from_user_id, i.to_user_id);

  return query
  select
    i.id::uuid,
    (
      case
        when i.to_user_id = v_me then 'incoming'
        else 'outgoing'
      end
    )::text,
    (
      case
        when i.to_user_id = v_me then i.from_user_id
        else i.to_user_id
      end
    )::uuid,
    '친구'::text,
    ''::text,
    coalesce(i.battle_mode, 'casual')::text,
    i.created_at::timestamptz,
    i.expires_at::timestamptz
  from public.oot_invites i
  where i.status = 'pending'
    and i.expires_at > now()
    and v_me in (i.from_user_id, i.to_user_id)
  order by i.created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_my_matches(p_limit integer DEFAULT 20)
 RETURNS TABLE(match_id uuid, opponent_id uuid, opponent_nickname text, opponent_avatar_url text, status text, phase text, current_turn_id uuid, turn_deadline timestamp with time zone, winner_id uuid, created_at timestamp with time zone, finished_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  with my_friends as (
    select
      f.friend_id,
      f.nickname,
      f.avatar_url
    from public.list_my_garden_friends() f
    where coalesce(f.is_dev_test, false) = false
  )
  select
    m.id,
    case when m.player_one_id = v_me then m.player_two_id else m.player_one_id end,
    coalesce(f.nickname, '친구')::text,
    coalesce(f.avatar_url, '')::text,
    m.status,
    m.phase,
    m.current_turn_id,
    m.turn_deadline,
    m.winner_id,
    m.created_at,
    m.finished_at
  from public.oot_matches m
  left join my_friends f
    on f.friend_id =
      case when m.player_one_id = v_me then m.player_two_id else m.player_one_id end
  where v_me in (m.player_one_id, m.player_two_id)
  order by
    case when m.status = 'active' then 0 else 1 end,
    coalesce(m.finished_at, m.created_at) desc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_my_matches_v2(p_limit integer DEFAULT 20)
 RETURNS TABLE(match_id uuid, opponent_id uuid, opponent_nickname text, opponent_avatar_url text, battle_mode text, status text, phase text, current_turn_id uuid, turn_deadline timestamp with time zone, winner_id uuid, point_settled_at timestamp with time zone, point_ineligible_reason text, created_at timestamp with time zone, finished_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  with my_friends as (
    select
      f.friend_id,
      f.nickname,
      f.avatar_url
    from public.list_my_garden_friends() f
    where coalesce(f.is_dev_test, false) = false
  )
  select
    m.id,
    case
      when m.player_one_id = v_me then m.player_two_id
      else m.player_one_id
    end,
    coalesce(f.nickname, '친구')::text,
    coalesce(f.avatar_url, '')::text,
    coalesce(m.battle_mode, 'casual')::text,
    m.status,
    m.phase,
    m.current_turn_id,
    m.turn_deadline,
    m.winner_id,
    m.point_settled_at,
    m.point_ineligible_reason,
    m.created_at,
    m.finished_at
  from public.oot_matches m
  left join my_friends f
    on f.friend_id =
      case
        when m.player_one_id = v_me then m.player_two_id
        else m.player_one_id
      end
  where v_me in (m.player_one_id, m.player_two_id)
  order by
    case when m.status = 'active' then 0 else 1 end,
    coalesce(m.finished_at, m.created_at) desc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_list_my_matches_v3(p_limit integer DEFAULT 20)
 RETURNS TABLE(match_id uuid, opponent_id uuid, opponent_nickname text, opponent_avatar_url text, match_source text, battle_mode text, status text, phase text, current_turn_id uuid, turn_deadline timestamp with time zone, winner_id uuid, point_settled_at timestamp with time zone, point_ineligible_reason text, created_at timestamp with time zone, finished_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  return query
  with my_friends as (
    select
      f.friend_id,
      f.nickname,
      f.avatar_url
    from public.list_my_garden_friends() f
    where coalesce(f.is_dev_test, false) = false
  )
  select
    m.id,
    case
      when m.player_one_id = v_me then m.player_two_id
      else m.player_one_id
    end as opponent_id,
    coalesce(
      f.nickname,
      to_jsonb(g)->>'nickname',
      case when coalesce(m.match_source, 'friend') = 'random'
        then '숲의 여행자'
        else '친구'
      end
    )::text as opponent_nickname,
    coalesce(
      f.avatar_url,
      to_jsonb(g)->>'avatar_url',
      ''
    )::text as opponent_avatar_url,
    coalesce(m.match_source, 'friend')::text,
    coalesce(m.battle_mode, 'casual')::text,
    m.status,
    m.phase,
    m.current_turn_id,
    m.turn_deadline,
    m.winner_id,
    m.point_settled_at,
    m.point_ineligible_reason,
    m.created_at,
    m.finished_at
  from public.oot_matches m
  left join my_friends f
    on f.friend_id = case
      when m.player_one_id = v_me then m.player_two_id
      else m.player_one_id
    end
  left join public.garden_profiles g
    on g.id = case
      when m.player_one_id = v_me then m.player_two_id
      else m.player_one_id
    end
  where v_me in (m.player_one_id, m.player_two_id)
  order by
    case when m.status = 'active' then 0 else 1 end,
    coalesce(m.finished_at, m.created_at) desc
  limit greatest(1, least(coalesce(p_limit, 20), 100));
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_mark_push_result(p_invite_id uuid, p_success boolean, p_error text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.oot_invites
  set
    push_status = case
      when coalesce(p_success, false) then 'sent'
      when push_attempts < 3 then 'pending'
      else 'failed'
    end,
    push_sent_at = case
      when coalesce(p_success, false) then now()
      else push_sent_at
    end,
    push_due_at = case
      when coalesce(p_success, false) then null
      when push_attempts < 3 then now() + interval '30 seconds'
      else null
    end,
    push_last_error = case
      when coalesce(p_success, false) then null
      else left(coalesce(p_error, 'UNKNOWN_PUSH_ERROR'), 2000)
    end
  where id = p_invite_id
    and push_status = 'processing';

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_match_chat_series_is_open(p_series_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_latest public.oot_matches%rowtype;
  v_expiry timestamptz;
begin
  if p_series_id is null or p_user_id is null then
    return false;
  end if;

  select * into v_latest
  from public.oot_matches m
  where coalesce(m.series_id, m.id) = p_series_id
    and p_user_id in (m.player_one_id, m.player_two_id)
  order by greatest(1, coalesce(m.round_number, 1)) desc, m.created_at desc
  limit 1;

  if not found then
    return false;
  end if;

  if coalesce(v_latest.match_source, 'friend') <> 'friend' then
    return false;
  end if;

  if v_latest.status = 'active' then
    return true;
  end if;

  if v_latest.status <> 'finished' then
    return false;
  end if;

  if v_latest.next_match_id is not null
     or v_latest.player_one_rematch_status = 'declined'
     or v_latest.player_two_rematch_status = 'declined' then
    return false;
  end if;

  v_expiry := coalesce(
    v_latest.rematch_expires_at,
    v_latest.finished_at + interval '10 minutes'
  );

  return v_expiry is not null and v_expiry > now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_other_player(p_match oot_matches, p_user_id uuid)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_match.player_one_id = p_user_id then p_match.player_two_id
    when p_match.player_two_id = p_user_id then p_match.player_one_id
    else null
  end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_point_floor_for_peak(p_peak_point integer)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE STRICT
AS $function$
  select case
    when p_peak_point >= 400 then 400
    when p_peak_point >= 250 then 250
    when p_peak_point >= 150 then 150
    when p_peak_point >= 80  then 80
    when p_peak_point >= 30  then 30
    else 0
  end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_point_tier_for(p_point integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE STRICT
AS $function$
  select case
    when p_point >= 400 then 'forest_keeper'
    when p_point >= 250 then 'one_of_ten_master'
    when p_point >= 150 then 'number_tree'
    when p_point >= 80  then 'formula_branch'
    when p_point >= 30  then 'calculation_sprout'
    else 'number_seed'
  end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_record_player_match_performance(p_match_id uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_result text;
  v_mode text;
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_match_id is null then raise exception 'OOT_PROFILE_MATCH_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
    and v_user_id in (player_one_id, player_two_id);

  if not found then raise exception 'OOT_PROFILE_MATCH_NOT_FOUND'; end if;
  if v_match.status <> 'finished' and v_match.phase <> 'finished' then
    raise exception 'OOT_PROFILE_MATCH_NOT_FINISHED';
  end if;

  if v_match.winner_id is null then
    v_result := 'draw';
  elsif v_match.winner_id = v_user_id then
    v_result := 'win';
  else
    v_result := 'lose';
  end if;

  v_mode := case when coalesce(v_match.match_source, 'friend') = 'random' then 'random' else 'friend' end;

  return public._oot_insert_player_game_record(
    v_user_id, 'player', p_match_id::text, v_mode,
    coalesce(v_match.battle_mode, 'casual'), null, null,
    v_result, coalesce(p_payload, '{}'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_record_squirrel_performance(p_run_id text, p_result text, p_difficulty text, p_opponent_personality text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_run_id text := trim(coalesce(p_run_id, ''));
  v_result text := lower(trim(coalesce(p_result, '')));
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  if length(v_run_id) < 8 or length(v_run_id) > 160 then raise exception 'OOT_PROFILE_RUN_INVALID'; end if;
  if v_result not in ('win','draw','lose') then raise exception 'OOT_PROFILE_RESULT_INVALID'; end if;

  return public._oot_insert_player_game_record(
    v_user_id, 'squirrel', v_run_id, 'squirrel', null,
    lower(trim(coalesce(p_difficulty, ''))),
    lower(trim(coalesce(p_opponent_personality, ''))),
    v_result, coalesce(p_payload, '{}'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_request_rematch(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_new_match_id uuid;
  v_starter uuid;
  v_target_mode text;
  v_rated_used integer := 0;
  v_expiry timestamptz;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtext('oot_random_matchmaking_v1'));

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'finished' then
    raise exception 'OOT_REMATCH_NOT_FINISHED';
  end if;

  if v_match.next_match_id is not null then
    return public.oot_get_match_view(p_match_id);
  end if;

  v_expiry := coalesce(
    v_match.rematch_expires_at,
    v_match.finished_at + interval '10 minutes',
    now() + interval '10 minutes'
  );

  if v_expiry <= now() then
    raise exception 'OOT_REMATCH_EXPIRED';
  end if;

  if v_me = v_match.player_one_id then
    update public.oot_matches
    set
      player_one_rematch_status = 'accepted',
      rematch_expires_at = v_expiry,
      rematch_updated_at = now()
    where id = p_match_id;
  else
    update public.oot_matches
    set
      player_two_rematch_status = 'accepted',
      rematch_expires_at = v_expiry,
      rematch_updated_at = now()
    where id = p_match_id;
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if v_match.player_one_rematch_status = 'declined'
     or v_match.player_two_rematch_status = 'declined' then
    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.player_one_rematch_status = 'accepted'
     and v_match.player_two_rematch_status = 'accepted' then

    if exists (
      select 1
      from public.oot_matches m
      where m.status = 'active'
        and (
          v_match.player_one_id in (m.player_one_id, m.player_two_id)
          or v_match.player_two_id in (m.player_one_id, m.player_two_id)
        )
    ) then
      raise exception 'OOT_PLAYER_ALREADY_IN_MATCH';
    end if;

    v_rated_used := public.oot_count_pair_rated_matches_today(
      v_match.player_one_id,
      v_match.player_two_id
    );

    v_target_mode := case
      when coalesce(v_match.battle_mode, 'casual') = 'rated'
       and v_rated_used < 3
        then 'rated'
      else 'casual'
    end;

    v_starter := case
      when random() < 0.5 then v_match.player_one_id
      else v_match.player_two_id
    end;

    insert into public.oot_matches (
      player_one_id,
      player_two_id,
      starter_id,
      current_turn_id,
      status,
      phase,
      turn_deadline,
      battle_mode,
      point_rules_version,
      player_one_ready_at,
      player_two_ready_at,
      countdown_started_at,
      play_starts_at,
      play_started_at,
      series_id,
      round_number,
      previous_match_id,
      match_source
    )
    values (
      v_match.player_one_id,
      v_match.player_two_id,
      v_starter,
      null,
      'active',
      'opening',
      null,
      v_target_mode,
      case when v_target_mode = 'rated' then 'one_point_v1' else null end,
      null,
      null,
      null,
      null,
      null,
      coalesce(v_match.series_id, v_match.id),
      greatest(1, coalesce(v_match.round_number, 1)) + 1,
      v_match.id,
      coalesce(v_match.match_source, 'friend')
    )
    returning id into v_new_match_id;

    insert into public.oot_match_private_states (
      match_id,
      deck,
      player_one_hand,
      player_two_hand
    )
    values (
      v_new_match_id,
      '{}'::smallint[],
      '{}'::smallint[],
      '{}'::smallint[]
    );

    update public.oot_matches
    set
      next_match_id = v_new_match_id,
      rematch_updated_at = now()
    where id = p_match_id;

    delete from public.oot_random_match_queue
    where user_id in (v_match.player_one_id, v_match.player_two_id);

    update public.oot_invites
    set
      status = 'cancelled',
      responded_at = coalesce(responded_at, now())
    where status = 'pending'
      and (
        from_user_id in (v_match.player_one_id, v_match.player_two_id)
        or to_user_id in (v_match.player_one_id, v_match.player_two_id)
      );
  end if;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_resolve_timeout(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_actor uuid;
  v_actor_hand smallint[];
  v_number smallint;
  v_operation text;
  v_after integer;
  v_next_turn uuid;
  v_next_version integer;
begin
  if v_caller is null then raise exception 'LOGIN_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_caller not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'active' then
    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.turn_deadline is null or v_match.turn_deadline > now() then
    return public.oot_get_match_view(p_match_id);
  end if;

  v_actor := v_match.current_turn_id;

  if v_actor is null then
    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.phase = 'decision' then
    v_next_version := v_match.version + 1;

    update public.oot_matches
    set
      phase = 'resolving',
      current_turn_id = null,
      turn_deadline = null,
      version = v_next_version
    where id = p_match_id;

    insert into public.oot_match_actions (
      match_id, action_no, actor_id, action_type,
      before_value, after_value, is_timeout
    )
    values (
      p_match_id, v_next_version, v_actor, 'timeout_auto_stop',
      v_match.current_value, v_match.current_value, true
    );

    perform public.oot_finish_match_locked(p_match_id, 'timeout_auto_stop');
    return public.oot_get_match_view(p_match_id);
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  v_actor_hand := case
    when v_match.player_one_id = v_actor then v_private.player_one_hand
    else v_private.player_two_hand
  end;

  if cardinality(v_actor_hand) = 0 then
    raise exception 'OOT_TIMEOUT_HAND_EMPTY';
  end if;

  v_number := v_actor_hand[
    floor(random() * cardinality(v_actor_hand))::integer + 1
  ];

  if v_match.phase = 'opening' then
    if v_match.player_one_id = v_actor then
      update public.oot_match_private_states
      set player_one_hand = array_remove(player_one_hand, v_number),
          updated_at = now()
      where match_id = p_match_id;
    else
      update public.oot_match_private_states
      set player_two_hand = array_remove(player_two_hand, v_number),
          updated_at = now()
      where match_id = p_match_id;
    end if;

    v_next_turn := public.oot_other_player(v_match, v_actor);
    v_next_version := v_match.version + 1;

    update public.oot_matches
    set
      current_value = v_number,
      phase = 'must_play',
      current_turn_id = v_next_turn,
      turn_deadline = now() + interval '30 seconds',
      version = v_next_version
    where id = p_match_id;

    insert into public.oot_match_actions (
      match_id, action_no, actor_id, action_type,
      number_card, after_value, is_timeout
    )
    values (
      p_match_id, v_next_version, v_actor, 'timeout_auto_opening',
      v_number, v_number, true
    );

    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.phase <> 'must_play' then
    raise exception 'OOT_INVALID_TIMEOUT_PHASE';
  end if;

  if cardinality(v_match.available_operations) = 0 then
    perform public.oot_finish_match_locked(p_match_id, 'operations_exhausted');
    return public.oot_get_match_view(p_match_id);
  end if;

  v_operation := v_match.available_operations[
    floor(random() * cardinality(v_match.available_operations))::integer + 1
  ];

  v_after := public.oot_apply_operation(
    v_match.current_value,
    v_operation,
    v_number
  );

  if v_match.player_one_id = v_actor then
    update public.oot_match_private_states
    set player_one_hand = array_remove(player_one_hand, v_number),
        updated_at = now()
    where match_id = p_match_id;
  else
    update public.oot_match_private_states
    set player_two_hand = array_remove(player_two_hand, v_number),
        updated_at = now()
    where match_id = p_match_id;
  end if;

  v_next_version := v_match.version + 1;
  v_next_turn := public.oot_other_player(v_match, v_actor);

  update public.oot_matches
  set
    current_value = v_after,
    available_operations = array_remove(available_operations, v_operation),
    phase = case
      when cardinality(array_remove(available_operations, v_operation)) = 0
        then 'resolving'
      else 'decision'
    end,
    current_turn_id = case
      when cardinality(array_remove(available_operations, v_operation)) = 0
        then null
      else v_next_turn
    end,
    turn_deadline = case
      when cardinality(array_remove(available_operations, v_operation)) = 0
        then null
      else now() + interval '30 seconds'
    end,
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id, action_no, actor_id, action_type,
    before_value, operation, number_card, after_value, is_timeout
  )
  values (
    p_match_id, v_next_version, v_actor, 'timeout_auto_calculation',
    v_match.current_value, v_operation, v_number, v_after, true
  );

  if cardinality(array_remove(v_match.available_operations, v_operation)) = 0 then
    perform public.oot_finish_match_locked(p_match_id, 'operations_exhausted');
  end if;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_send_match_chat(p_match_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_latest public.oot_matches%rowtype;
  v_series_id uuid;
  v_body text := btrim(coalesce(p_body, ''));
  v_message public.oot_match_chat_messages%rowtype;
  v_recent_count integer := 0;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  v_series_id := coalesce(v_match.series_id, v_match.id);

  if not public.oot_match_chat_series_is_open(v_series_id, v_me) then
    raise exception 'OOT_CHAT_ROOM_CLOSED';
  end if;

  if char_length(v_body) < 1 then
    raise exception 'OOT_CHAT_EMPTY';
  end if;

  if char_length(v_body) > 120 then
    raise exception 'OOT_CHAT_TOO_LONG';
  end if;

  perform pg_advisory_xact_lock(hashtext(v_me::text));

  if exists (
    select 1
    from public.oot_match_chat_messages c
    where c.sender_id = v_me
      and c.created_at > now() - interval '800 milliseconds'
  ) then
    raise exception 'OOT_CHAT_TOO_FAST';
  end if;

  select count(*)::integer
  into v_recent_count
  from public.oot_match_chat_messages c
  where c.sender_id = v_me
    and c.created_at > now() - interval '10 seconds';

  if v_recent_count >= 6 then
    raise exception 'OOT_CHAT_RATE_LIMIT';
  end if;

  select * into v_latest
  from public.oot_matches m
  where coalesce(m.series_id, m.id) = v_series_id
    and v_me in (m.player_one_id, m.player_two_id)
  order by greatest(1, coalesce(m.round_number, 1)) desc, m.created_at desc
  limit 1;

  insert into public.oot_match_chat_messages (
    series_id,
    match_id,
    sender_id,
    body
  )
  values (
    v_series_id,
    v_latest.id,
    v_me,
    v_body
  )
  returning * into v_message;

  return jsonb_build_object(
    'id', v_message.id,
    'matchId', v_message.match_id,
    'senderId', v_message.sender_id,
    'body', v_message.body,
    'createdAt', v_message.created_at,
    'roundNumber', greatest(1, coalesce(v_latest.round_number, 1)),
    'seriesId', v_series_id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_set_game_ready(p_device_id text, p_ready boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_ready_until timestamptz;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_device_id is null
     or char_length(trim(p_device_id)) < 8
     or char_length(trim(p_device_id)) > 200 then
    raise exception 'OOT_INVALID_DEVICE_ID';
  end if;

  v_ready_until := case
    when coalesce(p_ready, false) then now() + interval '10 minutes'
    else null
  end;

  insert into public.oot_presence_sessions (
    user_id,
    device_id,
    activity_context,
    last_seen_at,
    game_ready_until,
    updated_at
  )
  values (
    v_me,
    trim(p_device_id),
    'one_of_ten_lobby',
    now(),
    v_ready_until,
    now()
  )
  on conflict (user_id, device_id)
  do update set
    activity_context = 'one_of_ten_lobby',
    last_seen_at = now(),
    game_ready_until = v_ready_until,
    updated_at = now();

  return jsonb_build_object(
    'ok', true,
    'gameReady', coalesce(p_ready, false),
    'gameReadyUntil', v_ready_until,
    'serverNow', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_set_match_ready(p_match_id uuid, p_ready boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_now timestamptz := clock_timestamp();
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  if v_match.status <> 'active'
     or v_match.phase <> 'opening'
     or v_match.current_turn_id is not null
     or v_match.turn_deadline is not null
     or v_match.current_value is not null
     or v_match.version <> 0
     or exists (
       select 1 from public.oot_match_actions a
       where a.match_id = p_match_id
     ) then
    raise exception 'OOT_MATCH_NOT_WAITING';
  end if;

  if v_match.play_starts_at is not null then
    if coalesce(p_ready, false)
       and (
         (v_me = v_match.player_one_id and v_match.player_one_ready_at is not null)
         or
         (v_me = v_match.player_two_id and v_match.player_two_ready_at is not null)
       ) then
      return public.oot_get_match_view(p_match_id);
    end if;
    raise exception 'OOT_READY_COUNTDOWN_STARTED';
  end if;

  if v_me = v_match.player_one_id then
    update public.oot_matches
    set player_one_ready_at = case when coalesce(p_ready, false) then v_now else null end
    where id = p_match_id;
  else
    update public.oot_matches
    set player_two_ready_at = case when coalesce(p_ready, false) then v_now else null end
    where id = p_match_id;
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id;

  if v_match.player_one_ready_at is not null
     and v_match.player_two_ready_at is not null then
    update public.oot_matches
    set
      countdown_started_at = v_now,
      play_starts_at = v_now + interval '3 seconds'
    where id = p_match_id
      and play_starts_at is null;
  else
    update public.oot_matches
    set
      countdown_started_at = null,
      play_starts_at = null
    where id = p_match_id;
  end if;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_settle_friend_rated_match_locked(p_match_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_match public.oot_matches%rowtype;
  v_used_today integer;
  v_p1_result text;
  v_p2_result text;
  v_source_mode text := 'friend_rated';
begin
  select *
  into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found then
    return;
  end if;

  if v_match.status <> 'finished'
     or v_match.battle_mode <> 'rated'
     or v_match.point_settled_at is not null then
    return;
  end if;

  v_source_mode := case
    when coalesce(v_match.match_source, 'friend') = 'random'
      then 'random_rated'
    else 'friend_rated'
  end;

  insert into public.oot_player_stats (user_id)
  values
    (v_match.player_one_id),
    (v_match.player_two_id)
  on conflict (user_id) do nothing;

  perform 1
  from public.oot_player_stats s
  where s.user_id in (v_match.player_one_id, v_match.player_two_id)
  order by s.user_id
  for update;

  v_used_today := public.oot_count_pair_rated_matches_today(
    v_match.player_one_id,
    v_match.player_two_id
  );

  if v_used_today >= 3 then
    insert into public.oot_point_ledger (
      settlement_key,
      online_match_id,
      user_id,
      opponent_user_id,
      source_mode,
      result_type,
      point_before,
      base_delta,
      streak_bonus,
      protection_amount,
      final_delta,
      point_after,
      peak_after,
      tier_before,
      tier_after,
      beginner_protection_applied,
      tier_floor_applied,
      exact_hit,
      reason,
      rules_version
    )
    select
      p_match_id,
      p_match_id,
      s.user_id,
      case
        when s.user_id = v_match.player_one_id then v_match.player_two_id
        else v_match.player_one_id
      end,
      v_source_mode,
      'ineligible',
      s.one_point,
      0,
      0,
      0,
      0,
      s.one_point,
      s.peak_one_point,
      s.tier_key,
      s.tier_key,
      false,
      false,
      false,
      'daily_pair_limit',
      'one_point_v1'
    from public.oot_player_stats s
    where s.user_id in (v_match.player_one_id, v_match.player_two_id);

    update public.oot_matches
    set
      point_rules_version = 'one_point_v1',
      point_settled_at = now(),
      point_ineligible_reason = 'daily_pair_limit'
    where id = p_match_id;

    return;
  end if;

  if v_match.winner_id is null then
    v_p1_result := 'draw';
    v_p2_result := 'draw';
  elsif v_match.winner_id = v_match.player_one_id then
    v_p1_result := 'win';
    v_p2_result := 'loss';
  else
    v_p1_result := 'loss';
    v_p2_result := 'win';
  end if;

  perform public.oot_apply_friend_point_result_locked(
    p_match_id,
    v_match.player_one_id,
    v_match.player_two_id,
    v_p1_result,
    coalesce(v_match.player_one_distance = 0, false)
  );

  perform public.oot_apply_friend_point_result_locked(
    p_match_id,
    v_match.player_two_id,
    v_match.player_one_id,
    v_p2_result,
    coalesce(v_match.player_two_distance = 0, false)
  );

  if v_source_mode = 'random_rated' then
    update public.oot_point_ledger
    set
      source_mode = 'random_rated',
      reason = case
        when result_type in ('win', 'draw', 'loss')
          then 'random_rated_' || result_type
        else reason
      end
    where online_match_id = p_match_id;
  end if;

  update public.oot_matches
  set
    point_rules_version = 'one_point_v1',
    point_settled_at = now(),
    point_ineligible_reason = null
  where id = p_match_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_start_match_if_due(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_numbers smallint[];
  v_now timestamptz;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;

  -- 행 잠금을 기다린 시간까지 반영한 실제 서버 시각을 사용합니다.
  v_now := clock_timestamp();

  if v_match.status <> 'active' then
    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.current_turn_id is not null or v_match.turn_deadline is not null then
    return public.oot_get_match_view(p_match_id);
  end if;

  if v_match.phase <> 'opening'
     or v_match.current_value is not null
     or v_match.version <> 0
     or v_match.player_one_ready_at is null
     or v_match.player_two_ready_at is null
     or v_match.play_starts_at is null
     or v_match.play_starts_at > v_now then
    return public.oot_get_match_view(p_match_id);
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  if not found then
    raise exception 'OOT_PRIVATE_STATE_NOT_FOUND';
  end if;

  if cardinality(coalesce(v_private.deck, '{}'::smallint[])) = 0
     and cardinality(coalesce(v_private.player_one_hand, '{}'::smallint[])) = 0
     and cardinality(coalesce(v_private.player_two_hand, '{}'::smallint[])) = 0 then
    select array_agg(n::smallint order by random())
    into v_numbers
    from generate_series(1, 10) as n;

    update public.oot_match_private_states
    set
      deck = coalesce(v_numbers[5:10], '{}'::smallint[]),
      player_one_hand = v_numbers[1:2],
      player_two_hand = v_numbers[3:4],
      updated_at = v_now
    where match_id = p_match_id;
  end if;

  update public.oot_matches
  set
    current_turn_id = starter_id,
    turn_deadline = v_now + interval '30 seconds',
    play_started_at = v_now,
    started_at = v_now
  where id = p_match_id
    and current_turn_id is null
    and turn_deadline is null;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_stop_match(p_match_id uuid, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_next_version integer;
begin
  if v_me is null then raise exception 'LOGIN_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;
  if v_match.status <> 'active' or v_match.phase <> 'decision' then
    raise exception 'OOT_INVALID_PHASE';
  end if;
  if v_match.current_turn_id <> v_me then
    raise exception 'OOT_NOT_MY_TURN';
  end if;
  if v_match.version <> p_expected_version then
    raise exception 'OOT_VERSION_MISMATCH';
  end if;
  if v_match.turn_deadline <= now() then
    raise exception 'OOT_TURN_EXPIRED';
  end if;

  v_next_version := v_match.version + 1;

  update public.oot_matches
  set
    phase = 'resolving',
    current_turn_id = null,
    turn_deadline = null,
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id, action_no, actor_id, action_type,
    before_value, after_value
  )
  values (
    p_match_id, v_next_version, v_me, 'stop',
    v_match.current_value, v_match.current_value
  );

  perform public.oot_finish_match_locked(p_match_id, 'player_stop');

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_submit_calculation(p_match_id uuid, p_expected_version integer, p_operation text, p_number smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_hand smallint[];
  v_after integer;
  v_next_turn uuid;
  v_next_version integer;
begin
  if v_me is null then raise exception 'LOGIN_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;
  if v_match.status <> 'active' or v_match.phase <> 'must_play' then
    raise exception 'OOT_INVALID_PHASE';
  end if;
  if v_match.current_turn_id <> v_me then
    raise exception 'OOT_NOT_MY_TURN';
  end if;
  if v_match.version <> p_expected_version then
    raise exception 'OOT_VERSION_MISMATCH';
  end if;
  if v_match.turn_deadline <= now() then
    raise exception 'OOT_TURN_EXPIRED';
  end if;
  if not (p_operation = any(v_match.available_operations)) then
    raise exception 'OOT_OPERATION_NOT_AVAILABLE';
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  v_hand := case
    when v_match.player_one_id = v_me then v_private.player_one_hand
    else v_private.player_two_hand
  end;

  if not (p_number = any(v_hand)) then
    raise exception 'OOT_CARD_NOT_IN_HAND';
  end if;

  v_after := public.oot_apply_operation(
    v_match.current_value,
    p_operation,
    p_number
  );

  if v_match.player_one_id = v_me then
    update public.oot_match_private_states
    set player_one_hand = array_remove(player_one_hand, p_number),
        updated_at = now()
    where match_id = p_match_id;
  else
    update public.oot_match_private_states
    set player_two_hand = array_remove(player_two_hand, p_number),
        updated_at = now()
    where match_id = p_match_id;
  end if;

  v_next_version := v_match.version + 1;
  v_next_turn := public.oot_other_player(v_match, v_me);

  update public.oot_matches
  set
    current_value = v_after,
    available_operations = array_remove(available_operations, p_operation),
    phase = case
      when cardinality(array_remove(available_operations, p_operation)) = 0
        then 'resolving'
      else 'decision'
    end,
    current_turn_id = case
      when cardinality(array_remove(available_operations, p_operation)) = 0
        then null
      else v_next_turn
    end,
    turn_deadline = case
      when cardinality(array_remove(available_operations, p_operation)) = 0
        then null
      else now() + interval '30 seconds'
    end,
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id, action_no, actor_id, action_type,
    before_value, operation, number_card, after_value
  )
  values (
    p_match_id, v_next_version, v_me, 'calculation',
    v_match.current_value, p_operation, p_number, v_after
  );

  if cardinality(array_remove(v_match.available_operations, p_operation)) = 0 then
    perform public.oot_finish_match_locked(p_match_id, 'operations_exhausted');
  end if;

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_submit_opening(p_match_id uuid, p_expected_version integer, p_number smallint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_match public.oot_matches%rowtype;
  v_private public.oot_match_private_states%rowtype;
  v_hand smallint[];
  v_next_turn uuid;
  v_next_version integer;
begin
  if v_me is null then raise exception 'LOGIN_REQUIRED'; end if;

  select * into v_match
  from public.oot_matches
  where id = p_match_id
  for update;

  if not found or v_me not in (v_match.player_one_id, v_match.player_two_id) then
    raise exception 'OOT_MATCH_NOT_FOUND';
  end if;
  if v_match.status <> 'active' or v_match.phase <> 'opening' then
    raise exception 'OOT_INVALID_PHASE';
  end if;
  if v_match.current_turn_id <> v_me then
    raise exception 'OOT_NOT_MY_TURN';
  end if;
  if v_match.version <> p_expected_version then
    raise exception 'OOT_VERSION_MISMATCH';
  end if;
  if v_match.turn_deadline <= now() then
    raise exception 'OOT_TURN_EXPIRED';
  end if;

  select * into v_private
  from public.oot_match_private_states
  where match_id = p_match_id
  for update;

  v_hand := case
    when v_match.player_one_id = v_me then v_private.player_one_hand
    else v_private.player_two_hand
  end;

  if not (p_number = any(v_hand)) then
    raise exception 'OOT_CARD_NOT_IN_HAND';
  end if;

  if v_match.player_one_id = v_me then
    update public.oot_match_private_states
    set player_one_hand = array_remove(player_one_hand, p_number),
        updated_at = now()
    where match_id = p_match_id;
  else
    update public.oot_match_private_states
    set player_two_hand = array_remove(player_two_hand, p_number),
        updated_at = now()
    where match_id = p_match_id;
  end if;

  v_next_turn := public.oot_other_player(v_match, v_me);
  v_next_version := v_match.version + 1;

  update public.oot_matches
  set
    current_value = p_number,
    phase = 'must_play',
    current_turn_id = v_next_turn,
    turn_deadline = now() + interval '30 seconds',
    version = v_next_version
  where id = p_match_id;

  insert into public.oot_match_actions (
    match_id, action_no, actor_id, action_type,
    number_card, after_value
  )
  values (
    p_match_id, v_next_version, v_me, 'opening',
    p_number, p_number
  );

  return public.oot_get_match_view(p_match_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_touch_player_stats_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_touch_presence(p_device_id text, p_activity_context text DEFAULT 'app'::text, p_match_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_context text;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_device_id is null
     or char_length(trim(p_device_id)) < 8
     or char_length(trim(p_device_id)) > 200 then
    raise exception 'OOT_INVALID_DEVICE_ID';
  end if;

  v_context := case
    when p_activity_context in ('app', 'one_of_ten_lobby', 'one_of_ten_match')
      then p_activity_context
    else 'app'
  end;

  insert into public.oot_presence_sessions (
    user_id,
    device_id,
    activity_context,
    last_seen_at,
    current_match_id,
    updated_at
  )
  values (
    v_me,
    trim(p_device_id),
    v_context,
    now(),
    p_match_id,
    now()
  )
  on conflict (user_id, device_id)
  do update set
    activity_context = excluded.activity_context,
    last_seen_at = now(),
    current_match_id = excluded.current_match_id,
    updated_at = now();

  -- 오래된 자기 기기 세션만 가볍게 정리합니다.
  delete from public.oot_presence_sessions
  where user_id = v_me
    and last_seen_at < now() - interval '7 days';

  return jsonb_build_object(
    'ok', true,
    'serverNow', now(),
    'onlineUntil', now() + interval '45 seconds'
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_update_my_player_profile(p_tagline text, p_stats_visibility text DEFAULT 'friends'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_tagline text := trim(coalesce(p_tagline, ''));
  v_visibility text := lower(trim(coalesce(p_stats_visibility, 'friends')));
begin
  if v_user_id is null then raise exception 'AUTH_REQUIRED'; end if;
  if char_length(v_tagline) > 40 then raise exception 'OOT_PROFILE_TAGLINE_TOO_LONG'; end if;
  if v_visibility not in ('friends', 'private') then raise exception 'OOT_PROFILE_VISIBILITY_INVALID'; end if;

  insert into public.oot_player_profiles (user_id, tagline, stats_visibility)
  values (v_user_id, v_tagline, v_visibility)
  on conflict (user_id) do update
  set tagline = excluded.tagline,
      stats_visibility = excluded.stats_visibility,
      updated_at = now();

  return jsonb_build_object('tagline', v_tagline, 'statsVisibility', v_visibility);
end;
$function$;

CREATE OR REPLACE FUNCTION public.oot_upsert_push_subscription(p_device_id text, p_endpoint text, p_p256dh text, p_auth_secret text, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_id uuid;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_device_id is null
     or char_length(trim(p_device_id)) < 8
     or char_length(trim(p_device_id)) > 200 then
    raise exception 'OOT_INVALID_DEVICE_ID';
  end if;

  if p_endpoint is null
     or char_length(trim(p_endpoint)) < 20
     or char_length(trim(p_endpoint)) > 4096
     or left(lower(trim(p_endpoint)), 8) <> 'https://' then
    raise exception 'OOT_INVALID_PUSH_ENDPOINT';
  end if;

  if p_p256dh is null
     or char_length(trim(p_p256dh)) < 20
     or p_auth_secret is null
     or char_length(trim(p_auth_secret)) < 8 then
    raise exception 'OOT_INVALID_PUSH_KEYS';
  end if;

  insert into public.oot_push_subscriptions (
    user_id,
    device_id,
    endpoint,
    p256dh,
    auth_secret,
    user_agent,
    enabled,
    updated_at
  )
  values (
    v_me,
    trim(p_device_id),
    trim(p_endpoint),
    trim(p_p256dh),
    trim(p_auth_secret),
    left(p_user_agent, 1000),
    true,
    now()
  )
  on conflict (endpoint)
  do update set
    user_id = v_me,
    device_id = excluded.device_id,
    p256dh = excluded.p256dh,
    auth_secret = excluded.auth_secret,
    user_agent = excluded.user_agent,
    enabled = true,
    updated_at = now()
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.pick_my_garden_animal_v3(p_user_id uuid, p_growth integer, p_last_kind text DEFAULT NULL::text, p_repeat_factor numeric DEFAULT 0.15)
 RETURNS TABLE(animal_kind text, habitat_zone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Seoul')::date;
  v_hour integer := extract(hour FROM (now() AT TIME ZONE 'Asia/Seoul'))::integer;
  v_state public.garden_animal_discovery_state_v1%rowtype;
  v_force_unseen boolean := false;
  v_active_unseen_rare boolean := false;
  v_repeat_factor numeric := greatest(0.05, least(coalesce(p_repeat_factor, 0.15), 1));
BEGIN
  IF p_user_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.garden_animal_discovery_state_v1 (user_id, discovery_day)
  VALUES (p_user_id, v_today)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.garden_animal_discovery_state_v1
  SET discovery_day = v_today,
      discoveries_today = 0,
      updated_at = now()
  WHERE user_id = p_user_id
    AND discovery_day <> v_today;

  SELECT * INTO v_state
  FROM public.garden_animal_discovery_state_v1
  WHERE user_id = p_user_id
  FOR UPDATE;

  SELECT EXISTS (
    SELECT 1
    FROM public.garden_dev_animal_v2_visits active_visit
    WHERE active_visit.user_id = p_user_id
      AND active_visit.visit_state IN ('approaching', 'visiting', 'departing')
      AND active_visit.animal_kind IN ('owl', 'fox', 'raccoon', 'mole')
      AND NOT EXISTS (
        SELECT 1
        FROM public.garden_animal_codex_visits seen
        WHERE seen.user_id = p_user_id
          AND seen.animal_kind = active_visit.animal_kind
      )
  ) INTO v_active_unseen_rare;

  v_force_unseen := coalesce(v_state.discoveries_today, 0) = 0
    AND coalesce(v_state.visits_since_new, 0) >= 8
    AND NOT v_active_unseen_rare;

  RETURN QUERY
  WITH candidate(kind, zone, base_weight, discovered_weight, is_rare) AS (
    VALUES
      ('bird'::text, 'branch'::text,
        CASE WHEN coalesce(p_growth, 0) >= 7 THEN 40::numeric ELSE 30::numeric END,
        0::numeric, false),
      ('rabbit'::text, 'ground'::text,
        CASE WHEN coalesce(p_growth, 0) >= 7 THEN 30::numeric ELSE 25::numeric END,
        0::numeric, false),
      ('squirrel'::text, 'branch'::text,
        CASE WHEN coalesce(p_growth, 0) >= 7 THEN 18::numeric ELSE 25::numeric END,
        0::numeric, false),
      ('hedgehog'::text, 'ground'::text,
        CASE WHEN coalesce(p_growth, 0) >= 7 THEN 12::numeric ELSE 20::numeric END,
        0::numeric, false),
      ('owl'::text, 'branch'::text, 0::numeric, 16::numeric, true),
      ('fox'::text, 'ground'::text, 0::numeric, 14::numeric, true),
      ('raccoon'::text, 'branch'::text, 0::numeric, 12::numeric, true),
      ('mole'::text, 'ground'::text, 0::numeric, 10::numeric, true)
  ),
  facts AS (
    SELECT
      candidate.*,
      EXISTS (
        SELECT 1
        FROM public.garden_animal_codex_visits seen
        WHERE seen.user_id = p_user_id
          AND seen.animal_kind = candidate.kind
      ) AS discovered
    FROM candidate
  ),
  scored AS (
    SELECT
      facts.*,
      (facts.is_rare AND NOT facts.discovered) AS is_unseen_rare,
      (
        CASE
          WHEN NOT facts.is_rare THEN facts.base_weight
          WHEN facts.discovered THEN facts.discovered_weight
          WHEN coalesce(v_state.visits_since_new, 0) >= 6 THEN 12::numeric
          WHEN coalesce(v_state.visits_since_new, 0) >= 3 THEN 7::numeric
          ELSE 3.5::numeric
        END
        * CASE facts.kind
            WHEN 'owl' THEN CASE WHEN v_hour >= 18 OR v_hour < 5 THEN 1.80 ELSE 0.78 END
            WHEN 'fox' THEN CASE WHEN (v_hour >= 5 AND v_hour < 9) OR (v_hour >= 17 AND v_hour < 21) THEN 1.55 ELSE 0.90 END
            WHEN 'raccoon' THEN CASE WHEN v_hour >= 20 OR v_hour < 2 THEN 1.70 ELSE 0.85 END
            WHEN 'mole' THEN CASE WHEN v_hour >= 6 AND v_hour < 11 THEN 1.50 ELSE 0.95 END
            ELSE 1::numeric
          END
        * CASE WHEN facts.kind = coalesce(p_last_kind, '') THEN v_repeat_factor ELSE 1::numeric END
      ) AS weight
    FROM facts
  )
  SELECT scored.kind, scored.zone
  FROM scored
  WHERE scored.weight > 0
    AND NOT EXISTS (
      SELECT 1
      FROM public.garden_dev_animal_v2_visits active_visit
      WHERE active_visit.user_id = p_user_id
        AND active_visit.visit_state IN ('approaching', 'visiting', 'departing')
        AND (
          active_visit.animal_kind = scored.kind
          OR active_visit.habitat_zone = scored.zone
        )
    )
    AND NOT (
      scored.is_unseen_rare
      AND coalesce(v_state.discoveries_today, 0) >= 1
    )
    AND NOT (
      scored.is_unseen_rare
      AND v_active_unseen_rare
    )
  ORDER BY
    CASE
      WHEN v_force_unseen AND scored.is_unseen_rare THEN 0
      WHEN v_force_unseen THEN 1
      ELSE 0
    END,
    -ln(greatest(random(), 0.000001)) / greatest(scored.weight, 0.000001)
  LIMIT 1;
END;
$function$;

CREATE OR REPLACE FUNCTION public.preview_garden_friend_code(p_code text)
 RETURNS TABLE(owner_id uuid, owner_nickname text, relationship_status text, pending_request_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  v_owner uuid;
  v_name text;
  v_request public.garden_friend_requests%rowtype;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select c.user_id, c.nickname_snapshot
    into v_owner, v_name
  from public.garden_friend_codes c
  where c.friend_code = v_code;

  if v_owner is null then
    return;
  end if;

  update public.garden_friend_requests r
  set status = 'expired', responded_at = now()
  where r.status = 'pending'
    and r.expires_at <= now()
    and v_me in (r.from_user_id, r.to_user_id);

  if v_owner = v_me then
    return query select v_owner, v_name, 'self'::text, null::uuid;
    return;
  end if;

  if exists (
    select 1 from public.list_my_garden_friends() f
    where f.friend_id = v_owner
  ) then
    return query select v_owner, v_name, 'already_friend'::text, null::uuid;
    return;
  end if;

  select * into v_request
  from public.garden_friend_requests r
  where r.status = 'pending'
    and ((r.from_user_id = v_me and r.to_user_id = v_owner)
      or (r.from_user_id = v_owner and r.to_user_id = v_me))
  order by r.created_at desc
  limit 1;

  if found then
    return query select
      v_owner,
      v_name,
      case when v_request.from_user_id = v_me then 'outgoing_pending' else 'incoming_pending' end,
      v_request.id;
    return;
  end if;

  return query select v_owner, v_name, 'ready'::text, null::uuid;
end;
$function$;

CREATE OR REPLACE FUNCTION public.preview_garden_friend_invite(p_token uuid)
 RETURNS TABLE(inviter_id uuid, inviter_nickname text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  return query
  select invite.creator_id,
         coalesce(profile.nickname, '친구'),
         invite.expires_at
  from public.garden_friend_invites as invite
  left join public.garden_profiles as profile
    on profile.id = invite.creator_id
  where invite.token = p_token
    and invite.accepted_at is null
    and invite.expires_at > now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.receive_garden_letter(p_letter_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.garden_letters
     set read_at = coalesce(read_at, now())
   where id = p_letter_id
     and recipient_id = auth.uid()
     and returned_at is null
     and available_at <= now();

  return found;
end;
$function$;

