CREATE OR REPLACE FUNCTION public.record_garden_animal_codex_visit_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'Asia/Seoul')::date;
  v_was_discovered boolean := false;
  v_inserted_count integer := 0;
  v_state public.garden_animal_discovery_state_v1%rowtype;
BEGIN
  IF new.user_id IS NULL
     OR new.id IS NULL
     OR new.animal_kind NOT IN ('bird', 'owl', 'rabbit', 'fox', 'squirrel', 'raccoon', 'hedgehog', 'mole')
     OR new.arrived_at IS NULL
     OR new.visit_state NOT IN ('visiting', 'departing', 'trace') THEN
    RETURN new;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.garden_animal_codex_visits existing
    WHERE existing.user_id = new.user_id
      AND existing.animal_kind = new.animal_kind
  ) INTO v_was_discovered;

  INSERT INTO public.garden_animal_codex_visits (
    visit_id,
    user_id,
    animal_kind,
    arrived_at
  )
  VALUES (
    new.id,
    new.user_id,
    new.animal_kind,
    new.arrived_at
  )
  ON CONFLICT (visit_id) DO NOTHING;

  GET DIAGNOSTICS v_inserted_count = ROW_COUNT;
  IF v_inserted_count = 0 THEN
    RETURN new;
  END IF;

  INSERT INTO public.garden_animal_discovery_state_v1 (user_id, discovery_day)
  VALUES (new.user_id, v_today)
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE public.garden_animal_discovery_state_v1
  SET discovery_day = v_today,
      discoveries_today = 0,
      updated_at = now()
  WHERE user_id = new.user_id
    AND discovery_day <> v_today;

  SELECT * INTO v_state
  FROM public.garden_animal_discovery_state_v1
  WHERE user_id = new.user_id
  FOR UPDATE;

  IF new.animal_kind IN ('owl', 'fox', 'raccoon', 'mole')
     AND NOT v_was_discovered
     AND coalesce(v_state.discoveries_today, 0) < 1 THEN
    UPDATE public.garden_animal_discovery_state_v1
    SET discoveries_today = 1,
        visits_since_new = 0,
        last_new_kind = new.animal_kind,
        updated_at = now()
    WHERE user_id = new.user_id;
  ELSE
    UPDATE public.garden_animal_discovery_state_v1
    SET visits_since_new = least(1000, coalesce(visits_since_new, 0) + 1),
        updated_at = now()
    WHERE user_id = new.user_id;
  END IF;

  RETURN new;
END;
$function$;

