$function$;

CREATE OR REPLACE FUNCTION public.respond_to_garden_friend_request(p_request_id uuid, p_accept boolean)
 RETURNS TABLE(request_id uuid, request_status text, friend_id uuid, friend_nickname text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me uuid := auth.uid();
  v_request public.garden_friend_requests%rowtype;
  v_friend_json jsonb;
  v_friend_name text;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  select * into v_request
  from public.garden_friend_requests r
  where r.id = p_request_id
    and r.to_user_id = v_me
  for update;

  if not found then
    raise exception 'FRIEND_REQUEST_NOT_FOUND';
  end if;

  if v_request.status <> 'pending' then
    return query select v_request.id, v_request.status, v_request.from_user_id, v_request.from_nickname;
    return;
  end if;

  if not coalesce(p_accept, false) then
    update public.garden_friend_requests
    set status = 'declined', responded_at = now()
    where id = v_request.id;
    return query select v_request.id, 'declined'::text, v_request.from_user_id, v_request.from_nickname;
    return;
  end if;

  if v_request.expires_at <= now() then
    update public.garden_friend_requests
    set status = 'expired', responded_at = now()
    where id = v_request.id;
    raise exception 'FRIEND_REQUEST_EXPIRED';
  end if;

  if exists (
    select 1 from public.list_my_garden_friends() f
    where f.friend_id = v_request.from_user_id
  ) then
    update public.garden_friend_requests
    set status = 'accepted', responded_at = now()
    where id = v_request.id;
    return query select v_request.id, 'accepted'::text, v_request.from_user_id, v_request.from_nickname;
    return;
  end if;

  -- 기존 친구 수락 RPC를 호출하므로 기존 친구 테이블·정원 기록 규칙은 그대로 보존됩니다.
  select to_jsonb(f) into v_friend_json
  from public.accept_garden_friend_invite(v_request.invite_token) f
  limit 1;

  v_friend_name := coalesce(nullif(v_friend_json ->> 'friend_nickname', ''), v_request.from_nickname);

  update public.garden_friend_requests
  set status = 'accepted', responded_at = now()
  where id = v_request.id;

  update public.garden_friend_requests r
  set status = 'cancelled', responded_at = now()
  where r.id <> v_request.id
    and r.status = 'pending'
    and ((r.from_user_id = v_me and r.to_user_id = v_request.from_user_id)
      or (r.from_user_id = v_request.from_user_id and r.to_user_id = v_me));

  return query select v_request.id, 'accepted'::text, v_request.from_user_id, v_friend_name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.run_my_garden_retention_dev_cleanup(p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted_count integer := 0;
  v_expired_tests jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_mode not in ('wind', '31') then
    raise exception 'INVALID_RETENTION_CLEANUP_MODE';
  end if;

  with deleted as (
    delete from public.garden_letter_retention_dev_tests
     where owner_id = auth.uid()
       and scenario = p_mode
       and available_at <= now() - interval '30 days'
    returning id, scenario, sender_name, title, body, delivery_kind, available_at, created_at
  )
  select
    count(*)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', id,
          'scenario', scenario,
          'sender_name', sender_name,
          'title', title,
          'body', body,
          'delivery_kind', delivery_kind,
          'available_at', available_at,
          'created_at', created_at
        )
        order by available_at asc
      ),
      '[]'::jsonb
    )
  into v_deleted_count, v_expired_tests
  from deleted;

  -- 31일 테스트는 "사용자가 없을 때 정리됨 → 다음 방문에서 한 번 안내"를 따로 검수합니다.
  if p_mode = '31' and v_deleted_count > 0 then
    insert into public.garden_letter_retention_dev_notices (
      owner_id, scenario, expired_count, created_at, acknowledged_at
    ) values (
      auth.uid(), '31', v_deleted_count, now(), null
    )
    on conflict (owner_id, scenario) do update
      set expired_count = excluded.expired_count,
          created_at = excluded.created_at,
          acknowledged_at = null;
  end if;

  return jsonb_build_object(
    'deleted_count', v_deleted_count,
    'expired_tests', v_expired_tests
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_garden_feedback_admin_reply(p_feedback_id uuid, p_reply text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin_id constant uuid := '2029663f-4af7-48df-a32e-47f855c9f1e1'::uuid;
  v_reply text := btrim(coalesce(p_reply, ''));
  v_found boolean := false;
begin
  if auth.uid() is distinct from v_admin_id then
    raise exception 'FEEDBACK_ADMIN_ONLY';
  end if;

  if char_length(v_reply) < 1 or char_length(v_reply) > 1200 then
    raise exception 'INVALID_OPERATOR_REPLY';
  end if;

  update public.garden_feedback
  set
    operator_reply = v_reply,
    operator_status = 'replied',
    operator_read_at = coalesce(operator_read_at, now())
  where id = p_feedback_id
  returning true into v_found;

  return coalesce(v_found, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_garden_record(p_mood text, p_one_line text, p_detail text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_growth integer;
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_moods text[];
begin
  if auth.uid() is null then
    raise exception '로그인이 필요합니다.';
  end if;

  v_moods := string_to_array(coalesce(p_mood, ''), '|');

  if cardinality(v_moods) not between 1 and 3
    or not (
      v_moods <@ array[
        'happy',
        'excited',
        'proud',
        'grateful',
        'comfortable',
        'calm',
        'good',
        'complex',
        'tired',
        'sad',
        'upset',
        'anxious',
        'neutral',
        'lonely',
        'frustrated',
        'angry',
        'regretful',
        'disappointed'
      ]::text[]
    )
    or cardinality(v_moods) <> (
      select count(distinct mood_key)
      from unnest(v_moods) as t(mood_key)
    )
  then
    raise exception '올바르지 않은 감정 값입니다.';
  end if;

  if char_length(trim(coalesce(p_one_line, ''))) = 0 then
    raise exception '한 줄 기록이 필요합니다.';
  end if;

  insert into public.garden_profiles (id)
  values (auth.uid())
  on conflict (id) do nothing;

  perform 1
  from public.garden_profiles
  where id = auth.uid()
  for update;

  if exists (
    select 1
    from public.garden_records
    where user_id = auth.uid()
      and (created_at at time zone 'Asia/Seoul')::date = v_today
  ) then
    raise exception using
      message = 'TODAY_RECORD_ALREADY_SAVED',
      errcode = 'P0001';
  end if;

  insert into public.garden_records (
    user_id,
    mood,
    one_line,
    detail
  )
  values (
    auth.uid(),
    p_mood,
    trim(p_one_line),
    nullif(trim(coalesce(p_detail, '')), '')
  );

  update public.garden_profiles
  set growth_count = growth_count + 1
  where id = auth.uid()
  returning growth_count into v_growth;

  return v_growth;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_my_garden_dev_found_item_layout_v2(p_items jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_requested_count integer := 0;
  v_distinct_count integer := 0;
  v_updated_count integer := 0;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'INVALID_LAYOUT_PAYLOAD';
  end if;

  v_requested_count := jsonb_array_length(p_items);

  if v_requested_count = 0 then
    return 0;
  end if;

  if v_requested_count > 200 then
    raise exception 'TOO_MANY_LAYOUT_ITEMS';
  end if;

  with requested as (
    select
      (value ->> 'id')::uuid as id,
      lower(trim(coalesce(value ->> 'storage_state', ''))) as storage_state,
      case
        when value ? 'position_x' and jsonb_typeof(value -> 'position_x') <> 'null'
          then (value ->> 'position_x')::numeric
        else null
      end as position_x,
      case
        when value ? 'position_y' and jsonb_typeof(value -> 'position_y') <> 'null'
          then (value ->> 'position_y')::numeric
        else null
      end as position_y
    from jsonb_array_elements(p_items)
  )
  select count(distinct id)
  into v_distinct_count
  from requested;

  if v_distinct_count <> v_requested_count then
    raise exception 'DUPLICATE_LAYOUT_ITEM';
  end if;

  if exists (
    with requested as (
      select
        (value ->> 'id')::uuid as id,
        lower(trim(coalesce(value ->> 'storage_state', ''))) as storage_state,
        case
          when value ? 'position_x' and jsonb_typeof(value -> 'position_x') <> 'null'
            then (value ->> 'position_x')::numeric
          else null
        end as position_x,
        case
          when value ? 'position_y' and jsonb_typeof(value -> 'position_y') <> 'null'
            then (value ->> 'position_y')::numeric
          else null
        end as position_y
      from jsonb_array_elements(p_items)
    )
    select 1
    from requested
    where id is null
       or storage_state not in ('placed', 'inventory')
       or ((position_x is null) <> (position_y is null))
       or (position_x is not null and position_x not between 0 and 100)
       or (position_y is not null and position_y not between 0 and 100)
  ) then
    raise exception 'INVALID_LAYOUT_ITEM';
  end if;

  with requested as (
    select
      (value ->> 'id')::uuid as id,
      lower(trim(coalesce(value ->> 'storage_state', ''))) as storage_state,
      case
        when value ? 'position_x' and jsonb_typeof(value -> 'position_x') <> 'null'
          then (value ->> 'position_x')::numeric
        else null
      end as position_x,
      case
        when value ? 'position_y' and jsonb_typeof(value -> 'position_y') <> 'null'
          then (value ->> 'position_y')::numeric
        else null
      end as position_y
    from jsonb_array_elements(p_items)
  ),
  updated as (
    update public.garden_dev_found_items as item
    set
      storage_state = requested.storage_state,
      -- 좌표가 전달되지 않은 장식은 기존 위치를 보존합니다.
      position_x = case
        when requested.position_x is null then item.position_x
        else round(requested.position_x, 3)
      end,
      position_y = case
        when requested.position_y is null then item.position_y
        else round(requested.position_y, 3)
      end,
      updated_at = now()
    from requested
    where item.id = requested.id
      and item.user_id = v_user_id
    returning item.id
  )
  select count(*)
  into v_updated_count
  from updated;

  if v_updated_count <> v_requested_count then
    raise exception 'ITEM_NOT_OWNED_OR_NOT_FOUND';
  end if;

  return v_updated_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_my_garden_dev_found_item_positions(p_positions jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_requested_count integer := 0;
  v_updated_count integer := 0;
begin
  if v_user_id is null then
    raise exception '로그인이 필요해요.';
  end if;

  if jsonb_typeof(p_positions) <> 'array' then
    raise exception '배치 정보 형식이 올바르지 않아요.';
  end if;

  v_requested_count := jsonb_array_length(p_positions);

  if v_requested_count = 0 then
    return 0;
  end if;

  if v_requested_count > 40 then
    raise exception '한 번에 옮길 수 있는 작은 것이 너무 많아요.';
  end if;

  with requested as (
    select
      (value ->> 'id')::uuid as id,
      (value ->> 'position_x')::numeric as position_x,
      (value ->> 'position_y')::numeric as position_y
    from jsonb_array_elements(p_positions)
  ),
  validated as (
    select *
    from requested
    where id is not null
      and position_x between 0 and 100
      and position_y between 0 and 100
  ),
  updated as (
    update public.garden_dev_found_items as found
    set
      position_x = round(validated.position_x, 3),
      position_y = round(validated.position_y, 3),
      updated_at = now()
    from validated
    where found.id = validated.id
      and found.user_id = v_user_id
    returning found.id
  )
  select count(*) into v_updated_count from updated;

  if v_updated_count <> v_requested_count then
    raise exception '내 정원의 작은 것만 저장할 수 있어요.';
  end if;

  return v_updated_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_my_garden_dev_trade_item_positions(p_positions jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  update public.garden_dev_trade_items t
  set position_x = p.position_x, position_y = p.position_y
  from jsonb_to_recordset(coalesce(p_positions, '[]'::jsonb)) as p(id uuid, position_x numeric, position_y numeric)
  where t.id = p.id and t.user_id = auth.uid();
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_my_garden_found_item_positions(p_positions jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_requested_count integer := 0;
  v_updated_count integer := 0;
begin
  if auth.uid() is null then
    raise exception '로그인이 필요해요.';
  end if;

  if jsonb_typeof(p_positions) <> 'array' then
    raise exception '배치 정보 형식이 올바르지 않아요.';
  end if;

  v_requested_count := jsonb_array_length(p_positions);
  if v_requested_count = 0 then
    return 0;
  end if;

  -- 이 기능은 현재 발견한 작은 것 수만 다룹니다. 비정상적으로 큰 요청은 막습니다.
  if v_requested_count > 40 then
    raise exception '한 번에 옮길 수 있는 작은 것이 너무 많아요.';
  end if;

  with requested as (
    select
      (value ->> 'id')::uuid as id,
      (value ->> 'position_x')::numeric as position_x,
      (value ->> 'position_y')::numeric as position_y
    from jsonb_array_elements(p_positions)
  ),
  validated as (
    select *
    from requested
    where id is not null
      and position_x between 0 and 100
      and position_y between 0 and 100
  ),
  updated as (
    update public.garden_found_items as found
    set
      position_x = round(validated.position_x, 3),
      position_y = round(validated.position_y, 3)
    from validated
    where found.id = validated.id
      and exists (
        select 1
        from public.garden_records as record
        where record.id = found.record_id
          -- 현재 정원 기록 테이블의 일반적인 소유자 열 이름들을 읽기 전용으로 확인합니다.
          -- 실제 데이터는 이 사용자의 기록과 연결된 작은 것만 갱신됩니다.
          and coalesce(
            to_jsonb(record) ->> 'user_id',
            to_jsonb(record) ->> 'profile_id',
            to_jsonb(record) ->> 'owner_id'
          ) = auth.uid()::text
      )
    returning found.id
  )
  select count(*) into v_updated_count from updated;

  if v_updated_count <> v_requested_count then
    raise exception '내 정원의 작은 것만 저장할 수 있어요.';
  end if;

  return v_updated_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_dev_test_garden_letter(p_test_friend_id uuid, p_title text, p_body text)
 RETURNS TABLE(letter_id uuid, recipient_nickname text, delivery_kind text, available_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_growth integer := 0;
  v_nickname text;
  v_delivery_kind text := 'little_bird';
  v_available_at timestamptz := now() + interval '1 minute';
  v_letter_id uuid;
begin
  if v_user_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if char_length(trim(coalesce(p_title, ''))) = 0 then
    raise exception '편지 제목을 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_title, ''))) > 100 then
    raise exception '편지 제목은 100자 안으로 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) = 0 then
    raise exception '전하고 싶은 이야기를 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) > 2000 then
    raise exception '편지는 2,000자 안으로 적어 주세요.';
  end if;

  select d.nickname
    into v_nickname
  from public.garden_dev_test_friends as d
  where d.owner_id = v_user_id
    and d.id = p_test_friend_id;

  if not found then
    raise exception '테스트 친구를 먼저 만들어 주세요.';
  end if;

  select coalesce(p.growth_count, 0)
    into v_growth
  from public.garden_profiles as p
  where p.id = v_user_id;

  if not found then
    raise exception '내 정원 정보를 먼저 준비해 주세요.';
  end if;

  if v_growth between 0 and 2 then
    v_delivery_kind := 'little_bird';
  elsif v_growth between 3 and 7 then
    v_delivery_kind := 'squirrel';
  elsif v_growth between 8 and 17 then
    v_delivery_kind := 'sprout_bird';
  else
    v_delivery_kind := 'swift_bird';
  end if;

  insert into public.garden_dev_test_letters (
    owner_id, test_friend_id, title, body, delivery_kind, available_at
  )
  values (
    v_user_id, p_test_friend_id, trim(p_title), trim(p_body), v_delivery_kind, v_available_at
  )
  returning id into v_letter_id;

  return query select v_letter_id, v_nickname, v_delivery_kind, v_available_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_dev_test_garden_letter_with_dev_animal_v2(p_visit_id uuid, p_test_friend_id uuid, p_title text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_presence public.garden_dev_animal_v2_presence%rowtype;
  v_visit public.garden_dev_animal_v2_visits%rowtype;
  v_letter_id uuid;
  v_recipient_nickname text;
  v_delivery_kind text;
  v_available_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  insert into public.garden_dev_animal_v2_presence (
    user_id, last_seen_at, last_change_at, next_event_at, updated_at
  )
  values (
    v_user_id,
    v_now,
    v_now,
    v_now + make_interval(secs => 45 + floor(random() * 96)::integer),
    v_now
  )
  on conflict (user_id) do nothing;

  select *
    into v_presence
  from public.garden_dev_animal_v2_presence
  where user_id = v_user_id
  for update;

  select *
    into v_visit
  from public.garden_dev_animal_v2_visits
  where id = p_visit_id
    and user_id = v_user_id
  for update;

  if not found or v_visit.visit_state <> 'visiting' then
    raise exception 'ANIMAL_NOT_AVAILABLE';
  end if;

  select letter_id, recipient_nickname, delivery_kind, available_at
    into v_letter_id, v_recipient_nickname, v_delivery_kind, v_available_at
  from public.send_dev_test_garden_letter(
    p_test_friend_id,
    p_title,
    p_body
  );

  update public.garden_dev_animal_v2_visits
  set visit_state = 'departing',
      departing_at = v_now,
      departure_reason = 'letter',
      trace_kind = null,
      trace_expires_at = null,
      updated_at = v_now
  where id = v_visit.id;

  update public.garden_dev_animal_v2_presence
  set last_seen_at = v_now,
      last_change_at = v_now,
      next_event_at = v_now + make_interval(secs => 35 + floor(random() * 136)::integer),
      last_animal_kind = v_visit.animal_kind,
      last_animal_departed_at = v_now,
      updated_at = v_now
  where user_id = v_user_id;

  return jsonb_build_object(
    'letter_id', v_letter_id,
    'recipient_nickname', v_recipient_nickname,
    'delivery_kind', v_delivery_kind,
    'available_at', v_available_at,
    'visit_id', v_visit.id,
    'visit_state', 'departing',
    'departing_at', v_now,
    'is_dev_test', true
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_garden_letter(p_recipient_id uuid, p_title text, p_body text)
 RETURNS TABLE(letter_id uuid, recipient_nickname text, delivery_kind text, available_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  select *
  from public.send_garden_letter(
    p_recipient_id,
    p_title,
    p_body,
    null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_garden_letter(p_recipient_id uuid, p_title text, p_body text, p_delivery_kind text)
 RETURNS TABLE(letter_id uuid, recipient_nickname text, delivery_kind text, available_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sender_id uuid := auth.uid();
  v_sender_name text;
  v_recipient_name text;
  v_growth integer := 0;
  v_delivery_kind text := lower(trim(coalesce(p_delivery_kind, '')));
  v_available_at timestamptz;
  v_letter_id uuid;
begin
  if v_sender_id is null then
    raise exception '로그인이 필요합니다.';
  end if;

  if p_recipient_id is null then
    raise exception '편지를 받을 친구를 골라 주세요.';
  end if;

  if p_recipient_id = v_sender_id then
    raise exception '나에게는 편지를 보낼 수 없어요.';
  end if;

  perform 1
  from public.garden_friendships
  where user_id = v_sender_id
    and friend_id = p_recipient_id
  for key share;

  if not found then
    raise exception '친구가 된 사람에게만 편지를 보낼 수 있어요.';
  end if;

  if char_length(trim(coalesce(p_title, ''))) = 0 then
    raise exception '편지 제목을 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_title, ''))) > 100 then
    raise exception '편지 제목은 100자 안으로 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) = 0 then
    raise exception '전하고 싶은 이야기를 적어 주세요.';
  end if;

  if char_length(trim(coalesce(p_body, ''))) > 2000 then
    raise exception '편지는 2,000자 안으로 적어 주세요.';
  end if;

  select
    coalesce(nickname, '친구'),
    coalesce(growth_count, 0)
  into
    v_sender_name,
    v_growth
  from public.garden_profiles
  where id = v_sender_id;

  if not found then
    raise exception '내 정원 정보를 먼저 준비해 주세요.';
  end if;

  select coalesce(nickname, '친구')
  into v_recipient_name
  from public.garden_profiles
  where id = p_recipient_id;

  if not found then
    raise exception '친구의 정원 정보를 찾지 못했어요.';
  end if;

  if v_delivery_kind = '' then
    if v_growth between 0 and 2 then
      v_delivery_kind := 'bird';
    elsif v_growth between 3 and 7 then
      v_delivery_kind := 'squirrel';
    elsif v_growth between 8 and 17 then
      v_delivery_kind := 'rabbit';
    else
      v_delivery_kind := 'hedgehog';
    end if;
  end if;

  if v_delivery_kind not in ('bird', 'owl', 'rabbit', 'fox', 'squirrel', 'raccoon', 'hedgehog', 'mole') then
    raise exception '알 수 없는 전달 동물입니다.';
  end if;

  v_available_at := case v_delivery_kind
    when 'bird' then now() + interval '2 hours'
    when 'owl' then now() + interval '2 hours'
    when 'rabbit' then now() + interval '6 hours'
    when 'fox' then now() + interval '6 hours'
    when 'squirrel' then now() + interval '12 hours'
    when 'raccoon' then now() + interval '12 hours'
    when 'hedgehog' then now() + interval '24 hours'
    when 'mole' then now() + interval '24 hours'
  end;

  insert into public.garden_letters (
    sender_id,
    recipient_id,
    sender_name,
    title,
    body,
    delivery_kind,
    available_at
  )
  values (
    v_sender_id,
    p_recipient_id,
    v_sender_name,
    trim(p_title),
    trim(p_body),
    v_delivery_kind,
    v_available_at
  )
  returning id into v_letter_id;

  return query
  select
    v_letter_id,
    v_recipient_name,
    v_delivery_kind,
    v_available_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_garden_letter_with_dev_animal_v2(p_visit_id uuid, p_recipient_id uuid, p_title text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_presence public.garden_dev_animal_v2_presence%rowtype;
  v_visit public.garden_dev_animal_v2_visits%rowtype;
  v_letter_id uuid;
  v_recipient_nickname text;
  v_delivery_kind text;
  v_available_at timestamptz;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  insert into public.garden_dev_animal_v2_presence (
    user_id, last_seen_at, last_change_at, next_event_at, updated_at
  )
  values (
    v_user_id,
    v_now,
    v_now,
    v_now + make_interval(secs => 45 + floor(random() * 96)::integer),
    v_now
  )
  on conflict (user_id) do nothing;

  select *
    into v_presence
  from public.garden_dev_animal_v2_presence
  where user_id = v_user_id
  for update;

  select *
    into v_visit
  from public.garden_dev_animal_v2_visits
  where id = p_visit_id
    and user_id = v_user_id
  for update;

  if not found or v_visit.visit_state <> 'visiting' then
    raise exception 'ANIMAL_NOT_AVAILABLE';
  end if;

  select letter_id, recipient_nickname, delivery_kind, available_at
    into v_letter_id, v_recipient_nickname, v_delivery_kind, v_available_at
  from public.send_garden_letter(
    p_recipient_id,
    p_title,
    p_body,
    v_visit.animal_kind
  );

  update public.garden_dev_animal_v2_visits
  set visit_state = 'departing',
      departing_at = v_now,
      departure_reason = 'letter',
      trace_kind = null,
      trace_expires_at = null,
      updated_at = v_now
  where id = v_visit.id;

  update public.garden_dev_animal_v2_presence
  set last_seen_at = v_now,
      last_change_at = v_now,
      next_event_at = v_now + make_interval(secs => 35 + floor(random() * 136)::integer),
      last_animal_kind = v_visit.animal_kind,
      last_animal_departed_at = v_now,
      updated_at = v_now
  where user_id = v_user_id;

  return jsonb_build_object(
    'letter_id', v_letter_id,
    'recipient_nickname', v_recipient_nickname,
    'delivery_kind', v_delivery_kind,
    'available_at', v_available_at,
    'visit_id', v_visit.id,
    'visit_state', 'departing',
    'departing_at', v_now
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_my_garden_special_friend_letter_v1(p_friend_key text, p_recipient_id uuid, p_title text, p_body text)
 RETURNS TABLE(letter_id uuid, recipient_nickname text, sent_at timestamp with time zone, available_at timestamp with time zone, return_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_friend_key text := lower(btrim(coalesce(p_friend_key, '')));
  v_title text := btrim(coalesce(p_title, ''));
  v_body text := btrim(coalesce(p_body, ''));
  v_sender_name text := '';
  v_recipient_name text := '';
  v_active_return_at timestamptz;
  v_letter_id uuid;
  v_sent_at timestamptz := now();
  v_available_at timestamptz := now() + interval '30 minutes';
  v_return_at timestamptz := now() + interval '60 minutes';
  v_recipient_is_friend boolean := false;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if v_friend_key not in ('forest_unicorn', 'little_light_dragon') then
    raise exception 'SPECIAL_FRIEND_NOT_FOUND';
  end if;

  if p_recipient_id is null or p_recipient_id = v_me then
    raise exception 'SPECIAL_FRIEND_RECIPIENT_NOT_FOUND';
  end if;

  if char_length(v_title) < 1 or char_length(v_title) > 100 then
    raise exception 'INVALID_LETTER_TITLE';
  end if;

  if char_length(v_body) < 1 or char_length(v_body) > 2000 then
    raise exception 'INVALID_LETTER_BODY';
  end if;

  select exists (
    select 1
    from public.list_my_garden_friends() f
    where f.friend_id = p_recipient_id

    union all

    select 1
    from public.get_my_dev_test_friend() d
    where d.friend_id = p_recipient_id
  )
  into v_recipient_is_friend;

  if not v_recipient_is_friend then
    raise exception 'SPECIAL_FRIEND_RECIPIENT_NOT_FOUND';
  end if;

  -- 특별 친구 자신이 귀환하기 전에는 다시 맡길 수 없음.
  insert into public.garden_special_friend_states (owner_id, friend_key)
  values (v_me, v_friend_key)
  on conflict (owner_id, friend_key) do nothing;

  select active_return_at
    into v_active_return_at
  from public.garden_special_friend_states
  where owner_id = v_me
    and friend_key = v_friend_key
  for update;

  if v_active_return_at is not null and v_active_return_at > now() then
    raise exception 'SPECIAL_FRIEND_AWAY';
  end if;

  -- 같은 친구에게 이미 도착했거나 읽지 않은 편지가 있어도
  -- 새 편지는 계속 보낼 수 있음.

  select coalesce(nickname, '')
    into v_sender_name
  from public.garden_profiles
  where id = v_me;

  select coalesce(nickname, '')
    into v_recipient_name
  from public.garden_profiles
  where id = p_recipient_id;

  insert into public.garden_special_friend_letters (
    sender_id,
    recipient_id,
    sender_name,
    recipient_name,
    friend_key,
    title,
    body,
    sent_at,
    available_at,
    return_at
  )
  values (
    v_me,
    p_recipient_id,
    left(coalesce(v_sender_name, ''), 80),
    left(coalesce(v_recipient_name, ''), 80),
    v_friend_key,
    v_title,
    v_body,
    v_sent_at,
    v_available_at,
    v_return_at
  )
  returning id into v_letter_id;

  update public.garden_special_friend_states
  set active_letter_id = v_letter_id,
      active_return_at = v_return_at,
      updated_at = now()
  where owner_id = v_me
    and friend_key = v_friend_key;

  return query
  select
    v_letter_id,
    coalesce(v_recipient_name, ''),
    v_sent_at,
    v_available_at,
    v_return_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_garden_feedback_operator_reply_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.operator_reply := nullif(btrim(coalesce(new.operator_reply, '')), '');

  if new.operator_reply is distinct from old.operator_reply then
    new.operator_replied_at := case
      when new.operator_reply is null then null
      else now()
    end;

    if new.operator_reply is not null then
      new.operator_status := 'replied';
      new.operator_read_at := coalesce(new.operator_read_at, now());
    elsif old.operator_status = 'replied' then
      new.operator_status := case
        when new.operator_read_at is null then 'new'
        else 'read'
      end;
    end if;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_dev_found_item_storage(p_item_id uuid, p_storage_state text)
 RETURNS TABLE(id uuid, storage_state text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_storage_state text := lower(trim(coalesce(p_storage_state, '')));
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if v_storage_state not in ('inventory', 'placed') then
    raise exception 'INVALID_STORAGE_STATE';
  end if;

  return query
  update public.garden_dev_found_items as item
  set storage_state = v_storage_state
  where item.id = p_item_id
    and exists (
      select 1
      from public.garden_records as record
      where record.id = item.record_id
        and record.user_id = auth.uid()
    )
  returning item.id, item.storage_state;

  if not found then
    raise exception 'FOUND_ITEM_NOT_OWNED_OR_NOT_FOUND';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_dev_trade_item_storage(p_item_id uuid, p_storage_state text)
 RETURNS TABLE(id uuid, storage_state text, position_x numeric, position_y numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_storage_state not in ('inventory','placed') then raise exception 'INVALID_STORAGE_STATE'; end if;
  return query
  update public.garden_dev_trade_items t
  set storage_state = p_storage_state
  where t.id = p_item_id and t.user_id = auth.uid()
  returning t.id, t.storage_state, t.position_x, t.position_y;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_record_visibility(p_record_id uuid, p_is_public boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  update public.garden_records
  set is_public = coalesce(p_is_public, false)
  where id = p_record_id
    and user_id = auth.uid();

  if not found then
    raise exception 'GARDEN_RECORD_NOT_FOUND';
  end if;

  return true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_shared_tree_name_piece(p_tree_id uuid, p_piece_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_tree public.garden_shared_trees%rowtype;
  v_role text;
  v_piece_key text := nullif(btrim(coalesce(p_piece_key, '')), '');
  v_existing_piece text;
  v_emotion_key text;
  v_nature_key text;
  v_emotion_label text;
  v_nature_label text;
  v_final_name text;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  select t.*
  into v_tree
  from public.garden_shared_trees t
  where t.id = p_tree_id
    and v_me in (t.user_one_id, t.user_two_id)
    and t.growth_version = 2
    and t.completed_at is not null
    and t.relationship_ended_at is null
  for update;

  if not found then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  insert into public.garden_shared_tree_profiles (tree_id)
  values (v_tree.id)
  on conflict (tree_id) do nothing;

  select p.final_name
  into v_final_name
  from public.garden_shared_tree_profiles p
  where p.tree_id = v_tree.id
  for update;

  if v_final_name is not null then
    raise exception 'SHARED_TREE_NAME_ALREADY_FINALIZED';
  end if;

  select s.name_piece_role, s.name_piece_key
  into v_role, v_existing_piece
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id
    and s.user_id = v_me
  for update;

  if v_role is null or v_role not in ('emotion', 'nature') then
    raise exception 'SHARED_TREE_NAME_ROLE_NOT_READY';
  end if;

  if v_piece_key is null then
    raise exception 'SHARED_TREE_NAME_PIECE_INVALID';
  end if;

  if v_existing_piece is not null then
    if v_existing_piece = v_piece_key then
      return public.get_my_garden_shared_tree_v2(v_tree.id);
    end if;
    raise exception 'SHARED_TREE_NAME_PIECE_ALREADY_SET';
  end if;

  if v_role = 'emotion' and v_piece_key not in ('warm', 'calm', 'sparkling') then
    raise exception 'SHARED_TREE_NAME_PIECE_INVALID';
  elsif v_role = 'nature' and v_piece_key not in ('summerlight', 'dawnleaf', 'starfruit') then
    raise exception 'SHARED_TREE_NAME_PIECE_INVALID';
  end if;

  update public.garden_shared_tree_member_states
  set name_piece_key = v_piece_key,
      name_piece_at = now(),
      updated_at = now()
  where tree_id = v_tree.id
    and user_id = v_me;

  select
    max(s.name_piece_key) filter (where s.name_piece_role = 'emotion'),
    max(s.name_piece_key) filter (where s.name_piece_role = 'nature')
  into v_emotion_key, v_nature_key
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id;

  if v_emotion_key is not null and v_nature_key is not null then
    v_emotion_label := case v_emotion_key
      when 'warm' then '포근한'
      when 'calm' then '고요한'
      when 'sparkling' then '반짝이는'
      else null
    end;

    v_nature_label := case v_nature_key
      when 'summerlight' then '여름빛'
      when 'dawnleaf' then '새벽잎'
      when 'starfruit' then '별열매'
      else null
    end;

    if v_emotion_label is null or v_nature_label is null then
      raise exception 'SHARED_TREE_NAME_PIECE_INVALID';
    end if;

    v_final_name := v_emotion_label || ' ' || v_nature_label || ' 나무';

    update public.garden_shared_tree_profiles
    set final_name = v_final_name,
        name_finalized_at = now(),
        updated_at = now()
    where tree_id = v_tree.id
      and final_name is null;
  end if;

  return public.get_my_garden_shared_tree_v2(v_tree.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_shared_tree_world_choice(p_tree_id uuid, p_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_tree public.garden_shared_trees%rowtype;
  v_choice text := lower(btrim(coalesce(p_choice, '')));
  v_final_name text;
  v_consent boolean;
  v_both_world boolean;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  if v_choice not in ('private', 'world', 'withdraw') then
    raise exception 'SHARED_TREE_WORLD_CHOICE_INVALID';
  end if;

  select t.*
  into v_tree
  from public.garden_shared_trees t
  where t.id = p_tree_id
    and v_me in (t.user_one_id, t.user_two_id)
    and t.growth_version = 2
    and t.completed_at is not null
    and t.relationship_ended_at is null
  for update;

  if not found then
    raise exception 'SHARED_TREE_V2_NOT_FOUND';
  end if;

  select p.final_name
  into v_final_name
  from public.garden_shared_tree_profiles p
  where p.tree_id = v_tree.id
  for update;

  if v_final_name is null then
    raise exception 'SHARED_TREE_NAME_NOT_READY';
  end if;

  v_consent := case
    when v_choice = 'world' then true
    when v_choice = 'private' then false
    else null
  end;

  update public.garden_shared_tree_member_states
  set world_consent = v_consent,
      world_consent_at = case when v_consent is null then null else now() end,
      updated_at = now()
  where tree_id = v_tree.id
    and user_id = v_me;

  select count(*) = 2
  into v_both_world
  from public.garden_shared_tree_member_states s
  where s.tree_id = v_tree.id
    and s.world_consent is true;

  if v_both_world then
    insert into public.garden_shared_tree_world_placements (
      tree_id,
      placement_state,
      hidden_at,
      updated_at
    )
    values (
      v_tree.id,
      'queued',
      null,
      now()
    )
    on conflict (tree_id) do update
      set placement_state = case
            when public.garden_shared_tree_world_placements.placement_state = 'placed'
              then 'placed'
            else 'queued'
          end,
          hidden_at = null,
          updated_at = now();
  else
    update public.garden_shared_tree_world_placements
    set placement_state = 'hidden',
        hidden_at = now(),
        updated_at = now()
    where tree_id = v_tree.id
      and placement_state <> 'hidden';
  end if;

  return public.get_my_garden_shared_tree_v2(v_tree.id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_my_garden_tree_name(p_tree_name text)
 RETURNS TABLE(saved_tree_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  normalized_name text := btrim(coalesce(p_tree_name, ''));
  existing_name text;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if char_length(normalized_name) < 1 or char_length(normalized_name) > 24 then
    raise exception 'TREE_NAME_LENGTH_INVALID';
  end if;

  select tree_name
    into existing_name
  from public.garden_profiles
  where id = auth.uid()
  for update;

  if not found then
    raise exception 'GARDEN_PROFILE_NOT_FOUND';
  end if;

  if coalesce(btrim(existing_name), '') <> '' then
    raise exception 'TREE_NAME_ALREADY_SET';
  end if;

  return query
  update public.garden_profiles
     set tree_name = normalized_name
   where id = auth.uid()
  returning tree_name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_todayforest_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.setup_my_garden_retention_dev_test(p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_available_at timestamptz;
  v_id bigint;
begin
  if auth.uid() is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  if p_mode not in ('21', 'wind', '31') then
    raise exception 'INVALID_RETENTION_TEST_MODE';
  end if;

  -- 같은 로그인 계정의 DEV 데이터만 교체합니다.
  delete from public.garden_letter_retention_dev_tests
   where owner_id = auth.uid();

  delete from public.garden_letter_retention_dev_notices
   where owner_id = auth.uid();

  if p_mode = '21' then
    v_available_at := now() - interval '21 days';
  elsif p_mode = 'wind' then
    -- 페이지를 연 뒤 약 18초 후 30일 경계를 지나도록 준비합니다.
    v_available_at := now() - interval '30 days' + interval '18 seconds';
  else
    v_available_at := now() - interval '31 days';
  end if;

  insert into public.garden_letter_retention_dev_tests (
    owner_id, scenario, available_at
  ) values (
    auth.uid(), p_mode, v_available_at
  ) returning id into v_id;

  return jsonb_build_object(
    'test_id', v_id,
    'scenario', p_mode,
    'available_at', v_available_at
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_my_garden_feedback(p_category text, p_message text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_message text := btrim(coalesce(p_message, ''));
  v_nickname text := '';
  v_feedback_id uuid;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if v_category not in ('issue', 'idea', 'cheer') then
    raise exception 'INVALID_FEEDBACK_CATEGORY';
  end if;

  if char_length(v_message) < 1 or char_length(v_message) > 1000 then
    raise exception 'INVALID_FEEDBACK_MESSAGE';
  end if;

  select coalesce(nickname, '')
    into v_nickname
  from public.garden_profiles
  where id = v_user_id;

  insert into public.garden_feedback (
    user_id,
    nickname_snapshot,
    category,
    message
  )
  values (
    v_user_id,
    left(coalesce(v_nickname, ''), 80),
    v_category,
    v_message
  )
  returning id into v_feedback_id;

  return v_feedback_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_my_garden_animal_visit(p_begin_when_ready boolean DEFAULT true)
 RETURNS TABLE(visit_state text, animal_kind text, approach_started_at timestamp with time zone, arrives_at timestamp with time zone, leaves_at timestamp with time zone, next_available_at timestamp with time zone, trace_expires_at timestamp with time zone, last_departed_at timestamp with time zone, last_departure_reason text, visits_started_today integer, visit_limit_today integer, visit_bonus_today boolean, server_now timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_today date := (v_now at time zone 'Asia/Seoul')::date;
  v_growth integer := 0;
  v_base_limit integer := 2;
  v_limit integer := 2;
  v_bonus boolean := false;
  v_kind text;
  v_dwell interval;
  v_delay_seconds integer;
  v_next_day_start timestamptz;
  v_visit public.garden_animal_visit_states%rowtype;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- 첫 방문 계정도 한 행만 만들고, 동시에 여러 기기에서 열어도 PK로 하나로 합칩니다.
  insert into public.garden_animal_visit_states (user_id, visit_day)
  values (v_user_id, v_today)
  on conflict (user_id) do nothing;

  select * into v_visit
  from public.garden_animal_visit_states
  where user_id = v_user_id
  for update;

  -- 한국 날짜가 바뀌면 그날의 방문 횟수만 새로 셉니다.
  -- 자정을 넘겨 아직 머무르는 동물은 그대로 두고, 퇴장 뒤의 다음 방문부터 새 일수를 적용합니다.
  if v_visit.visit_day <> v_today then
    update public.garden_animal_visit_states
    set visit_day = v_today,
        visits_started_today = 0,
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  end if;

  select coalesce(growth_count, 0)
  into v_growth
  from public.garden_profiles
  where id = v_user_id;

  v_growth := coalesce(v_growth, 0);
  v_base_limit := public.garden_animal_visit_limit(v_growth);

  -- 이틀 연속 방문을 시작하지 못했다면, 다음 접속일에는 한 번의 방문 기회를 보정합니다.
  if v_visit.daily_bonus_date = v_today then
    v_bonus := true;
  elsif v_visit.last_visit_started_at is not null
    and v_today - ((v_visit.last_visit_started_at at time zone 'Asia/Seoul')::date) >= 3 then
    v_bonus := true;
    update public.garden_animal_visit_states
    set daily_bonus_date = v_today,
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  end if;

  v_limit := v_base_limit + case when v_bonus then 1 else 0 end;

  -- '다가오는 중'이 예정 시각을 넘겼다면 실제 체류 상태로 바꿉니다.
  if v_visit.state = 'approaching'
    and v_visit.arrives_at is not null
    and v_visit.arrives_at <= v_now then

    v_dwell := case v_visit.animal_kind
      when 'bird' then interval '4 minutes'
      when 'rabbit' then interval '8 minutes'
      when 'squirrel' then interval '10 minutes'
      when 'hedgehog' then interval '15 minutes'
      else interval '8 minutes'
    end;

    update public.garden_animal_visit_states
    set state = 'visiting',
        arrived_at = v_visit.arrives_at,
        leaves_at = v_visit.arrives_at + v_dwell,
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  end if;

  -- 사용자가 정원을 보고 있지 않은 동안 체류 시간이 끝난 경우도,
  -- 다음에 접속했을 때 서버 시각 기준으로 조용히 퇴장 처리합니다.
  if v_visit.state = 'visiting'
    and v_visit.leaves_at is not null
    and v_visit.leaves_at <= v_now then

    update public.garden_animal_visit_states
    set state = 'idle',
        animal_kind = null,
        approach_started_at = null,
        arrives_at = null,
        arrived_at = null,
        next_available_at = v_visit.leaves_at + interval '1 hour',
        last_departed_at = v_visit.leaves_at,
        last_departure_reason = 'timeout',
        trace_expires_at = v_visit.leaves_at + interval '10 minutes',
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  end if;

  -- 조용한 정원이고 다음 방문 시간이 지났을 때만, 화면을 보고 있는 사용자에게
  -- 20~60초 후 도착할 동물을 한 번 정합니다. 새 기기라도 같은 행을 읽으므로 복제되지 않습니다.
  if p_begin_when_ready
    and v_visit.state = 'idle'
    and v_visit.next_available_at <= v_now
    and v_visit.visits_started_today < v_limit then

    case floor(random() * 4)::integer
      when 0 then v_kind := 'bird';
      when 1 then v_kind := 'rabbit';
      when 2 then v_kind := 'squirrel';
      else v_kind := 'hedgehog';
    end case;

    v_delay_seconds := 20 + floor(random() * 41)::integer;

    update public.garden_animal_visit_states
    set state = 'approaching',
        animal_kind = v_kind,
        approach_started_at = v_now,
        arrives_at = v_now + make_interval(secs => v_delay_seconds),
        arrived_at = null,
        leaves_at = null,
        visits_started_today = v_visit.visits_started_today + 1,
        last_visit_started_at = v_now,
        trace_expires_at = null,
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  elsif v_visit.state = 'idle'
    and v_visit.visits_started_today >= v_limit
    and v_visit.next_available_at <= v_now then

    -- 오늘의 방문 기회를 모두 썼으면 다음 한국 날짜 00:00부터 다시 기다립니다.
    v_next_day_start := ((v_today + 1)::timestamp at time zone 'Asia/Seoul');

    update public.garden_animal_visit_states
    set next_available_at = v_next_day_start,
        updated_at = v_now
    where user_id = v_user_id;

    select * into v_visit
    from public.garden_animal_visit_states
    where user_id = v_user_id
    for update;
  end if;

  return query
  select
    v_visit.state,
    v_visit.animal_kind,
    v_visit.approach_started_at,
    v_visit.arrives_at,
    v_visit.leaves_at,
    v_visit.next_available_at,
    v_visit.trace_expires_at,
    v_visit.last_departed_at,
    v_visit.last_departure_reason,
    v_visit.visits_started_today::integer,
    v_limit,
    v_bonus,
    v_now;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_my_garden_dev_animal_visits_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_growth integer := 0;
  v_presence public.garden_dev_animal_v2_presence%rowtype;
  v_was_absent boolean := false;
  v_active_count integer := 0;
  v_changed_count integer := 0;
  v_should_start boolean := false;
  v_force_change boolean := false;
  v_overlap_chance numeric := 0.18;
  v_candidate_kind text;
  v_candidate_zone text;
  v_delay_seconds integer;
  v_next_seconds integer;
  v_variant text := 'normal';
  v_oldest_active_id uuid;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  -- First DEV V2 visit: schedule a small, unannounced delay instead of
  -- showing an animal immediately on page load.
  insert into public.garden_dev_animal_v2_presence (
    user_id,
    last_seen_at,
    last_change_at,
    next_event_at,
    updated_at
  )
  values (
    v_user_id,
    v_now,
    v_now,
    v_now + make_interval(secs => 25 + floor(random() * 76)::integer),
    v_now
  )
  on conflict (user_id) do nothing;

  select *
    into v_presence
  from public.garden_dev_animal_v2_presence
  where user_id = v_user_id
  for update;

  -- If no device has watched this garden for a while, do not replay an old
  -- visit on the next open. Clear the old visual state and begin a fresh,
  -- unannounced forest rhythm instead.
  v_was_absent := v_presence.last_seen_at < v_now - interval '100 seconds';

  if v_was_absent then
    delete from public.garden_dev_animal_v2_visits
    where user_id = v_user_id;

    update public.garden_dev_animal_v2_presence
    set last_seen_at = v_now,
        last_change_at = v_now,
        next_event_at = v_now + make_interval(secs => 25 + floor(random() * 76)::integer),
        last_animal_kind = null,
        last_animal_departed_at = null,
        updated_at = v_now
    where user_id = v_user_id;
  else
    update public.garden_dev_animal_v2_presence
    set last_seen_at = v_now,
        updated_at = v_now
    where user_id = v_user_id;
  end if;

  select *
    into v_presence
  from public.garden_dev_animal_v2_presence
  where user_id = v_user_id
  for update;

  select coalesce(growth_count, 0)
    into v_growth
  from public.garden_profiles
  where id = v_user_id;

  v_growth := coalesce(v_growth, 0);

  -- The initial call after a genuine absence only starts a new quiet rhythm.
  -- A later visible-tab sync creates the first approach when it is due.
  if not v_was_absent then
    -- Arrival: the animal has reached its spot.
    update public.garden_dev_animal_v2_visits
    set visit_state = 'visiting',
        arrived_at = coalesce(arrives_at, v_now),
        updated_at = v_now
    where user_id = v_user_id
      and visit_state = 'approaching'
      and arrives_at is not null
      and arrives_at <= v_now;
    get diagnostics v_changed_count = row_count;

    if v_changed_count > 0 then
      update public.garden_dev_animal_v2_presence
      set last_change_at = v_now,
          updated_at = v_now
      where user_id = v_user_id;
    end if;

    -- Natural departure begins. The client receives this short departing state
    -- and can play the species-specific exit animation.
    update public.garden_dev_animal_v2_visits
    set visit_state = 'departing',
        departing_at = v_now,
        departure_reason = 'timeout',
        trace_kind = null,
        trace_expires_at = null,
        updated_at = v_now
    where user_id = v_user_id
      and visit_state = 'visiting'
      and leaves_at is not null
      and leaves_at <= v_now;
    get diagnostics v_changed_count = row_count;

    if v_changed_count > 0 then
      update public.garden_dev_animal_v2_presence
      set last_change_at = v_now,
          last_animal_departed_at = v_now,
          updated_at = v_now
      where user_id = v_user_id;
    end if;

    -- A letter departure only needs its short exit animation. It leaves no
    -- trace. Natural departures become a quiet species-specific trace.
    delete from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state = 'departing'
      and departure_reason = 'letter'
      and departing_at <= v_now - interval '1500 milliseconds';

    update public.garden_dev_animal_v2_visits
    set visit_state = 'trace',
        trace_kind = public.garden_dev_animal_v2_trace_for_kind(animal_kind),
        trace_expires_at = v_now + make_interval(secs => 150 + floor(random() * 211)::integer),
        updated_at = v_now
    where user_id = v_user_id
      and visit_state = 'departing'
      and departure_reason = 'timeout'
      and departing_at <= v_now - interval '1500 milliseconds';
    get diagnostics v_changed_count = row_count;

    if v_changed_count > 0 then
      update public.garden_dev_animal_v2_presence
      set last_change_at = v_now,
          updated_at = v_now
      where user_id = v_user_id;
    end if;

    delete from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state = 'trace'
      and trace_expires_at is not null
      and trace_expires_at <= v_now;

    select *
      into v_presence
    from public.garden_dev_animal_v2_presence
    where user_id = v_user_id
    for update;

    select count(*)
      into v_active_count
    from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state in ('approaching', 'visiting', 'departing');

    -- Growth changes the chance of special overlap / glimmer visits, not the
    -- baseline frequency. Every forest remains alive from day one.
    v_overlap_chance := case
      when v_growth <= 6 then 0.18
      when v_growth <= 13 then 0.28
      when v_growth <= 20 then 0.42
      when v_growth <= 29 then 0.52
      else 0.62
    end;

    v_force_change := v_now >= v_presence.last_change_at + interval '4 minutes 20 seconds';

    if v_active_count < 2
       and (v_now >= v_presence.next_event_at or v_force_change) then
      if v_active_count = 0 then
        v_should_start := true;
      elsif v_force_change then
        v_should_start := true;
      else
        v_should_start := random() < v_overlap_chance;
      end if;

      if v_should_start then
        -- 모든 자연 방문은 한 선택 함수에서 결정합니다. 새 친구는 하루 한 종류만
        -- 처음 발견되며, 오래 만나지 못하면 보이지 않는 우대가 천천히 쌓입니다.
        select picked.animal_kind, picked.habitat_zone
          into v_candidate_kind, v_candidate_zone
        from public.pick_my_garden_animal_v3(
          v_user_id,
          v_growth,
          v_presence.last_animal_kind,
          0.08
        ) as picked
        limit 1;

        if v_candidate_kind is not null then
          v_delay_seconds := 18 + floor(random() * 58)::integer; -- 18–75 sec
          v_variant := case
            when v_growth >= 30 and random() < 0.18 then 'glimmer'
            when v_growth >= 21 and random() < 0.10 then 'glimmer'
            else 'normal'
          end;

          -- The initial natural dwell windows are intentionally shorter than
          -- V1's long fixed stays so arrivals and departures remain lively.
          -- They are still species-flavoured and can be tuned later without
          -- touching the client protocol.
          insert into public.garden_dev_animal_v2_visits (
            user_id,
            animal_kind,
            habitat_zone,
            visit_state,
            visit_variant,
            approach_started_at,
            arrives_at,
            leaves_at,
            created_at,
            updated_at
          )
          values (
            v_user_id,
            v_candidate_kind,
            v_candidate_zone,
            'approaching',
            v_variant,
            v_now,
            v_now + make_interval(secs => v_delay_seconds),
            (v_now + make_interval(secs => v_delay_seconds))
              + case v_candidate_kind
                  when 'bird' then make_interval(secs => 150 + floor(random() * 151)::integer)       -- 2.5–5 min
                  when 'owl' then make_interval(secs => 180 + floor(random() * 151)::integer)        -- 3–5.5 min
                  when 'rabbit' then make_interval(secs => 210 + floor(random() * 181)::integer)     -- 3.5–6.5 min
                  when 'fox' then make_interval(secs => 220 + floor(random() * 181)::integer)        -- 3.7–6.7 min
                  when 'squirrel' then make_interval(secs => 240 + floor(random() * 181)::integer)   -- 4–7 min
                  when 'raccoon' then make_interval(secs => 250 + floor(random() * 191)::integer)    -- 4.2–7.3 min
                  when 'hedgehog' then make_interval(secs => 270 + floor(random() * 211)::integer)   -- 4.5–8 min
                  when 'mole' then make_interval(secs => 300 + floor(random() * 211)::integer)       -- 5–8.5 min
                end,
            v_now,
            v_now
          );

          -- A fresh animal clears any old passive traces. The trace remains
          -- visible only during a quiet gap, as planned in the V2 design.
          delete from public.garden_dev_animal_v2_visits
          where user_id = v_user_id
            and visit_state = 'trace';

          v_next_seconds := 45 + floor(random() * 166)::integer; -- 45–210 sec
          update public.garden_dev_animal_v2_presence
          set last_change_at = v_now,
              next_event_at = v_now + make_interval(secs => v_next_seconds),
              last_animal_kind = v_candidate_kind,
              updated_at = v_now
          where user_id = v_user_id;
        end if;
      else
        -- A second animal was skipped this time. Leave another unpredictable
        -- chance soon, without exposing a countdown to the user.
        update public.garden_dev_animal_v2_presence
        set next_event_at = v_now + make_interval(secs => 45 + floor(random() * 96)::integer),
            updated_at = v_now
        where user_id = v_user_id;
      end if;
    elsif v_active_count >= 2 and v_now >= v_presence.next_event_at then
      -- Both visual slots are occupied. Let their scheduled departures create
      -- the next change, but do not keep a stale due timestamp around.
      update public.garden_dev_animal_v2_presence
      set next_event_at = v_now + make_interval(secs => 45 + floor(random() * 96)::integer),
          updated_at = v_now
      where user_id = v_user_id;
    end if;

    -- If two long stays happen to fill both slots and no scheduled transition
    -- would occur before the 5-minute rhythm limit, gently let the oldest one
    -- begin a natural departure. This is invisible as a rule to the user.
    select count(*)
      into v_active_count
    from public.garden_dev_animal_v2_visits
    where user_id = v_user_id
      and visit_state in ('approaching', 'visiting', 'departing');

    if v_active_count >= 2 then
      select id
        into v_oldest_active_id
      from public.garden_dev_animal_v2_visits
      where user_id = v_user_id
        and visit_state = 'visiting'
      order by arrived_at nulls last, created_at
      limit 1;

      select *
        into v_presence
      from public.garden_dev_animal_v2_presence
      where user_id = v_user_id
      for update;

      if v_oldest_active_id is not null
         and v_now >= v_presence.last_change_at + interval '4 minutes 20 seconds' then
        update public.garden_dev_animal_v2_visits
        set visit_state = 'departing',
            departing_at = v_now,
            departure_reason = 'timeout',
            trace_kind = null,
            trace_expires_at = null,
            updated_at = v_now
        where id = v_oldest_active_id;

        update public.garden_dev_animal_v2_presence
        set last_change_at = v_now,
            last_animal_departed_at = v_now,
            updated_at = v_now
        where user_id = v_user_id;
      end if;
    end if;
  end if;

  select jsonb_build_object(
    'server_now', v_now,
    'last_change_at', p.last_change_at,
    'visits', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'visit_id', v.id,
            'animal_kind', v.animal_kind,
            'habitat_zone', v.habitat_zone,
            'visit_state', v.visit_state,
            'visit_variant', v.visit_variant,
            'approach_started_at', v.approach_started_at,
            'arrives_at', v.arrives_at,
            'arrived_at', v.arrived_at,
            'leaves_at', v.leaves_at,
            'departing_at', v.departing_at,
            'departure_reason', v.departure_reason,
            'trace_kind', v.trace_kind,
            'trace_expires_at', v.trace_expires_at
          )
          order by
            case v.visit_state
              when 'approaching' then 1
              when 'visiting' then 2
              when 'departing' then 3
              else 4
            end,
            v.created_at
        )
        from public.garden_dev_animal_v2_visits v
        where v.user_id = v_user_id
      ),
      '[]'::jsonb
    )
  )
  into v_result
  from public.garden_dev_animal_v2_presence p
  where p.user_id = v_user_id;

  return coalesce(
    v_result,
    jsonb_build_object('server_now', v_now, 'last_change_at', v_now, 'visits', '[]'::jsonb)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_my_garden_special_friend_state()
 RETURNS TABLE(friend_key text, progress_count integer, target_count integer, today_counted boolean, is_ready boolean, meeting_started boolean, is_met boolean, started_at timestamp with time zone, ready_at timestamp with time zone, meeting_started_at timestamp with time zone, met_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_today_start timestamptz :=
    ((now() at time zone 'Asia/Seoul')::date::timestamp at time zone 'Asia/Seoul');
  v_earliest_record_at timestamptz;
  v_progress_count integer := 0;
  v_legacy_growth_count integer := 0;
  v_effective_progress integer := 0;
begin
  if v_user_id is null then
    raise exception 'AUTH_REQUIRED';
  end if;

  select min(r.created_at)
    into v_earliest_record_at
  from public.garden_records as r
  where r.user_id = v_user_id;

  select coalesce(gp.growth_count, 0)::integer
    into v_legacy_growth_count
  from public.garden_profiles as gp
  where gp.id = v_user_id;

  insert into public.garden_special_friend_profiles (
    user_id,
    friend_key,
    started_at,
    created_at,
    updated_at
  )
  values (
    v_user_id,
    'forest_unicorn',
    coalesce(v_earliest_record_at, v_today_start),
    now(),
    now()
  )
  on conflict (user_id) do update
  set started_at = least(
        public.garden_special_friend_profiles.started_at,
        excluded.started_at
      ),
      updated_at = now();

  insert into public.garden_special_friend_day_records (
    user_id,
    record_date,
    source_type,
    source_record_id,
    created_at
  )
  select
    v_user_id,
    src.record_date,
    'garden_record',
    src.record_id,
    src.created_at
  from (
    select distinct on ((r.created_at at time zone 'Asia/Seoul')::date)
      (r.created_at at time zone 'Asia/Seoul')::date as record_date,
      r.id as record_id,
      r.created_at
    from public.garden_records as r
    where r.user_id = v_user_id
    order by
      (r.created_at at time zone 'Asia/Seoul')::date,
      r.created_at asc
  ) as src
  on conflict (user_id, record_date) do nothing;

  select count(*)::integer
    into v_progress_count
  from public.garden_special_friend_day_records as d
  where d.user_id = v_user_id;

  v_effective_progress :=
    greatest(v_progress_count, coalesce(v_legacy_growth_count, 0));

  update public.garden_special_friend_profiles as sfp
  set ready_at = case
        when v_effective_progress >= 3
          then coalesce(sfp.ready_at, now())
        else sfp.ready_at
      end,
      updated_at = now()
  where sfp.user_id = v_user_id;

  return query
  select
    sfp.friend_key,
    least(v_effective_progress, 3)::integer,
    3::integer,
    exists (
      select 1
      from public.garden_special_friend_day_records as d
      where d.user_id = v_user_id
        and d.record_date = v_today
    ),
    (sfp.ready_at is not null),
    (sfp.meeting_started_at is not null),
    (sfp.met_at is not null),
    sfp.started_at,
    sfp.ready_at,
    sfp.meeting_started_at,
    sfp.met_at
  from public.garden_special_friend_profiles as sfp
  where sfp.user_id = v_user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tree_animal_call_install_status_v1()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'visit_table', to_regclass('public.garden_dev_animal_v2_visits') is not null,
    'presence_table', to_regclass('public.garden_dev_animal_v2_presence') is not null,
    'state_table', to_regclass('public.garden_tree_animal_call_state_v1') is not null,
    'sync_rpc', to_regprocedure('public.sync_my_garden_dev_animal_visits_v2()') is not null,
    'send_rpc', to_regprocedure('public.send_garden_letter_with_dev_animal_v2(uuid,uuid,text,text)') is not null,
    'status_rpc', to_regprocedure('public.get_my_garden_tree_call_status_v1()') is not null,
    'call_rpc', to_regprocedure('public.call_my_garden_animal_with_tree_v1(uuid)') is not null,
    'presence_speed_trigger', exists (
      select 1 from pg_trigger
      where tgrelid = 'public.garden_dev_animal_v2_presence'::regclass
        and tgname = 'garden_animal_v2_presence_speed_v1'
        and not tgisinternal
    ),
    'approach_speed_trigger', exists (
      select 1 from pg_trigger
      where tgrelid = 'public.garden_dev_animal_v2_visits'::regclass
        and tgname = 'garden_animal_v2_approach_speed_v1'
        and not tgisinternal
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.upsert_my_garden_shared_tree_note(p_tree_id uuid, p_body text)
 RETURNS TABLE(tree_id uuid, author_id uuid, note_body text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_body text := btrim(coalesce(p_body, ''));
  v_tree public.garden_shared_trees%rowtype;
begin
  if v_me is null then
    raise exception 'LOGIN_REQUIRED';
  end if;

  if p_tree_id is null then
    raise exception 'SHARED_TREE_NOT_FOUND';
  end if;

  if char_length(v_body) < 1 then
    raise exception 'SHARED_TREE_NOTE_REQUIRED';
  end if;

  if char_length(v_body) > 40 then
    raise exception 'SHARED_TREE_NOTE_TOO_LONG';
  end if;

  select t.*
  into v_tree
  from public.garden_shared_trees t
  where t.id = p_tree_id
    and v_me in (t.user_one_id, t.user_two_id)
    and t.relationship_ended_at is null
  for share;

  if not found then
    raise exception 'SHARED_TREE_NOT_FOUND';
  end if;

  if v_tree.completed_at is null then
    raise exception 'SHARED_TREE_NOT_COMPLETED';
  end if;

  insert into public.garden_shared_tree_notes as n (
    tree_id,
    user_id,
    body
  )
  values (
    p_tree_id,
    v_me,
    v_body
  )
  on conflict on constraint garden_shared_tree_notes_one_per_person
  do update
    set body = excluded.body,
        updated_at = now();

  return query
  select
    n.tree_id,
    n.user_id,
    n.body,
    n.created_at,
    n.updated_at
  from public.garden_shared_tree_notes n
  where n.tree_id = p_tree_id
    and n.user_id = v_me;
end;
$function$;

-- Added after metadata export: protected admin statistics RPC
-- TodayForest admin statistics RPC.
-- Replaces the browser-visible Apps Script summary endpoint/key on /admin.html.
-- Safe to run repeatedly.

create or replace function public.get_todayforest_admin_stats(
  p_range text default 'all'
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $function$
declare
  v_range text := lower(trim(coalesce(p_range, 'all')));
  v_start timestamptz;
  v_mood_count bigint := 0;
  v_letter_count bigint := 0;
  v_friend_count bigint := 0;
begin
  if coalesce(public.get_my_garden_feedback_admin_access(), false) is not true then
    raise exception 'ADMIN_REQUIRED' using errcode = '42501';
  end if;

  if v_range = 'all' then
    v_start := null;
  elsif v_range = 'today' then
    v_start := date_trunc('day', now() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul';
  elsif v_range = 'last7' then
    v_start := (date_trunc('day', now() at time zone 'Asia/Seoul') - interval '6 days') at time zone 'Asia/Seoul';
  else
    raise exception 'INVALID_RANGE' using errcode = '22023';
  end if;

  select count(*)
  into v_mood_count
  from public.garden_records r
  where v_start is null or r.created_at >= v_start;

  select count(*)
  into v_letter_count
  from public.garden_letters l
  where v_start is null or l.sent_at >= v_start;

  select count(*)
  into v_friend_count
  from (
    select least(f.user_id, f.friend_id) as user_one_id,
           greatest(f.user_id, f.friend_id) as user_two_id
    from public.garden_friendships f
    where v_start is null or f.created_at >= v_start
    group by 1, 2
  ) pairs;

  return jsonb_build_object(
    'ok', true,
    'range', v_range,
    'updated_at', now(),
    'summary', jsonb_build_object(
      'garden_mood_saved', v_mood_count,
      'garden_letter_sent', v_letter_count,
      'garden_friend_connected', v_friend_count
    )
  );
end;
$function$;

