-- Policies captured from pg_policies
create policy "garden animal codex select own" on public."garden_animal_codex_visits" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));
create policy "decoration items readable" on public."garden_decoration_items" as PERMISSIVE for SELECT to "authenticated" using (is_active);
create policy "users read own recipe exchanges" on public."garden_decoration_recipe_exchanges" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));
create policy "decoration recipes readable" on public."garden_decoration_recipes" as PERMISSIVE for SELECT to "authenticated" using (is_enabled);
create policy "garden dev animal v2: read my presence" on public."garden_dev_animal_v2_presence" as PERMISSIVE for SELECT to public using ((auth.uid() = user_id));
create policy "garden dev animal v2: read my visits" on public."garden_dev_animal_v2_visits" as PERMISSIVE for SELECT to public using ((auth.uid() = user_id));
create policy "garden dev found item: read my items" on public."garden_dev_found_items" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));
create policy "garden_dev_trade_items_select_own" on public."garden_dev_trade_items" as PERMISSIVE for SELECT to public using ((user_id = auth.uid()));
create policy "garden_dev_trade_items_update_own" on public."garden_dev_trade_items" as PERMISSIVE for UPDATE to public using ((user_id = auth.uid())) with check ((user_id = auth.uid()));
create policy "garden_dev_trade_offers_select_own" on public."garden_dev_trade_offers" as PERMISSIVE for SELECT to public using ((user_id = auth.uid()));
create policy "garden found item: read my items" on public."garden_found_items" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));
create policy "garden letter: mark my letter read" on public."garden_letters" as PERMISSIVE for UPDATE to "authenticated" using (((( SELECT auth.uid() AS uid) = recipient_id) AND (returned_at IS NULL))) with check (((( SELECT auth.uid() AS uid) = recipient_id) AND (returned_at IS NULL)));
create policy "garden letter: read my letters" on public."garden_letters" as PERMISSIVE for SELECT to "authenticated" using (((( SELECT auth.uid() AS uid) = recipient_id) AND (returned_at IS NULL)));
create policy "garden profile: create my garden" on public."garden_profiles" as PERMISSIVE for INSERT to "authenticated" with check ((( SELECT auth.uid() AS uid) = id));
create policy "garden profile: read my garden" on public."garden_profiles" as PERMISSIVE for SELECT to "authenticated" using ((( SELECT auth.uid() AS uid) = id));
create policy "garden profile: update my garden" on public."garden_profiles" as PERMISSIVE for UPDATE to "authenticated" using ((( SELECT auth.uid() AS uid) = id)) with check ((( SELECT auth.uid() AS uid) = id));
create policy "garden record: add my record" on public."garden_records" as PERMISSIVE for INSERT to "authenticated" with check ((( SELECT auth.uid() AS uid) = user_id));
create policy "garden record: read my records" on public."garden_records" as PERMISSIVE for SELECT to "authenticated" using ((( SELECT auth.uid() AS uid) = user_id));
create policy "oot_acorn_transactions_select_own" on public."oot_acorn_transactions" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));
create policy "oot_acorn_wallets_select_own" on public."oot_acorn_wallets" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));
create policy "oot_invites_participant_select" on public."oot_invites" as PERMISSIVE for SELECT to "authenticated" using (((auth.uid() = from_user_id) OR (auth.uid() = to_user_id)));
create policy "oot_actions_participant_select" on public."oot_match_actions" as PERMISSIVE for SELECT to "authenticated" using ((EXISTS ( SELECT 1
   FROM oot_matches m
  WHERE ((m.id = oot_match_actions.match_id) AND ((auth.uid() = m.player_one_id) OR (auth.uid() = m.player_two_id))))));
create policy "oot_match_chat_messages_select_participants" on public."oot_match_chat_messages" as PERMISSIVE for SELECT to "authenticated" using (oot_match_chat_series_is_open(series_id, auth.uid()));
create policy "oot_matches_participant_select" on public."oot_matches" as PERMISSIVE for SELECT to "authenticated" using (((auth.uid() = player_one_id) OR (auth.uid() = player_two_id)));
create policy "oot_player_game_records_select_own" on public."oot_player_game_records" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));
create policy "oot_player_profiles_select_own" on public."oot_player_profiles" as PERMISSIVE for SELECT to "authenticated" using ((user_id = auth.uid()));
create policy "oot_player_stats_own_select" on public."oot_player_stats" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));
create policy "oot_point_ledger_own_select" on public."oot_point_ledger" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));
create policy "oot_reward_unlocks_own_select" on public."oot_reward_unlocks" as PERMISSIVE for SELECT to "authenticated" using ((auth.uid() = user_id));

