-- ---- 6) ordinary triggers ----
CREATE TRIGGER garden_animal_v2_presence_speed_v1 BEFORE INSERT OR UPDATE OF next_event_at ON garden_dev_animal_v2_presence FOR EACH ROW EXECUTE FUNCTION garden_animal_v2_presence_speed_v1();
CREATE TRIGGER garden_animal_codex_visit_v1 AFTER INSERT OR UPDATE OF visit_state, arrived_at ON garden_dev_animal_v2_visits FOR EACH ROW EXECUTE FUNCTION record_garden_animal_codex_visit_v1();
CREATE TRIGGER garden_animal_v2_approach_speed_v1 BEFORE INSERT OR UPDATE OF visit_state, arrives_at, leaves_at ON garden_dev_animal_v2_visits FOR EACH ROW EXECUTE FUNCTION garden_animal_v2_approach_speed_v1();
CREATE TRIGGER garden_feedback_operator_reply_timestamp BEFORE UPDATE OF operator_reply ON garden_feedback FOR EACH ROW EXECUTE FUNCTION set_garden_feedback_operator_reply_timestamp();
CREATE TRIGGER garden_profiles_set_updated_at BEFORE UPDATE ON garden_profiles FOR EACH ROW EXECUTE FUNCTION set_todayforest_updated_at();
CREATE TRIGGER garden_profiles_tree_name_locked BEFORE UPDATE OF tree_name ON garden_profiles FOR EACH ROW EXECUTE FUNCTION lock_garden_tree_name_after_first_save();
CREATE TRIGGER garden_records_add_special_friend_day AFTER INSERT ON garden_records FOR EACH ROW EXECUTE FUNCTION add_garden_special_friend_day_for_record();
CREATE TRIGGER oot_award_finished_match_acorns_trigger AFTER UPDATE OF status ON oot_matches FOR EACH ROW WHEN (old.status IS DISTINCT FROM new.status AND new.status = 'finished'::text) EXECUTE FUNCTION _oot_award_finished_match_acorns();
CREATE TRIGGER oot_player_stats_touch_updated_at BEFORE UPDATE ON oot_player_stats FOR EACH ROW EXECUTE FUNCTION oot_touch_player_stats_updated_at();

-- Push webhook intentionally omitted: its historical trigger snapshot contained a privileged credential.
-- Restore the webhook only after configuring OOT_PUSH_WEBHOOK_SECRET. See README.md.

-- Standardized RLS auto-enable event trigger (the function existed in the live snapshot).
drop event trigger if exists todayforest_rls_auto_enable;
create event trigger todayforest_rls_auto_enable on ddl_command_end when tag in ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO') execute function public.rls_auto_enable();

